insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('inv-001', 'What does owning a share of stock give you?', '["A loan to the company","Partial ownership of the company","A guaranteed dividend","A bond from the company"]'::jsonb, 1, 'A share of stock represents partial equity ownership in a company.', 'Investing basics', 'Basic', null),
  ('inv-002', 'Which of these is an asset class?', '["Tesla","Bonds","The Dow Jones","E*TRADE"]'::jsonb, 1, 'Bonds are an asset class. Tesla is a security, the Dow is an index, and E*TRADE is a broker.', 'Investing basics', 'Basic', null),
  ('inv-003', 'What is a portfolio?', '["A single high-conviction stock","The full collection of investments owned by a person or institution","A document tracking dividends","A type of mutual fund"]'::jsonb, 1, 'A portfolio is the entire group of investments held by an investor.', 'Investing basics', 'Basic', null),
  ('inv-004', 'Which best describes diversification?', '["Owning only blue-chip stocks","Spreading investments across many assets to reduce risk","Holding cash to wait for a crash","Trading frequently to catch winners"]'::jsonb, 1, 'Diversification spreads risk so that no single holding can devastate the portfolio.', 'Investing basics', 'Basic', null),
  ('inv-005', 'What is compounding?', '["Reinvesting earnings so they generate their own returns","Selling at the top","Borrowing to invest more","Paying off margin debt"]'::jsonb, 0, 'Compounding is the snowball effect of returns earning returns over time.', 'Investing basics', 'Basic', null),
  ('inv-006', 'Which asset is the most liquid?', '["A duplex rental","Cash in a checking account","Private equity in a startup","Fine art"]'::jsonb, 1, 'Cash is the most liquid asset — it can be spent immediately with no conversion.', 'Investing basics', 'Basic', null),
  ('inv-007', 'What does a dividend represent?', '["Interest on a loan","A cash or stock payment to shareholders from company profits","A capital gain","A tax deduction"]'::jsonb, 1, 'Dividends are payments companies make to shareholders, typically from earnings.', 'Investing basics', 'Basic', null),
  ('inv-008', 'Which is generally considered the safest of these for a 1-year holding?', '["Individual small-cap stocks","Long-dated corporate bonds","Short-term Treasury bills","Cryptocurrencies"]'::jsonb, 2, 'Short-term Treasury bills are backed by the US government and have minimal price risk over a year.', 'Investing basics', 'Basic', null),
  ('inv-009', 'What does "yield" measure?', '["Total price appreciation","Income an investment generates relative to its price","Annual fees charged","Market capitalization"]'::jsonb, 1, 'Yield expresses income (interest or dividends) as a percentage of price.', 'Investing basics', 'Basic', null),
  ('inv-010', 'What is a capital gain?', '["A dividend payment","The profit when an asset is sold above its purchase price","A type of bond coupon","Interest from a savings account"]'::jsonb, 1, 'A capital gain is the realized profit between purchase and sale prices.', 'Investing basics', 'Basic', null),
  ('inv-011', 'Which describes "buy and hold"?', '["Day trading every day","Holding investments through cycles for the long term","Rotating sectors monthly","Buying only on dips"]'::jsonb, 1, 'Buy-and-hold ignores short-term moves and holds for the long term.', 'Investing basics', 'Basic', null),
  ('inv-012', 'What is dollar-cost averaging?', '["Investing a fixed amount on a regular schedule","Buying only when prices fall 10%","Selling half on every rally","Hedging with options"]'::jsonb, 0, 'DCA spreads purchases over time to reduce timing risk.', 'Investing basics', 'Beginner', null),
  ('inv-013', 'Why does time horizon matter?', '["It determines tax bracket","It shapes how much risk a portfolio can take","It sets the dividend rate","It''s required for margin accounts"]'::jsonb, 1, 'Longer horizons let portfolios recover from volatility, so they can hold more risk.', 'Investing basics', 'Beginner', null),
  ('inv-014', 'Which best defines risk tolerance?', '["A fund''s average return","An investor''s emotional and financial ability to withstand losses","The maximum drawdown of an index","A regulatory rating"]'::jsonb, 1, 'Risk tolerance is the investor''s capacity to handle volatility and loss.', 'Investing basics', 'Beginner', null),
  ('inv-015', 'What is asset allocation?', '["Trading individual stocks","The mix of asset classes (stocks, bonds, cash) in a portfolio","A fund''s expense ratio","The order in which assets are sold"]'::jsonb, 1, 'Asset allocation is the percentage split across asset classes.', 'Investing basics', 'Beginner', null),
  ('inv-016', 'What is rebalancing?', '["Adding new money to a portfolio","Restoring a portfolio to target weights after drift","Liquidating to cash","Switching brokers"]'::jsonb, 1, 'Rebalancing trims overweight positions and adds to underweight ones to restore the target allocation.', 'Investing basics', 'Beginner', null),
  ('inv-017', 'Which usually has higher long-term return but more volatility?', '["Treasury bills","Corporate bonds","Equities","Money market funds"]'::jsonb, 2, 'Equities historically deliver higher long-term returns at the cost of greater short-term volatility.', 'Investing basics', 'Beginner', null),
  ('inv-018', 'What does "principal" mean in investing?', '["The interest earned","The original amount invested or borrowed","The portfolio manager","The current market value"]'::jsonb, 1, 'Principal is the original capital, separate from any returns or interest.', 'Investing basics', 'Beginner', null),
  ('inv-019', 'What is a "total return"?', '["Only the dividend income","Only the price change","Price change plus income (dividends/interest)","After-tax return only"]'::jsonb, 2, 'Total return combines price appreciation and income.', 'Investing basics', 'Beginner', null),
  ('inv-020', 'Which is an example of a fixed-income security?', '["Common stock","Corporate bond","ETF tracking the S&P 500","Bitcoin"]'::jsonb, 1, 'Bonds pay fixed interest, making them fixed-income.', 'Investing basics', 'Beginner', null),
  ('inv-021', 'What is inflation?', '["A rise in interest rates","A general rise in prices over time","A fall in stock prices","A central bank surplus"]'::jsonb, 1, 'Inflation is the broad increase in the price level of goods and services.', 'Investing basics', 'Beginner', null),
  ('inv-022', 'What is real return?', '["Nominal return minus inflation","Return before fees","Return before taxes","Return on real estate"]'::jsonb, 0, 'Real return is the inflation-adjusted return — what you actually gained in purchasing power.', 'Investing basics', 'Beginner', null),
  ('inv-023', 'Which behavior is generally rewarded over decades?', '["Frequent trading on news","Staying invested through downturns","Holding only cash","Chasing yesterday''s winners"]'::jsonb, 1, 'Long-term, disciplined holding consistently beats reactive trading on average.', 'Investing basics', 'Beginner', null),
  ('inv-024', 'Which best describes an index fund?', '["A fund that picks individual winners","A fund designed to track a market index","A fund that only buys IPOs","A leveraged ETF"]'::jsonb, 1, 'Index funds mechanically track a basket like the S&P 500.', 'Investing basics', 'Beginner', null),
  ('inv-025', 'Which goal is most aligned with growth investing?', '["Maximize current income","Maximize long-term capital appreciation","Minimize tax bills","Match short-term spending needs"]'::jsonb, 1, 'Growth investing prioritizes price appreciation over current yield.', 'Investing basics', 'Beginner', null),
  ('inv-026', 'What is a "safe-haven" asset?', '["An asset that tends to hold value during market stress","An asset with no taxes","Any large-cap stock","An IPO"]'::jsonb, 0, 'Safe-haven assets like gold and Treasuries are sought during turmoil.', 'Investing basics', 'Beginner', null),
  ('inv-027', 'Which is generally the worst environment for long-term bonds?', '["Falling interest rates","Rising interest rates","Stable rates","Deflation"]'::jsonb, 1, 'Rising rates push existing bond prices down because their fixed coupons become less attractive.', 'Investing basics', 'Beginner', null),
  ('inv-028', 'Why are fees important?', '["Fees only matter in IPOs","High fees compound and meaningfully reduce long-term returns","Fees are tax-deductible","Fees are unrelated to returns"]'::jsonb, 1, 'Even a 1% fee can cut decades of returns by tens of percent due to compounding.', 'Investing basics', 'Beginner', null),
  ('inv-029', 'What is an expense ratio?', '["The fund''s distribution yield","Annual fund operating cost expressed as a percentage of assets","The bid-ask spread","The fund''s beta"]'::jsonb, 1, 'The expense ratio is the annual cost of owning a fund, charged against assets.', 'Investing basics', 'Beginner', null),
  ('inv-030', 'Which investment offers the highest historical long-term return?', '["Cash savings","Long-dated US Treasuries","US stocks","Gold"]'::jsonb, 2, 'US stocks have historically delivered the highest long-run returns of these options.', 'Investing basics', 'Beginner', null),
  ('inv-031', 'If you invest $10,000 at a 7% annual compounded return, roughly what''s it worth in 30 years?', '["~$20,000","~$45,000","~$76,000","~$300,000"]'::jsonb, 2, 'By the rule of 72, money doubles ~every 10 years at 7%, so 30 years ≈ 8×… ~$76k after compounding precisely.', 'Investing basics', 'Intermediate', null),
  ('inv-032', 'The "rule of 72" estimates what?', '["A fund''s beta","How many years to double your money at a given rate","Maximum allowed leverage","The risk-free rate"]'::jsonb, 1, '72 divided by the annual return rate ≈ years to double.', 'Investing basics', 'Intermediate', null),
  ('inv-033', 'Which is true about taxable vs tax-advantaged accounts?', '["They are taxed identically","Tax-advantaged accounts (IRA, 401(k)) defer or eliminate certain taxes","Brokerage accounts have lower fees","Roth IRAs have no contribution limits"]'::jsonb, 1, 'Tax-advantaged accounts shield growth or contributions from taxes within the account.', 'Investing basics', 'Intermediate', null),
  ('inv-034', 'Which is the biggest threat to a long-term retirement plan?', '["Single-day drawdowns","A multi-decade gap between contributions and withdrawals being unfunded","Quarterly volatility","Dividend cuts"]'::jsonb, 1, 'Under-saving relative to a 20-30 year liability is the dominant retirement risk.', 'Investing basics', 'Intermediate', null),
  ('inv-035', 'What is the "risk-free rate"?', '["A guaranteed stock return","The yield on short-term government debt","A regulated bond ceiling","The Fed funds target"]'::jsonb, 1, 'It''s typically the yield on short-term Treasury bills.', 'Investing basics', 'Intermediate', null),
  ('inv-036', 'Which is true about volatility and risk?', '["Volatility is always risk","Volatility is one common measure of risk but not the only one","Risk and volatility are unrelated","Risk only matters in bonds"]'::jsonb, 1, 'Volatility is a proxy for risk but doesn''t capture risks like permanent loss or liquidity drought.', 'Investing basics', 'Intermediate', null),
  ('inv-037', 'What is a benchmark?', '["A target price","A reference index used to evaluate a portfolio''s performance","A regulatory limit","A type of bond"]'::jsonb, 1, 'Benchmarks like the S&P 500 are used to judge whether a portfolio beat the market.', 'Investing basics', 'Intermediate', null),
  ('inv-038', 'Which describes "alpha"?', '["Total return","Excess return above the benchmark","The dividend yield","Implied volatility"]'::jsonb, 1, 'Alpha is the return a manager earns above their benchmark, adjusted for risk.', 'Investing basics', 'Intermediate', null),
  ('inv-039', 'What is "beta" in investing?', '["Risk per dollar of return","A stock''s sensitivity to the overall market","A type of derivative","The trading volume"]'::jsonb, 1, 'Beta measures how much a stock moves relative to the market — beta 1.0 moves with the market.', 'Investing basics', 'Intermediate', null),
  ('inv-040', 'Which is the most common cause of poor long-term returns for retail investors?', '["High taxes","Behavioral mistakes — buying high and selling low","Bad luck with dividends","Brokerage fees"]'::jsonb, 1, 'Repeated behavioral mistakes — emotional buying/selling — drive the persistent gap between fund and investor returns.', 'Investing basics', 'Intermediate', null),
  ('inv-041', 'Which is most consistent with passive investing?', '["Frequent rebalancing on technicals","Holding broad index funds long-term","Sector rotation","Pairs trading"]'::jsonb, 1, 'Passive investing favors broad, low-turnover index exposure.', 'Investing basics', 'Intermediate', null),
  ('inv-042', 'What is the typical impact of inflation on cash savings?', '["Increases purchasing power","Has no effect","Erodes purchasing power over time","Doubles the nominal balance"]'::jsonb, 2, 'Inflation steadily reduces what cash can buy.', 'Investing basics', 'Intermediate', null),
  ('inv-043', 'Which is true about Sharpe ratio?', '["Higher is worse","It measures return per unit of total risk","It only applies to bonds","It ignores volatility"]'::jsonb, 1, 'Sharpe = (return − risk-free rate) / volatility. Higher is better.', 'Investing basics', 'Intermediate', null),
  ('inv-044', 'Why does sequence-of-returns risk matter most near retirement?', '["Returns reverse near retirement","Withdrawals during early losses lock in damage","Taxes spike at age 65","Brokerage fees rise"]'::jsonb, 1, 'Losses early in retirement combined with withdrawals deplete principal faster than later losses.', 'Investing basics', 'Intermediate', null),
  ('inv-045', 'Which is true about reinvesting dividends?', '["It always increases tax bills","It accelerates compounding","It''s prohibited in IRAs","It only works in mutual funds"]'::jsonb, 1, 'Reinvesting buys more shares, which then generate their own dividends — accelerating compounding.', 'Investing basics', 'Intermediate', null),
  ('inv-046', 'Which is the best definition of "drawdown"?', '["Annual return","Peak-to-trough decline in portfolio value","Daily volatility","Dividend yield"]'::jsonb, 1, 'Drawdown is the percentage drop from a portfolio''s prior peak.', 'Investing basics', 'Intermediate', null),
  ('inv-047', 'Which is true about correlation in a portfolio?', '["Lower correlation between holdings reduces total risk","Higher correlation is always desirable","Correlation only applies to bonds","Correlation equals beta"]'::jsonb, 0, 'Combining assets with lower correlation smooths overall portfolio volatility.', 'Investing basics', 'Intermediate', null),
  ('inv-048', 'Which is the most common reason investors underperform their own funds?', '["Currency conversion fees","Mistimed buying and selling","Stock splits","Dividend taxes"]'::jsonb, 1, 'Buying after rallies and selling after declines creates a persistent investor-return gap.', 'Investing basics', 'Intermediate', null),
  ('inv-049', 'Which is generally tax-inefficient in a taxable account?', '["A low-turnover index fund","High-yield bond funds","Municipal bonds","Buy-and-hold equities"]'::jsonb, 1, 'High-yield bond funds throw off taxable income each year, hurting after-tax returns in taxable accounts.', 'Investing basics', 'Intermediate', null),
  ('inv-050', 'Which scenario most resembles a "value trap"?', '["A cheap-looking stock with deteriorating fundamentals","A high-multiple growth stock","An index fund","A government bond"]'::jsonb, 0, 'A value trap is a statistically cheap stock whose business is permanently impaired.', 'Investing basics', 'Intermediate', null),
  ('inv-051', 'Which is true about geometric vs arithmetic mean return?', '["They are identical","Geometric mean is always ≥ arithmetic mean","Geometric mean is always ≤ arithmetic mean for variable returns","Only arithmetic mean is used by professionals"]'::jsonb, 2, 'Volatility introduces a "variance drag" that pulls geometric returns below arithmetic averages.', 'Investing basics', 'Advanced', null),
  ('inv-052', 'An investor with a 30-year horizon should generally:', '["Hold mostly cash","Tilt toward equities even with high short-term volatility","Avoid international exposure","Hold only TIPS"]'::jsonb, 1, 'Long horizons let equities dominate; short-term volatility is offset by time.', 'Investing basics', 'Advanced', null),
  ('inv-053', 'Which is true about the "4% rule" for retirement withdrawals?', '["It guarantees never running out of money","It''s a historically-derived rule of thumb that has limitations","It applies only to bond portfolios","It''s a regulatory requirement"]'::jsonb, 1, 'The 4% rule is a useful heuristic but assumes historical patterns hold; it isn''t a guarantee.', 'Investing basics', 'Advanced', null),
  ('inv-054', 'Which scenario most expands the "equity risk premium" empirically?', '["Bull market peaks","Periods after large equity drawdowns","Stable low-vol regimes","High dividend payouts"]'::jsonb, 1, 'After large drawdowns, expected forward equity returns historically rise — widening the premium.', 'Investing basics', 'Advanced', null),
  ('inv-055', 'Which is the most accurate critique of mean-variance optimization?', '["Inputs are precisely known","Outputs are extremely sensitive to small input changes","It always finds the highest-return portfolio","It is risk-neutral"]'::jsonb, 1, 'Mean-variance optimizers are notoriously sensitive to expected-return inputs, producing extreme weights.', 'Investing basics', 'Advanced', null),
  ('inv-056', 'What is the "home country bias"?', '["A regulatory restriction","Investors over-weighting domestic assets relative to global market weights","A tax-loss harvesting strategy","An ESG framework"]'::jsonb, 1, 'Home-country bias is the well-documented tendency to over-allocate to one''s own market.', 'Investing basics', 'Advanced', null),
  ('inv-057', 'Which is true about "factor investing"?', '["It picks individual stocks by name","It targets systematic exposures like value, size, momentum, quality","It''s the same as indexing","It only works with derivatives"]'::jsonb, 1, 'Factor investing systematically tilts toward characteristics that have shown long-term risk premia.', 'Investing basics', 'Advanced', null),
  ('inv-058', 'Which describes "shortfall risk"?', '["The risk of any negative return","The risk of not meeting a specific financial goal","The risk of bond default","The risk of margin call"]'::jsonb, 1, 'Shortfall risk is the probability of failing a specific objective, not just any loss.', 'Investing basics', 'Advanced', null),
  ('inv-059', 'Which is true about international diversification?', '["It always reduces returns","It has historically reduced portfolio volatility, though correlations can spike during crises","It eliminates currency risk","It''s only for institutions"]'::jsonb, 1, 'International exposure adds diversification benefits but correlations rise during global crises.', 'Investing basics', 'Advanced', null),
  ('inv-060', 'Which describes the "endowment effect" in investing?', '["Universities outperform retail","Investors overvalue assets they already own","Donations boost returns","Annuities reduce risk"]'::jsonb, 1, 'The endowment effect is the cognitive bias of overvaluing what you already hold.', 'Investing basics', 'Advanced', null),
  ('inv-061', 'Which is true about "risk parity" strategies?', '["They weight assets equally by dollars","They weight assets to contribute equally to portfolio risk","They eliminate volatility","They only hold bonds"]'::jsonb, 1, 'Risk parity allocates capital so each asset contributes equal risk, typically using leverage on lower-vol assets.', 'Investing basics', 'Advanced', null),
  ('inv-062', 'Which best characterizes "tail risk"?', '["Average daily moves","The risk of rare, severe events","Quarterly volatility","Dividend cuts"]'::jsonb, 1, 'Tail risk is the risk of extreme, low-probability outcomes — large losses or gains.', 'Investing basics', 'Advanced', null),
  ('inv-063', 'Which strategy is most consistent with "convexity"?', '["Holding cash","Owning options whose payoff accelerates with magnitude","Selling far OTM options","Holding bonds to maturity"]'::jsonb, 1, 'Long-option payoffs are convex — they grow faster than linearly with the underlying move.', 'Investing basics', 'Advanced', null),
  ('inv-064', 'Which best describes "path dependence" in returns?', '["The order of returns affects ending wealth when contributing/withdrawing","Returns are determined by the previous day","Bonds always recover","Markets are mean-reverting daily"]'::jsonb, 0, 'With contributions or withdrawals, the sequence of returns — not just the average — drives wealth.', 'Investing basics', 'Advanced', null),
  ('inv-065', 'Which is true about "hindsight bias" in market analysis?', '["Past events look more predictable than they were in real time","Markets are predictable","Bonds are safer than they look","Volatility is constant"]'::jsonb, 0, 'Hindsight bias makes past outcomes seem inevitable, distorting risk perception.', 'Investing basics', 'Advanced', null),
  ('inv-066', 'Which describes "survivorship bias" in fund data?', '["Closed/failed funds drop from indexes, inflating average returns","All funds survive","Failed funds report higher returns","Only crypto funds are affected"]'::jsonb, 0, 'Failed funds disappear from databases, so historical averages overstate the true experience.', 'Investing basics', 'Advanced', null),
  ('inv-067', 'Which is true about "black swan" events in markets?', '["They are common","They are rare, high-impact events that are hard to predict and easy to rationalize afterward","Only emerging markets have them","They never happen in equities"]'::jsonb, 1, 'Per Taleb, black swans are rare outliers with massive impact that look obvious in retrospect.', 'Investing basics', 'Advanced', null),
  ('stk-001', 'What is common stock?', '["Senior debt","Equity ownership with voting rights","A type of bond","A short-term loan"]'::jsonb, 1, 'Common stock represents equity ownership and typically carries voting rights.', 'Stocks & equities', 'Basic', null),
  ('stk-002', 'Which is true about preferred stock?', '["It has no priority over common in dividends","It typically pays a fixed dividend and ranks above common in liquidation","It is the same as a bond","It always has voting rights"]'::jsonb, 1, 'Preferred stock pays a set dividend and is paid before common stock in liquidation.', 'Stocks & equities', 'Basic', null),
  ('stk-003', 'What is market capitalization?', '["Total revenue","Share price × total shares outstanding","Earnings per share","Book value of assets"]'::jsonb, 1, 'Market cap = price per share multiplied by the number of shares outstanding.', 'Stocks & equities', 'Basic', null),
  ('stk-004', 'Which is generally considered a large-cap stock?', '["Market cap under $1 billion","Market cap between $1B-$10B","Market cap above $10 billion","Market cap above $1 trillion only"]'::jsonb, 2, 'Large-cap is generally market cap above $10 billion.', 'Stocks & equities', 'Basic', null),
  ('stk-005', 'What is an IPO?', '["A private company''s first public sale of shares","A bond issuance","An options expiration","A stock split"]'::jsonb, 0, 'An initial public offering is a company''s debut on public markets.', 'Stocks & equities', 'Basic', null),
  ('stk-006', 'What is a stock split?', '["A merger","Dividing existing shares into more shares without changing total value","Issuing new debt","Buying back stock"]'::jsonb, 1, 'A stock split increases share count and lowers per-share price proportionally; total value is unchanged.', 'Stocks & equities', 'Basic', null),
  ('stk-007', 'What does "shares outstanding" mean?', '["Shares held by insiders only","Shares currently held by all investors","Authorized shares only","Treasury shares only"]'::jsonb, 1, 'Outstanding shares are all shares held by the public and insiders combined.', 'Stocks & equities', 'Basic', null),
  ('stk-008', 'Which describes "float"?', '["Cash held by a company","Shares available for trading by the public","Total revenue","Pre-tax earnings"]'::jsonb, 1, 'Float = shares outstanding minus restricted/insider-held shares not freely traded.', 'Stocks & equities', 'Basic', null),
  ('stk-009', 'What is a blue-chip stock?', '["A penny stock","A large, established, financially-stable company''s stock","Any stock that pays dividends","A pre-IPO startup"]'::jsonb, 1, 'Blue chips are large, well-known, financially-stable companies — think Apple, Microsoft, J&J.', 'Stocks & equities', 'Basic', null),
  ('stk-010', 'What does EPS stand for?', '["Equity per share","Earnings per share","Expected profit share","Exchange-priced security"]'::jsonb, 1, 'EPS is earnings per share — net income divided by shares outstanding.', 'Stocks & equities', 'Basic', null),
  ('stk-011', 'If a company has $100M net income and 50M shares, EPS is:', '["$0.50","$2","$5","$50"]'::jsonb, 1, 'EPS = $100M / 50M shares = $2 per share.', 'Stocks & equities', 'Beginner', null),
  ('stk-012', 'A 2-for-1 stock split: $100 stock becomes:', '["$200 stock, half the shares","$50 stock, double the shares","$100 stock with double dividend","$50 stock with no other changes"]'::jsonb, 1, 'In a 2-for-1 split, you get twice the shares at half the price; total value unchanged.', 'Stocks & equities', 'Beginner', null),
  ('stk-013', 'Which is true about dividend yield?', '["Annual dividend ÷ share price","Quarterly dividend × 4","Always above 4%","Equals the bond yield"]'::jsonb, 0, 'Dividend yield = annual dividend per share divided by current price.', 'Stocks & equities', 'Beginner', null),
  ('stk-014', 'Which describes a growth stock?', '["High current yield, slow growth","Expected above-average earnings growth, typically reinvesting profits","A regulated utility","A bond fund"]'::jsonb, 1, 'Growth stocks emphasize fast earnings growth, often paying little or no dividend.', 'Stocks & equities', 'Beginner', null),
  ('stk-015', 'Which describes a value stock?', '["Trading at a high multiple to growth","Trading at a low multiple relative to fundamentals like earnings or book value","Always pays high dividends","Only small-cap"]'::jsonb, 1, 'Value stocks trade cheaply relative to fundamentals like earnings or book value.', 'Stocks & equities', 'Beginner', null),
  ('stk-016', 'Which is true about cyclicals?', '["Earnings are stable in all economies","Earnings rise and fall with the economic cycle","They never pay dividends","They are immune to recessions"]'::jsonb, 1, 'Cyclicals — autos, airlines, materials — track economic cycles closely.', 'Stocks & equities', 'Beginner', null),
  ('stk-017', 'Which are typical defensive sectors?', '["Tech and consumer discretionary","Utilities, consumer staples, healthcare","Energy and materials","Financials and industrials"]'::jsonb, 1, 'Defensive sectors hold up better in recessions because demand for their products is steady.', 'Stocks & equities', 'Beginner', null),
  ('stk-018', 'Which is the right description of a "penny stock"?', '["Any stock under $50","Typically trades under $5 with low market cap and high risk","Always traded on the NYSE","A regulated bond"]'::jsonb, 1, 'Penny stocks are low-priced, small-cap, often thinly traded and risky.', 'Stocks & equities', 'Beginner', null),
  ('stk-019', 'Which is true about ADRs (American Depositary Receipts)?', '["They give US investors exposure to foreign companies via US exchanges","They are only for bonds","They eliminate currency risk","They trade only over the counter"]'::jsonb, 0, 'ADRs let US investors trade foreign companies on US exchanges in dollars.', 'Stocks & equities', 'Beginner', null),
  ('stk-020', 'What is a stock buyback?', '["Issuing new shares","A company repurchasing its own shares","A merger","A dividend"]'::jsonb, 1, 'Buybacks reduce share count, raising EPS and often supporting the stock price.', 'Stocks & equities', 'Beginner', null),
  ('stk-021', 'Why might a company do a buyback?', '["To raise capital","To return cash to shareholders and reduce share count","To file for bankruptcy","To pay employees"]'::jsonb, 1, 'Buybacks return capital and concentrate ownership in remaining shares.', 'Stocks & equities', 'Beginner', null),
  ('stk-022', 'Which is true about voting rights?', '["Bonds always carry voting rights","Common stock typically has voting rights, preferred often does not","Only insiders vote","Voting rights expire annually"]'::jsonb, 1, 'Common shareholders typically vote; preferred usually doesn''t unless dividends are skipped.', 'Stocks & equities', 'Beginner', null),
  ('stk-023', 'Which sector is most sensitive to interest rates?', '["Consumer staples","Banks/financials","Energy producers","Utilities only"]'::jsonb, 1, 'Banks profit on the spread between borrowing and lending rates — they are very rate-sensitive.', 'Stocks & equities', 'Beginner', null),
  ('stk-024', 'Which is a small-cap stock typically?', '["Market cap >$10B","Market cap $300M-$2B","Market cap >$100B","Any stock under $5"]'::jsonb, 1, 'Small-caps are typically $300M-$2B in market cap.', 'Stocks & equities', 'Beginner', null),
  ('stk-025', 'Why do small-caps historically have higher long-term returns?', '["No reason","Higher risk and less analyst coverage create a risk premium","Tax advantages","Fixed regulation"]'::jsonb, 1, 'Small-caps are riskier, so investors demand a return premium — the size premium.', 'Stocks & equities', 'Beginner', null),
  ('stk-026', 'Which is true about "momentum" stocks?', '["Recent winners often continue trending in the short run","They always reverse","They are immune to news","They only exist in small caps"]'::jsonb, 0, 'Momentum is the empirical tendency for recent winners to keep outperforming for some period.', 'Stocks & equities', 'Beginner', null),
  ('stk-027', 'Which is most likely true about an ex-dividend date?', '["Buying on it qualifies for the dividend","On or after ex-date, the buyer does not receive the current dividend","It''s always quarterly","It''s set by the SEC"]'::jsonb, 1, 'You must own shares before the ex-date to receive the announced dividend.', 'Stocks & equities', 'Beginner', null),
  ('stk-028', 'Which is true about the record date?', '["It''s irrelevant","Shareholders on the record date receive the dividend","It''s the same as the pay date","Only insiders see it"]'::jsonb, 1, 'Holders on the record date are the eligible recipients of the dividend.', 'Stocks & equities', 'Beginner', null),
  ('stk-029', 'What is a sector?', '["A specific company","A grouping of related industries (tech, financials, etc.)","An exchange","A type of derivative"]'::jsonb, 1, 'Sectors group companies by industry — useful for analysis and diversification.', 'Stocks & equities', 'Beginner', null),
  ('stk-030', 'What is sector rotation?', '["A regulatory requirement","Shifting allocations between sectors based on economic cycle","Holding only one sector","Quarterly rebalancing"]'::jsonb, 1, 'Investors rotate into sectors expected to outperform at the current point in the cycle.', 'Stocks & equities', 'Beginner', null),
  ('stk-031', 'What does "diluted EPS" account for?', '["Only outstanding shares","Potential conversion of options, warrants, convertible debt","Bond interest","Treasury shares only"]'::jsonb, 1, 'Diluted EPS assumes all dilutive securities are converted, giving a more conservative figure.', 'Stocks & equities', 'Intermediate', null),
  ('stk-032', 'Which is true about share repurchases vs dividends?', '["Both are taxed identically","Buybacks are more tax-flexible because gains are deferred until sale","Dividends are always better","Buybacks reduce float for sellers"]'::jsonb, 1, 'Buybacks defer tax until shares are sold; dividends are taxed when received.', 'Stocks & equities', 'Intermediate', null),
  ('stk-033', 'Which best describes "market-cap-weighted" index?', '["Each company has equal weight","Larger market-cap companies have larger weights","Weights are price-based","Weights rotate weekly"]'::jsonb, 1, 'Cap-weighted indexes (like the S&P 500) give larger companies bigger weights.', 'Stocks & equities', 'Intermediate', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('stk-034', 'Which best describes "price-weighted" index?', '["Each company has equal weight","Higher-price stocks have larger weights regardless of size","Weighted by market cap","Weighted by revenue"]'::jsonb, 1, 'Price-weighted indexes (like the Dow) give higher-priced stocks more influence.', 'Stocks & equities', 'Intermediate', null),
  ('stk-035', 'Which best describes "equal-weighted" index?', '["Larger companies dominate","Each constituent has the same weight regardless of size","Weighted by float","Weighted by volatility"]'::jsonb, 1, 'Equal-weight gives each constituent the same weight — more small/mid exposure than cap-weighted.', 'Stocks & equities', 'Intermediate', null),
  ('stk-036', 'Which is true about "insider selling"?', '["It''s always bullish","It can be neutral (planned 10b5-1 sales) or bearish (signaling concern)","It''s illegal","It only happens at IPO"]'::jsonb, 1, 'Insider selling can be routine (scheduled plans) or informative — context matters.', 'Stocks & equities', 'Intermediate', null),
  ('stk-037', 'Which is true about "short interest"?', '["High short interest always means a stock will rise","High short interest indicates bearish positioning; squeezes can trigger sharp rallies","It''s a regulatory limit","It''s a dividend type"]'::jsonb, 1, 'Short interest is the share of float sold short — a sentiment indicator and squeeze candidate.', 'Stocks & equities', 'Intermediate', null),
  ('stk-038', 'What is a "short squeeze"?', '["When dividends are cut","Forced buying by short-sellers as price rises","An IPO lockup ending","A regulatory halt"]'::jsonb, 1, 'As shorts cover positions, buying pressure escalates rapidly — squeezing the price higher.', 'Stocks & equities', 'Intermediate', null),
  ('stk-039', 'Which best describes "buyback yield"?', '["Dividend yield","Net shares retired as a percentage of market cap","Earnings yield","Forward P/E"]'::jsonb, 1, 'Buyback yield measures how much capital is returned via repurchases relative to market cap.', 'Stocks & equities', 'Intermediate', null),
  ('stk-040', 'Which is true about "qualified dividends"?', '["They are taxed as ordinary income","They are taxed at lower long-term capital gains rates","They are tax-free","Only foreign dividends qualify"]'::jsonb, 1, 'Qualified dividends meet IRS criteria and are taxed at favorable long-term capital gains rates.', 'Stocks & equities', 'Intermediate', null),
  ('stk-041', 'Which is true about "book value per share"?', '["It''s the same as market price","Shareholders'' equity ÷ shares outstanding","Always above market price","Equals EPS"]'::jsonb, 1, 'Book value per share is the accounting equity divided by shares outstanding.', 'Stocks & equities', 'Intermediate', null),
  ('stk-042', 'Which is true about "return on equity" (ROE)?', '["Net income ÷ revenue","Net income ÷ shareholders'' equity","Operating income ÷ assets","Free cash flow ÷ debt"]'::jsonb, 1, 'ROE measures profit generated per dollar of shareholder equity.', 'Stocks & equities', 'Intermediate', null),
  ('stk-043', 'Which is generally true about banks'' ROE vs tech ROE?', '["Banks have systematically higher ROE","Tech firms often have much higher ROE due to capital-light models","ROE is identical","Both rarely exceed 5%"]'::jsonb, 1, 'Software businesses scale without much capital, often achieving very high ROE.', 'Stocks & equities', 'Intermediate', null),
  ('stk-044', 'Which is true about "earnings surprises"?', '["Stocks generally drift in the direction of the surprise for weeks afterward","They always reverse the next day","Negative surprises are bullish","Surprises don''t affect price"]'::jsonb, 0, 'Post-earnings announcement drift is a well-documented effect — stocks drift in the surprise direction.', 'Stocks & equities', 'Intermediate', null),
  ('stk-045', 'Which is true about "forward earnings"?', '["Historical","Analyst-estimated future earnings","Audited","Always lower than trailing earnings"]'::jsonb, 1, 'Forward earnings are analyst projections used to compute forward multiples.', 'Stocks & equities', 'Intermediate', null),
  ('stk-046', 'Which best describes "earnings yield"?', '["1 ÷ price","EPS ÷ price (inverse of P/E)","Dividend yield","Coupon ÷ price"]'::jsonb, 1, 'Earnings yield is the inverse of P/E — useful for comparing equity expected returns to bond yields.', 'Stocks & equities', 'Intermediate', null),
  ('stk-047', 'Which best describes "insider buying"?', '["Always bullish in any context","Often viewed as a positive signal, especially when concentrated","Always neutral","Illegal in the US"]'::jsonb, 1, 'Open-market insider purchases — especially clustered — are often viewed bullishly.', 'Stocks & equities', 'Intermediate', null),
  ('stk-048', 'Which is true about "share class" structures (e.g., GOOG vs GOOGL)?', '["They are always identical","Different classes can have different voting rights or dividend treatment","They have different P/E ratios","Classes are interchangeable"]'::jsonb, 1, 'Different share classes can differ in voting rights and sometimes economics.', 'Stocks & equities', 'Intermediate', null),
  ('stk-049', 'Which describes "insider lockup" after an IPO?', '["Insiders can sell immediately","Insiders are restricted from selling for a set period (often 90-180 days)","Insiders never sell","Only the CEO is restricted"]'::jsonb, 1, 'Lockups prevent insider selling immediately post-IPO; expirations can pressure the stock.', 'Stocks & equities', 'Intermediate', null),
  ('stk-050', 'Which is true about secondary offerings?', '["They reduce share count","They issue new shares to raise capital, often diluting existing holders","They cancel debt","They are tax-free"]'::jsonb, 1, 'Secondary offerings raise capital by issuing new shares, which dilutes existing shareholders.', 'Stocks & equities', 'Intermediate', null),
  ('stk-051', 'Which is true about "earnings quality"?', '["All earnings are equal","Recurring cash-backed earnings are higher quality than one-time or non-cash items","Earnings quality only matters in tech","GAAP requires same quality across firms"]'::jsonb, 1, 'High-quality earnings come from cash-generating recurring operations, not accounting adjustments.', 'Stocks & equities', 'Advanced', null),
  ('stk-052', 'Which is most likely "low-quality earnings"?', '["Repeating subscription revenue","Large one-time gain from asset sale","Steady ROIC across segments","Cash-funded buyback"]'::jsonb, 1, 'One-time gains inflate earnings without recurring economic substance — low quality.', 'Stocks & equities', 'Advanced', null),
  ('stk-053', 'Which is true about "insider ownership" and stock performance?', '["High insider ownership empirically correlates with stronger long-term performance, on average","Insider ownership doesn''t matter","Lower is better","Insider ownership only matters in banks"]'::jsonb, 0, 'Studies show meaningful insider ownership tends to align incentives and improve returns on average.', 'Stocks & equities', 'Advanced', null),
  ('stk-054', 'Which is true about "share dilution" over time?', '["It always raises EPS","Heavy stock-based compensation can quietly erode per-share value","Dilution is illegal","SBC has no impact"]'::jsonb, 1, 'Heavy stock-based comp dilutes share count, eroding existing holders'' per-share economics.', 'Stocks & equities', 'Advanced', null),
  ('stk-055', 'Which is true about "narrow vs wide moats"?', '["No company has a moat","Wide-moat businesses tend to sustain returns longer","Moats are accounting metrics","Moats refer to physical assets only"]'::jsonb, 1, 'Wide economic moats — durable competitive advantages — let companies sustain returns longer.', 'Stocks & equities', 'Advanced', null),
  ('stk-056', 'Which describes "network effects"?', '["A regulatory barrier","Each new user makes the product more valuable for existing users","A type of derivative","Always negative for growth"]'::jsonb, 1, 'Network effects create self-reinforcing value — more users → more value → more users.', 'Stocks & equities', 'Advanced', null),
  ('stk-057', 'Which is true about "customer concentration risk"?', '["Diversified revenue is risky","Heavy reliance on a few customers can create acute risk if any leave","Concentration is irrelevant","SaaS firms have no customer risk"]'::jsonb, 1, 'A handful of mega-customers can drop revenue dramatically if they churn.', 'Stocks & equities', 'Advanced', null),
  ('stk-058', 'Which best describes "capital allocation"?', '["Picking factories","How a company deploys cash flow (reinvestment, buybacks, dividends, M&A, debt paydown)","Tax planning","Inventory management"]'::jsonb, 1, 'Capital allocation is the management''s choice of how to deploy generated cash — a major driver of long-term value.', 'Stocks & equities', 'Advanced', null),
  ('stk-059', 'Which is generally true about "reinvestment economics"?', '["Reinvesting is always bad","High-ROIC businesses reinvesting at high rates compound rapidly","ROIC is irrelevant to reinvestment value","Reinvestment lowers returns"]'::jsonb, 1, 'When a business earns high returns on capital and can reinvest, compounding accelerates.', 'Stocks & equities', 'Advanced', null),
  ('stk-060', 'Which is true about "shareholder yield"?', '["It''s only dividends","Dividends + net buybacks combined as a percentage of market cap","Always negative","Coupon yield"]'::jsonb, 1, 'Shareholder yield sums dividends and net buybacks to show total capital return.', 'Stocks & equities', 'Advanced', null),
  ('stk-061', 'Which is most likely true about "highly-shorted" stocks long-term?', '["They always rise","On average they underperform, but short squeezes can cause sharp short-term spikes","Always outperform","Are immune to news"]'::jsonb, 1, 'Heavily-shorted stocks tend to underperform on average but can squeeze violently in the short run.', 'Stocks & equities', 'Advanced', null),
  ('stk-062', 'Which is true about "deferred revenue" growing?', '["A bearish signal","Often a leading indicator of bookings/subscriber strength","Tax deferral","Reduces earnings"]'::jsonb, 1, 'Rising deferred revenue indicates strong forward bookings — a leading SaaS indicator.', 'Stocks & equities', 'Advanced', null),
  ('stk-063', 'Which describes "earnings management"?', '["Honest reporting","Using accounting flexibility to smooth or shape reported earnings","A tax strategy","A type of buyback"]'::jsonb, 1, 'Earnings management uses accounting discretion to hit targets — a quality concern.', 'Stocks & equities', 'Advanced', null),
  ('stk-064', 'Which best describes "share-based compensation" (SBC) impact?', '["No effect on shareholders","SBC is a real economic expense even if it doesn''t immediately hit cash","Tax credit","Always disclosed in revenue"]'::jsonb, 1, 'SBC dilutes existing shareholders and is an economic expense, despite often being non-cash on the income statement.', 'Stocks & equities', 'Advanced', null),
  ('stk-065', 'Which is true about "goodwill impairment" charges?', '["Tax savings","Indicate an acquisition''s value has deteriorated","Always non-cash and always ignored","Boost EPS"]'::jsonb, 1, 'Goodwill impairments signal that a past acquisition was overpaid for or underperformed.', 'Stocks & equities', 'Advanced', null),
  ('stk-066', 'Which is true about "capital-light" businesses?', '["Require huge fixed assets","Generate strong cash flow with minimal reinvestment needs","Always cyclicals","Always banks"]'::jsonb, 1, 'Capital-light businesses — software, brand licensing — generate cash without heavy reinvestment.', 'Stocks & equities', 'Advanced', null),
  ('stk-067', 'Which is most consistent with a "compounder"?', '["High dividend, no growth","Sustainable high ROIC reinvested at attractive incremental rates","Single-product cyclical","Distressed turnaround"]'::jsonb, 1, 'A compounder is a business that can profitably reinvest at high ROIC for many years.', 'Stocks & equities', 'Advanced', null),
  ('bnd-001', 'What is a bond?', '["Equity ownership","A loan from the investor to the issuer","A type of insurance","A bank deposit"]'::jsonb, 1, 'A bond is a debt instrument — the investor lends money in exchange for interest and return of principal.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-002', 'What is a coupon?', '["The discount on a bond","The periodic interest payment a bond makes","The bond''s price","A type of bond rating"]'::jsonb, 1, 'The coupon is the regular interest payment a bond makes to holders.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-003', 'What is face value?', '["Current market price","The amount the issuer repays at maturity","Annual interest","Discount to par"]'::jsonb, 1, 'Face value (par) is the principal repaid at maturity, typically $1,000 for corporates.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-004', 'What is maturity?', '["The bond''s credit rating","The date when principal is repaid","The current price","The coupon rate"]'::jsonb, 1, 'Maturity is when the bond''s principal is returned to the holder.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-005', 'Which is true about Treasury bonds?', '["Issued by corporations","Issued by the US federal government","Issued by municipalities","Issued by banks"]'::jsonb, 1, 'Treasuries are debt of the US federal government.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-006', 'What are Treasury bills (T-bills)?', '["Long-term Treasuries","Short-term US government debt (1 year or less)","Corporate bonds","Municipal bonds"]'::jsonb, 1, 'T-bills mature in 1 year or less and are sold at a discount to face value.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-007', 'What is a municipal bond?', '["A corporate bond","Debt issued by state/local governments","Federal debt","A bank CD"]'::jsonb, 1, 'Munis are issued by state and local governments and often carry tax advantages.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-008', 'Why are munis often tax-advantaged?', '["No reason","Interest is typically exempt from federal income tax","They have higher yields","They are guaranteed by the FDIC"]'::jsonb, 1, 'Most muni bond interest is exempt from federal taxes, and sometimes state taxes too.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-009', 'What is a corporate bond?', '["Government debt","Debt issued by a company","An equity stake","Insurance"]'::jsonb, 1, 'Corporate bonds are debt issued by companies to fund operations or expansion.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-010', 'What is credit risk?', '["Volatility of returns","The risk the issuer fails to make payments","Interest-rate risk","Currency risk"]'::jsonb, 1, 'Credit risk is the chance the borrower defaults on principal or coupon.', 'Bonds & fixed income', 'Basic', null),
  ('bnd-011', 'Which is true about bond prices and yields?', '["They move in the same direction","Prices and yields move in opposite directions","They are unrelated","Both rise with inflation"]'::jsonb, 1, 'As yields rise, prices fall; as yields fall, prices rise.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-012', 'What is yield to maturity (YTM)?', '["Coupon rate","Total annualized return if held to maturity, assuming coupon reinvestment","Current yield","Dividend yield"]'::jsonb, 1, 'YTM is the comprehensive yield assuming the bond is held to maturity and coupons reinvested.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-013', 'What is duration?', '["Time to maturity","A measure of a bond''s price sensitivity to interest-rate changes","The coupon rate","Credit rating"]'::jsonb, 1, 'Duration estimates how much a bond''s price will move for a 1% change in rates.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-014', 'Higher duration means:', '["Lower sensitivity to rates","Higher sensitivity to rates","No relationship to rates","Higher coupon"]'::jsonb, 1, 'Longer-duration bonds move more for the same rate change.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-015', 'What is investment-grade?', '["Bonds with credit ratings BBB-/Baa3 or higher","Only AAA bonds","All government bonds","Bonds under $1000"]'::jsonb, 0, 'Investment-grade is BBB-/Baa3 and above per S&P/Moody''s.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-016', 'What are "high-yield" or "junk" bonds?', '["Bonds rated investment grade","Bonds rated below BBB-/Baa3 with higher yields and default risk","Treasury bonds","Municipal bonds"]'::jsonb, 1, 'Below-investment-grade bonds carry more default risk and compensating yield.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-017', 'Which is true about interest-rate risk?', '["Only affects short bonds","Bond prices fall when interest rates rise","Affects only floating rate bonds","Only matters for junk bonds"]'::jsonb, 1, 'Existing bonds with fixed coupons become less valuable when new bonds offer higher rates.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-018', 'What is the yield curve?', '["Average yields","Yields plotted by maturity, typically of Treasuries","Stock returns over time","Credit spreads"]'::jsonb, 1, 'The yield curve plots yields across maturities — a snapshot of rate expectations.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-019', 'What does a "normal" yield curve look like?', '["Flat","Upward sloping — longer maturities yield more","Downward sloping","V-shaped"]'::jsonb, 1, 'Normal yield curves are upward-sloping because investors demand more for longer maturities.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-020', 'What is an inverted yield curve?', '["Long yields > short yields","Short yields > long yields","Both yields equal","Negative yields only"]'::jsonb, 1, 'Inversion (short > long) is historically associated with recession risk.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-021', 'What is a callable bond?', '["Bond you can sell anytime","Bond the issuer can redeem early at a set price","Bond with no maturity","Bond with floating coupon"]'::jsonb, 1, 'Callable bonds let the issuer redeem early — typically when rates fall and refinancing is cheaper.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-022', 'What is a zero-coupon bond?', '["Pays no interest","Pays no periodic coupon; sold at discount, matures at par","Pays only at default","Has no maturity"]'::jsonb, 1, 'Zeros are bought below par and pay no coupons; the return is the discount accreting to par.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-023', 'What are TIPS?', '["Inflation-indexed Treasury securities","Tax-free state bonds","Tech sector bonds","Short-term notes"]'::jsonb, 0, 'TIPS are Treasury Inflation-Protected Securities — principal adjusts with CPI.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-024', 'What is a CD (Certificate of Deposit)?', '["A type of stock","Bank time deposit with fixed term and interest","Corporate bond","A mutual fund"]'::jsonb, 1, 'CDs are bank deposits paying fixed interest over a term — federally insured up to limits.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-025', 'Which is FDIC-insured?', '["Treasury bonds","CDs at member banks (up to limits)","Corporate bonds","Money market funds"]'::jsonb, 1, 'CDs at FDIC-member banks are insured up to $250,000 per depositor per bank.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-026', 'Which is true about money market funds?', '["FDIC-insured","Mutual funds investing in short-term debt; aim for stable $1 NAV","Long-term equity funds","Always Treasury-only"]'::jsonb, 1, 'Money market funds hold short-term debt and target a stable $1 share price.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-027', 'Which is true about junk bonds in a recession?', '["Outperform","Default rates and spreads typically spike","Unchanged","Become Treasuries"]'::jsonb, 1, 'Recessions stress weaker credits — defaults and spreads rise sharply.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-028', 'What is the "coupon rate"?', '["Annual coupon ÷ face value","Annual coupon ÷ market price","Market price ÷ face value","Yield to maturity"]'::jsonb, 0, 'Coupon rate is the annual coupon divided by face value — fixed for fixed-rate bonds.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-029', 'What is "current yield"?', '["Coupon rate","Annual coupon ÷ current market price","Yield to maturity","Yield to call"]'::jsonb, 1, 'Current yield divides the annual coupon by the bond''s current market price.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-030', 'Which is true about agency bonds (e.g., Fannie Mae)?', '["Direct Treasury issues","Issued by GSEs; carry implicit but not explicit government guarantee","Tax-free everywhere","Always investment grade"]'::jsonb, 1, 'Agency bonds are issued by government-sponsored entities and carry implied but not explicit federal backing.', 'Bonds & fixed income', 'Beginner', null),
  ('bnd-031', 'Which has highest interest-rate sensitivity?', '["3-month T-bill","2-year note","30-year Treasury bond","Floating-rate note"]'::jsonb, 2, '30-year bonds have the longest duration of these — most sensitive to rate moves.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-032', 'If rates rise 1%, a bond with duration 8 will fall approximately:', '["1%","4%","8%","16%"]'::jsonb, 2, 'For a small rate move, price change ≈ -duration × ΔY. Duration 8 → -8% for +1%.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-033', 'Which is true about convexity?', '["Linear approximation only","Captures the curvature of price-yield relationship; positive convexity benefits holders","Always negative","Equals duration"]'::jsonb, 1, 'Convexity refines duration''s linear estimate and is typically positive for standard bonds.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-034', 'Which describes "credit spread"?', '["Equity dividend yield","Difference between a bond''s yield and the comparable Treasury yield","Coupon difference","Maturity difference"]'::jsonb, 1, 'Credit spread = yield over a comparable Treasury, compensating for credit risk.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-035', 'Wider spreads typically signal:', '["Improving credit conditions","Higher perceived credit risk and/or worsening conditions","Lower inflation","Stock market gains"]'::jsonb, 1, 'Spreads widen when investors demand more yield for credit risk.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-036', 'Which is true about bond ETF liquidity?', '["Always matches underlying bonds","ETF shares can trade more liquidly than illiquid underlying bonds","ETFs cannot trade","Bond ETFs have no NAV"]'::jsonb, 1, 'Bond ETFs often offer better intraday liquidity than the underlying corporate bonds.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-037', 'What is reinvestment risk?', '["Default risk","Risk that coupons must be reinvested at lower rates","Inflation risk","Currency risk"]'::jsonb, 1, 'If rates fall, coupons earn lower returns when reinvested — reducing total realized yield.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-038', 'Which is true about "par bonds"?', '["Trade above face value","Trade at face value because coupon ≈ market yield","Trade below face value","Are always government bonds"]'::jsonb, 1, 'A par bond trades at face value when its coupon equals prevailing market yields.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-039', 'Which bond trades at a premium?', '["Coupon < market yield","Coupon = market yield","Coupon > market yield","Always callable bonds"]'::jsonb, 2, 'When a bond''s coupon exceeds current yields, it trades above par.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-040', 'Which is true about LIBOR/SOFR-linked debt?', '["Fixed rate","Coupons reset based on a short-term benchmark","Always tax-free","Default-free"]'::jsonb, 1, 'Floating-rate notes reset coupons periodically based on benchmark rates like SOFR.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-041', 'Which is true about "laddered" bond portfolios?', '["All bonds mature same date","Maturities are staggered to smooth reinvestment risk","Higher risk than single bond","Always uses high-yield bonds"]'::jsonb, 1, 'Bond ladders spread maturities to reduce timing/reinvestment risk and create rolling cash flows.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-042', 'What is a "barbell" bond strategy?', '["Equal duration weights","Concentrating in short and long maturities, avoiding intermediates","Holding only one bond","Avoiding government bonds"]'::jsonb, 1, 'Barbells combine short and long maturities to balance liquidity and yield.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-043', 'Which is true about Treasury STRIPS?', '["Coupon-paying Treasuries","Zero-coupon Treasuries created by separating principal and interest","Inflation-linked bonds","Foreign government debt"]'::jsonb, 1, 'STRIPS are zero-coupon Treasuries derived from stripping the coupons of regular Treasuries.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-044', 'Which is true about "covenants" in bond indentures?', '["Decorative legal language","Restrictions/obligations on the issuer protecting bondholders","Coupon rates","Maturity dates"]'::jsonb, 1, 'Covenants impose limits like leverage ceilings or dividend restrictions to protect lenders.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-045', 'What is a "sinking fund" provision?', '["A default trigger","Issuer sets aside funds to retire portions of debt before maturity","Tax shelter","Currency hedge"]'::jsonb, 1, 'Sinking funds reduce credit risk by retiring debt over time rather than at a single maturity.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-046', 'Which is true about "convertible bonds"?', '["Always convert to cash","Bondholders can convert into a set number of issuer shares","Tax-free","Equity-only"]'::jsonb, 1, 'Convertibles let holders trade the bond for a fixed number of shares — equity upside with debt floor.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-047', 'Which is true about MBS (mortgage-backed securities)?', '["Backed by mortgage loans; cash flows depend on prepayments","Equity in real estate","Default-free","Always Treasury-backed"]'::jsonb, 0, 'MBS pass through mortgage payments; prepayment risk affects timing of cash flows.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-048', 'What is "negative convexity" in MBS?', '["Price rises faster than rates drop","As rates fall, prepayments accelerate, capping price gains","Higher duration","Lower coupon"]'::jsonb, 1, 'MBS show negative convexity because falling rates trigger refinancing — limiting price upside.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-049', 'Which is true about credit default swaps (CDS)?', '["Bond ETF","Derivative that pays out if a reference entity defaults","Insurance on equities","Currency hedge"]'::jsonb, 1, 'CDS contracts pay the buyer if a reference name defaults — a credit insurance/hedging tool.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-050', 'Which is true about "investment-grade vs high-yield" historical defaults?', '["IG default rates roughly match HY","HY has materially higher default rates","HY default-free","IG defaults are highest"]'::jsonb, 1, 'High-yield defaults run much higher than investment-grade on average.', 'Bonds & fixed income', 'Intermediate', null),
  ('bnd-051', 'Which is true about the "on-the-run" Treasury?', '["Off-the-run yields more","On-the-run yields more","They are identical","On-the-run yields slightly less due to liquidity premium"]'::jsonb, 3, 'The most recently issued (on-the-run) Treasury is most liquid and yields slightly less.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-052', 'Which is true about "breakeven inflation"?', '["Difference between TIPS yield and nominal Treasury yield","Federal Reserve target","CPI revisions","Forward CPI"]'::jsonb, 0, 'Breakeven inflation = nominal yield − TIPS yield, implying market-priced inflation.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-053', 'Which is true about "OAS" (option-adjusted spread)?', '["Same as nominal spread","Spread adjusted for embedded options (calls/puts)","Pure equity metric","Always zero for callable bonds"]'::jsonb, 1, 'OAS strips out optionality to give a cleaner comparable credit spread.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-054', 'Which is true about "liability-driven investing"?', '["Pure return maximization","Matching asset duration/cashflows to specific liability streams","Equity-only","Tax avoidance"]'::jsonb, 1, 'LDI matches duration and cash flows to expected liabilities, common for pension funds.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-055', 'Which is true about "key rate duration"?', '["Single-rate sensitivity","Bond price sensitivity to specific points on the yield curve","Currency sensitivity","Same as Macaulay duration"]'::jsonb, 1, 'Key rate duration breaks duration into sensitivities at specific maturities.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-056', 'Which is true about "riding the yield curve"?', '["Buying short, selling long","Holding a longer-dated bond as it \"rolls down\" to shorter maturities, hoping for price gain","Buying inflation","Equity strategy"]'::jsonb, 1, 'As time passes, a bond''s maturity shortens; on an upward-sloping curve, its yield drops and price rises.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-057', 'Which is true about "flat yield curve"?', '["Implies high growth","Often signals economic uncertainty or transition","Always bullish stocks","No information"]'::jsonb, 1, 'Flat curves often precede inversion and indicate uncertainty about growth or rates.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-058', 'Which is true about "recovery rate" in defaults?', '["100%","The proportion of par value bondholders recover after default","Always 0%","Equals yield"]'::jsonb, 1, 'Recovery rate is what holders get back after default — typically 30-50% for senior unsecured.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-059', 'Which is true about "seniority" in capital structure?', '["Common equity is most senior","Senior secured debt is first to be paid in liquidation","Order doesn''t matter","Bonds always come last"]'::jsonb, 1, 'Senior secured debt holds the highest priority claim on assets in bankruptcy.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-060', 'Which is true about "subordinated" debt?', '["Highest seniority","Ranks junior to senior debt in claim priority","Equity stake","Government-backed"]'::jsonb, 1, 'Subordinated bondholders are paid only after senior debt is satisfied.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-061', 'Which is true about "perpetual bonds"?', '["Have a maturity","Pay coupons indefinitely with no maturity","Tax-free","Always callable"]'::jsonb, 1, 'Perpetuals have no maturity; the principal is never repaid (often callable, though).', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-062', 'Which is true about "contingent convertible" (CoCo) bonds?', '["Standard convertibles","Convert to equity (or write down) on a regulatory/capital trigger","Tax-free","Risk-free"]'::jsonb, 1, 'CoCos are bank capital that converts or writes down when capital ratios fall below thresholds.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-063', 'Which is true about "credit migration" risk?', '["Default risk only","Risk a bond is downgraded, affecting price even without default","Currency risk","Inflation risk"]'::jsonb, 1, 'Downgrades widen spreads and reduce prices, even before any actual default.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-064', 'Which is true about "floating rate funds" in rising rate environments?', '["Their NAV typically falls","Their coupons reset higher, reducing duration risk","They are illegal","Equal to bond ETFs"]'::jsonb, 1, 'Floaters'' coupons reset with reference rates, limiting price impact from rate hikes.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-065', 'Which is true about "emerging market debt"?', '["Always safer than Treasuries","Carries credit, currency, and political risks — higher yields compensate","Tax-free","Default-free"]'::jsonb, 1, 'EM debt offers yield premia for credit, currency, and political risks.', 'Bonds & fixed income', 'Advanced', null),
  ('bnd-066', 'Which is true about "bond futures" delivery?', '["Always physical","Often cash-settled or with a cheapest-to-deliver basket","Always digital","Equity-settled"]'::jsonb, 1, 'Treasury futures use a cheapest-to-deliver basket; many other bond futures cash-settle.', 'Bonds & fixed income', 'Advanced', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('bnd-067', 'Which is true about "barbell vs bullet" with convexity?', '["Bullet has more convexity","Barbell typically has more convexity than a bullet at same duration","Both identical","Convexity is irrelevant"]'::jsonb, 1, 'Barbells (short + long) have higher convexity than equal-duration bullet portfolios.', 'Bonds & fixed income', 'Advanced', null),
  ('mkt-001', 'What is a stock exchange?', '["A regulator","A marketplace where securities are bought and sold","A type of bond","A clearing bank"]'::jsonb, 1, 'Exchanges are marketplaces that match buyers and sellers of securities.', 'Market structure & order types', 'Basic', null),
  ('mkt-002', 'Which is the largest US stock exchange by market cap?', '["Nasdaq","NYSE","Cboe","OTC"]'::jsonb, 1, 'The NYSE is the largest US exchange by listed market cap.', 'Market structure & order types', 'Basic', null),
  ('mkt-003', 'What does "bid" mean?', '["Highest price a buyer is willing to pay","Lowest price a seller will accept","Last traded price","Average daily price"]'::jsonb, 0, 'The bid is the best buyer-side price in the order book.', 'Market structure & order types', 'Basic', null),
  ('mkt-004', 'What does "ask" (offer) mean?', '["Highest price a buyer will pay","Lowest price a seller will accept","Last trade price","Volume weighted price"]'::jsonb, 1, 'The ask is the best seller-side price in the order book.', 'Market structure & order types', 'Basic', null),
  ('mkt-005', 'What is the bid-ask spread?', '["Difference between bid and ask","Difference between high and low","Average price","Volume"]'::jsonb, 0, 'The spread is the gap between bid and ask — narrower spreads usually mean more liquidity.', 'Market structure & order types', 'Basic', null),
  ('mkt-006', 'What is a market order?', '["Order at a specific price","Order to execute immediately at the best available price","Order with no expiration","Order that cancels at close"]'::jsonb, 1, 'A market order executes immediately at the prevailing market price.', 'Market structure & order types', 'Basic', null),
  ('mkt-007', 'What is a limit order?', '["Order at the market","Order to buy/sell only at a specified price or better","Order with hidden quantity","Order that requires margin"]'::jsonb, 1, 'A limit order specifies the maximum buy or minimum sell price you''ll accept.', 'Market structure & order types', 'Basic', null),
  ('mkt-008', 'What is a stop order (stop-loss)?', '["Triggers a market order once price hits a level","Cancels open orders","Halts trading","Hides the order"]'::jsonb, 0, 'Stop orders convert to market orders once the stop price is reached, often used to limit losses.', 'Market structure & order types', 'Basic', null),
  ('mkt-009', 'What is a stop-limit order?', '["Like a stop, but becomes a limit order at the stop price","Pure limit order","Hidden order","Iceberg order"]'::jsonb, 0, 'Stop-limits combine stop-trigger with limit price — you may not fill if price moves past the limit.', 'Market structure & order types', 'Basic', null),
  ('mkt-010', 'What is "liquidity" in markets?', '["How many shares exist","How easily an asset can be bought/sold without moving price","Maturity","Volatility"]'::jsonb, 1, 'Liquidity is the ease of transacting at near-current prices.', 'Market structure & order types', 'Basic', null),
  ('mkt-011', 'What does "day order" mean?', '["Order good only for today''s session","Order good for 30 days","Pending overnight","Limit order only"]'::jsonb, 0, 'Day orders expire at the end of the trading session if not filled.', 'Market structure & order types', 'Beginner', null),
  ('mkt-012', 'What is GTC (good-till-canceled)?', '["Order canceled immediately","Order stays active until canceled or filled","Day-only order","Trader-only order"]'::jsonb, 1, 'GTC orders persist (broker policies vary on duration) until filled or canceled.', 'Market structure & order types', 'Beginner', null),
  ('mkt-013', 'What is an "all-or-none" order?', '["Partial fills allowed","Must fill entire order or none","Hidden order","Stop order"]'::jsonb, 1, 'AON requires the entire quantity to fill or nothing fills.', 'Market structure & order types', 'Beginner', null),
  ('mkt-014', 'What is an iceberg order?', '["Order with no quantity","Order showing only a small portion of total size","Order that freezes prices","An options strategy"]'::jsonb, 1, 'Icebergs display only a slice of the full size, hiding the rest from the order book.', 'Market structure & order types', 'Beginner', null),
  ('mkt-015', 'What is a market maker?', '["A regulator","A firm that quotes both bid and ask, providing liquidity","A type of broker","An ETF sponsor"]'::jsonb, 1, 'Market makers continuously quote bids/offers, earning the spread for providing liquidity.', 'Market structure & order types', 'Beginner', null),
  ('mkt-016', 'What is the NBBO?', '["A regulator","National Best Bid and Offer — the best available across US exchanges","An index","A market segment"]'::jsonb, 1, 'NBBO is the highest bid and lowest offer across all venues — Reg NMS protects it.', 'Market structure & order types', 'Beginner', null),
  ('mkt-017', 'What does a "halt" mean?', '["A merger","Temporary trading pause, often due to volatility or news","An IPO","A dividend"]'::jsonb, 1, 'Trading halts pause activity, typically to allow information dissemination or cool extreme volatility.', 'Market structure & order types', 'Beginner', null),
  ('mkt-018', 'What is a circuit breaker?', '["A halt rule triggered by big market moves","A type of order","A regulator","An IPO mechanism"]'::jsonb, 0, 'Circuit breakers pause trading at predefined market-decline thresholds (e.g., -7%, -13%, -20%).', 'Market structure & order types', 'Beginner', null),
  ('mkt-019', 'What is an opening cross/auction?', '["Mid-day pause","Match of orders at session open setting the opening price","Closing auction","Random auction"]'::jsonb, 1, 'Exchanges match accumulated open-orders in an auction to establish the opening print.', 'Market structure & order types', 'Beginner', null),
  ('mkt-020', 'What is a closing auction?', '["Random","Match of orders at session close setting the closing print","Mid-day","Block trade"]'::jsonb, 1, 'The closing auction concentrates end-of-day flow into a single matched print.', 'Market structure & order types', 'Beginner', null),
  ('mkt-021', 'Which is true about pre-market trading?', '["Same liquidity as regular hours","Thinner liquidity and wider spreads","Always closed","Restricted to institutions"]'::jsonb, 1, 'Pre-market is thin and volatile; spreads widen and price discovery is rough.', 'Market structure & order types', 'Beginner', null),
  ('mkt-022', 'Which is true about after-hours trading?', '["High liquidity","Thinner volume and wider spreads, larger price moves possible","Identical to RTH","Closed except earnings days"]'::jsonb, 1, 'After-hours sessions have lower volume and can show outsized moves on news.', 'Market structure & order types', 'Beginner', null),
  ('mkt-023', 'What is an ECN?', '["A regulator","Electronic communication network matching orders directly","A bond rating","A type of fund"]'::jsonb, 1, 'ECNs are electronic platforms that match buyers/sellers without traditional market makers.', 'Market structure & order types', 'Beginner', null),
  ('mkt-024', 'What is a "dark pool"?', '["Public exchange","Private venue where trades execute without pre-trade transparency","Crypto exchange","Bond marketplace"]'::jsonb, 1, 'Dark pools let institutions trade large blocks privately without displaying orders.', 'Market structure & order types', 'Beginner', null),
  ('mkt-025', 'What is OTC trading?', '["Over-the-counter — trades occur outside formal exchanges","Same as exchange trading","Bond-only","Crypto-only"]'::jsonb, 0, 'OTC trading happens directly between parties, often via dealer networks.', 'Market structure & order types', 'Beginner', null),
  ('mkt-026', 'What is short selling?', '["Buying for the short-term","Borrowing shares to sell, expecting to buy back lower","Selling small lots","Selling fast"]'::jsonb, 1, 'Short sellers borrow shares, sell them, and aim to repurchase later at a lower price.', 'Market structure & order types', 'Beginner', null),
  ('mkt-027', 'What is margin?', '["A free service","Borrowed funds from a broker to amplify position size","A type of order","A regulator"]'::jsonb, 1, 'Margin lets you buy more than your cash balance by borrowing from the broker.', 'Market structure & order types', 'Beginner', null),
  ('mkt-028', 'What is a margin call?', '["Free upgrade","A demand to deposit more funds or reduce position when equity falls below maintenance","An order type","A type of dividend"]'::jsonb, 1, 'Margin calls force you to top up collateral or liquidate when account equity drops too low.', 'Market structure & order types', 'Beginner', null),
  ('mkt-029', 'What is slippage?', '["Order rejection","Difference between expected and actual execution price","A fee","Trade volume"]'::jsonb, 1, 'Slippage is the cost when your fill price differs from the price seen when you sent the order.', 'Market structure & order types', 'Beginner', null),
  ('mkt-030', 'Which is true about ETF arbitrage?', '["Authorized participants exploit price gaps vs NAV to keep ETF in line","ETFs never deviate","Only large investors can arbitrage","Arbitrage is illegal"]'::jsonb, 0, 'APs create/redeem shares to capture deviations between ETF price and underlying NAV.', 'Market structure & order types', 'Beginner', null),
  ('mkt-031', 'What is high-frequency trading (HFT)?', '["Slow institutional trading","Algorithmic trading at very high speeds, often providing/scalping liquidity","A regulator","Pre-market only"]'::jsonb, 1, 'HFT uses speed and low-latency tech to trade rapidly, often providing or competing for liquidity.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-032', 'What is payment for order flow (PFOF)?', '["Free order entry","Brokers receive payment from market makers for routing customer orders","Exchange fees","SEC tax"]'::jsonb, 1, 'PFOF lets brokers earn from order flow they route to wholesalers — controversial conflict of interest.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-033', 'Which is true about "Reg NMS"?', '["Repealed","Requires routing to best displayed price (Order Protection Rule)","Bond regulation","ETF rule"]'::jsonb, 1, 'Reg NMS requires orders execute at the National Best Bid/Offer when displayed.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-034', 'What is T+1 settlement?', '["Trade settles same day","Trade settles one business day after execution","Two-day settlement","Never settles"]'::jsonb, 1, 'As of 2024, US equities settle T+1 — one business day after the trade.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-035', 'Which describes "hidden" or "reserve" orders?', '["Always visible","Only display a portion; balance is hidden until executed","Cancel automatically","Only for options"]'::jsonb, 1, 'Reserve/hidden orders mask size to avoid moving the market against the trader.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-036', 'What is a "locked market"?', '["Bid = ask","Halted","Closed for holiday","Inverted curve"]'::jsonb, 0, 'A locked market occurs when bid and ask prices match — unusual in fragmented markets.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-037', 'What is a "crossed market"?', '["Bid > ask across venues","Two-sided","Halted","Closed"]'::jsonb, 0, 'Crossed markets occur when the bid price exceeds the ask price — an arbitrage opportunity.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-038', 'Which describes "VWAP" execution?', '["Volume-weighted average price; orders sliced to track VWAP benchmark","Random execution","Single block","Closing auction"]'::jsonb, 0, 'VWAP algos work orders through the day to match the volume-weighted average price.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-039', 'What is TWAP?', '["Total weighted average price","Time-weighted average price — slice orders evenly over time","A regulator","An index"]'::jsonb, 1, 'TWAP algos space orders evenly across a time window.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-040', 'Which is true about "latency arbitrage"?', '["Trading on news","Exploiting microsecond delays between venues to profit from price differences","Slow trading","Bond arb"]'::jsonb, 1, 'Latency arb exploits tiny timing gaps where prices update unevenly across venues.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-041', 'What is "adverse selection" in market making?', '["Picking winners","Risk of trading with informed counterparties who know more about future price","Random selection","Regulatory penalty"]'::jsonb, 1, 'Adverse selection is the market maker''s risk that the counterparty has private information.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-042', 'What is a "block trade"?', '["Tiny trade","Large institutional trade, often negotiated off-book","A halt","A buyback"]'::jsonb, 1, 'Block trades are large transactions, often handled privately to avoid moving the market.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-043', 'Which is true about "odd lots"?', '["Always 100 shares","Less than 100 shares — historically excluded from some quote data","Always 1000 shares","Only options"]'::jsonb, 1, 'Odd lots are sub-100-share trades; their flow has grown with retail and may not appear in all quote feeds.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-044', 'What is "order book depth"?', '["Single best price","All visible buy/sell orders at various price levels","Last trade","Open interest"]'::jsonb, 1, 'Depth shows the cumulative size available at each price beyond the top of book.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-045', 'Which is true about "PFOF and execution quality"?', '["Always the best execution","Regulators require broker best-execution disclosures; PFOF creates conflict of interest","Always worse","Eliminates spreads"]'::jsonb, 1, 'PFOF can be consistent with good execution but creates a routing conflict — regulators scrutinize 605/606 reports.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-046', 'Which is true about "settlement risk" (Herstatt risk)?', '["Always zero","Risk of paying one leg of a trade before receiving the other, especially across timezones","Currency risk","Inflation risk"]'::jsonb, 1, 'Settlement risk is the chance one leg settles but the counterparty''s leg fails — historically severe across time zones.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-047', 'What is the "uptick rule"?', '["Limits short sales when prices fall (Rule 201)","Bans shorting","Rate limit","Closing rule"]'::jsonb, 0, 'The alternative uptick rule restricts shorting during 10%+ intraday declines.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-048', 'What is a "hard-to-borrow" stock?', '["High volume","Difficult/expensive to borrow shares for shorting","Closed for trading","Listed only on Nasdaq"]'::jsonb, 1, 'HTB stocks have limited float available for short borrowing — borrow fees are high.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-049', 'Which is true about "locate requirement" for shorts?', '["Optional","Brokers must locate shares to borrow before allowing a short sale","Bond rule","Eliminated"]'::jsonb, 1, 'Reg SHO requires brokers to have a reasonable expectation that shares can be borrowed before short selling.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-050', 'Which is true about "naked shorting"?', '["Encouraged","Selling short without locating shares — generally prohibited","Tax-free","Standard practice"]'::jsonb, 1, 'Naked shorting (no locate) is broadly prohibited in US equities under Reg SHO.', 'Market structure & order types', 'Intermediate', null),
  ('mkt-051', 'Which is true about "maker-taker" exchange pricing?', '["Same fees for all","Liquidity-adding (maker) orders get rebates; liquidity-taking orders pay fees","Subscription only","Volume only"]'::jsonb, 1, 'Maker-taker pricing pays rebates for posting limit orders and charges takers — incentivizing depth.', 'Market structure & order types', 'Advanced', null),
  ('mkt-052', 'Which is true about "taker-maker" venues?', '["Same as maker-taker","Inverted pricing: takers receive rebates, makers pay fees","Outlawed","Bond-only"]'::jsonb, 1, 'Inverted (taker-maker) venues invert the model — used by aggressive routers and some niche exchanges.', 'Market structure & order types', 'Advanced', null),
  ('mkt-053', 'Which is true about "sponsored access"?', '["Banned","Direct market access via a broker''s MPID with risk controls (Rule 15c3-5)","Retail only","Crypto only"]'::jsonb, 1, 'Sponsored access lets clients trade under the broker''s market participant ID under pre-trade risk controls.', 'Market structure & order types', 'Advanced', null),
  ('mkt-054', 'Which is true about "co-location"?', '["Online trading","Placing servers next to exchange matching engines to reduce latency","Bond trading","Crypto mining"]'::jsonb, 1, 'Co-location reduces latency to microseconds by hosting trading servers physically inside the exchange data center.', 'Market structure & order types', 'Advanced', null),
  ('mkt-055', 'Which is true about "order types arms race"?', '["Few order types","Hundreds of exchange-specific order types exist","Banned","Regulated to 5"]'::jsonb, 1, 'Exchanges offer many specialized order types — some controversial — to attract flow.', 'Market structure & order types', 'Advanced', null),
  ('mkt-056', 'Which is true about "flash crashes"?', '["Slow declines","Extreme intraday plunges followed by rapid recovery, often algo-driven","Bond-only","Always last days"]'::jsonb, 1, 'Flash crashes are very fast, deep selloffs with subsequent rebound — often involving fragile algo liquidity.', 'Market structure & order types', 'Advanced', null),
  ('mkt-057', 'Which is true about "limit-up/limit-down" rules?', '["Halt rules to constrain extreme price moves per stock","No limits exist","Only for ETFs","Bond rule"]'::jsonb, 0, 'LULD pauses trading on stocks moving outside defined bands relative to a rolling reference price.', 'Market structure & order types', 'Advanced', null),
  ('mkt-058', 'Which is true about "odd-lot orders in NBBO"?', '["Always included","Historically excluded; SEC rules updated to include odd-lot quotes","Always opens market","Only for index"]'::jsonb, 1, 'Recent SEC rules have moved toward incorporating round-lot odd-lot improvements into NBBO.', 'Market structure & order types', 'Advanced', null),
  ('mkt-059', 'Which is true about "clearing" vs "settlement"?', '["Identical","Clearing matches/confirms trades; settlement is actual exchange of securities and funds","Both pre-trade","Settlement first"]'::jsonb, 1, 'Clearing organizes obligations; settlement moves the assets and cash on the agreed date.', 'Market structure & order types', 'Advanced', null),
  ('mkt-060', 'Which is true about "DTCC / NSCC"?', '["Foreign regulators","Central counterparty/clearing infrastructure for US equities","ETF sponsors","Bond exchanges"]'::jsonb, 1, 'DTCC subsidiaries (NSCC, DTC) clear and settle the vast majority of US equity transactions.', 'Market structure & order types', 'Advanced', null),
  ('mkt-061', 'Which is true about "central limit order book" (CLOB)?', '["Hidden\nbook","Visible book matching orders by price-time priority","Single-dealer","Crypto-only"]'::jsonb, 1, 'A CLOB displays orders and matches by best price, then time priority.', 'Market structure & order types', 'Advanced', null),
  ('mkt-062', 'Which is true about "RFQ" (request for quote) systems?', '["Used for ETF and bond markets where dealers respond to specific size requests","Equity-only","Banned","Random matching"]'::jsonb, 0, 'RFQ is common in bonds and large ETF trades — clients ping dealers for two-way quotes.', 'Market structure & order types', 'Advanced', null),
  ('mkt-063', 'Which is true about "speed bumps" (e.g., IEX D-Limit)?', '["Accelerate orders","Microsecond delays designed to neutralize latency arb on stale quotes","Bond-only","Banned"]'::jsonb, 1, 'Speed bumps introduce intentional microsecond delays to protect resting orders from latency arbitrage.', 'Market structure & order types', 'Advanced', null),
  ('mkt-064', 'Which is true about "order-to-trade" ratio?', '["Higher is better","High ratios suggest quote stuffing/spoofing risk; surveillance flags them","Always 1","Equal to fees"]'::jsonb, 1, 'High order-to-trade ratios may indicate manipulative behavior like quote stuffing or layering.', 'Market structure & order types', 'Advanced', null),
  ('mkt-065', 'Which is true about "spoofing"?', '["Legal strategy","Placing orders without intent to execute to mislead the market — illegal","Settlement type","An order type"]'::jsonb, 1, 'Spoofing is the illegal practice of entering and quickly canceling orders to influence price.', 'Market structure & order types', 'Advanced', null),
  ('mkt-066', 'Which is true about "layering"?', '["Legal","Spoofing variant: multiple deceptive orders at different prices to influence direction","Tax strategy","An exchange"]'::jsonb, 1, 'Layering uses tiers of fake orders to create apparent imbalance and induce real trades.', 'Market structure & order types', 'Advanced', null),
  ('mkt-067', 'Which is true about "market on close" (MOC) orders?', '["Execute mid-day","Execute in the closing auction at the official close price","Always limit","Banned"]'::jsonb, 1, 'MOC orders participate in the closing cross at the official closing print.', 'Market structure & order types', 'Advanced', null),
  ('fin-001', 'What are the three main financial statements?', '["Income, balance sheet, cash flow","Revenue, profit, equity","Assets, liabilities, equity","Operating, investing, financing"]'::jsonb, 0, 'The big three are the income statement, balance sheet, and cash flow statement.', 'Financial statements', 'Basic', null),
  ('fin-002', 'What does the income statement show?', '["Assets at a point in time","Revenues, expenses, and profit over a period","Cash movements","Equity rolls"]'::jsonb, 1, 'The income statement (P&L) shows performance — revenues minus expenses — over a period.', 'Financial statements', 'Basic', null),
  ('fin-003', 'What does the balance sheet show?', '["Performance over a period","Assets, liabilities, equity at a specific point in time","Cash sources/uses","Income breakdown"]'::jsonb, 1, 'The balance sheet is a snapshot — what the company owns and owes at one moment.', 'Financial statements', 'Basic', null),
  ('fin-004', 'What does the cash flow statement show?', '["Net income only","Cash sources and uses across operating, investing, financing","Asset details","Inventory levels"]'::jsonb, 1, 'The cash flow statement tracks actual cash movements grouped by activity.', 'Financial statements', 'Basic', null),
  ('fin-005', 'What is revenue?', '["Profit","Total sales/income from goods and services before expenses","Net cash","Equity"]'::jsonb, 1, 'Revenue is the top-line sales number — before any expenses.', 'Financial statements', 'Basic', null),
  ('fin-006', 'What is gross profit?', '["Revenue minus all expenses","Revenue minus cost of goods sold (COGS)","Net income","Operating cash flow"]'::jsonb, 1, 'Gross profit = revenue − COGS. It''s the margin after direct production costs.', 'Financial statements', 'Basic', null),
  ('fin-007', 'What is operating income?', '["Net income","Gross profit minus operating expenses (SG&A, R&D, etc.)","Cash from operations","Revenue"]'::jsonb, 1, 'Operating income reflects core business profitability before interest and taxes.', 'Financial statements', 'Basic', null),
  ('fin-008', 'What is net income?', '["Top-line revenue","The bottom line: profit after all expenses, interest, and taxes","Cash from operations","Gross margin"]'::jsonb, 1, 'Net income is the final profit figure — what flows through to shareholders.', 'Financial statements', 'Basic', null),
  ('fin-009', 'What is the accounting equation?', '["Assets = Liabilities + Equity","Revenue = Expenses + Profit","Cash = Income − Expenses","Equity = Revenue − COGS"]'::jsonb, 0, 'Assets must equal liabilities plus shareholders'' equity — the balance sheet always balances.', 'Financial statements', 'Basic', null),
  ('fin-010', 'What are current assets?', '["Long-term holdings","Assets expected to be converted to cash within one year","Fixed assets","Intangible assets"]'::jsonb, 1, 'Current assets — cash, receivables, inventory — are short-term in nature.', 'Financial statements', 'Basic', null),
  ('fin-011', 'What is working capital?', '["Long-term debt","Current assets minus current liabilities","Total equity","Cash only"]'::jsonb, 1, 'Working capital measures short-term operating liquidity.', 'Financial statements', 'Beginner', null),
  ('fin-012', 'What is depreciation?', '["Cash expense","Non-cash allocation of a fixed asset''s cost over its useful life","Bond expense","Equity dilution"]'::jsonb, 1, 'Depreciation spreads the cost of long-lived assets across periods — non-cash.', 'Financial statements', 'Beginner', null),
  ('fin-013', 'What is amortization?', '["Inventory accounting","Spreading an intangible asset''s or debt''s cost over time","Stock split","Buyback expense"]'::jsonb, 1, 'Amortization is like depreciation but for intangible assets, or for debt principal.', 'Financial statements', 'Beginner', null),
  ('fin-014', 'What is COGS?', '["Cost of all expenses","Cost of goods sold — direct costs to produce sold goods","Total expenses","Capital outlay"]'::jsonb, 1, 'COGS is the direct cost of producing/sourcing the goods sold.', 'Financial statements', 'Beginner', null),
  ('fin-015', 'What are SG&A expenses?', '["Tax expenses","Selling, general, and administrative — operating overhead","Capital expenses","Cost of goods sold"]'::jsonb, 1, 'SG&A is the operating overhead — salaries, rent, marketing, etc.', 'Financial statements', 'Beginner', null),
  ('fin-016', 'What is EBITDA?', '["Equity before income","Earnings before interest, taxes, depreciation, amortization","Net income","Free cash flow"]'::jsonb, 1, 'EBITDA strips out interest, taxes, and non-cash D&A to focus on operating performance.', 'Financial statements', 'Beginner', null),
  ('fin-017', 'What is EBIT?', '["Operating income","Earnings before interest and taxes","Net income","Gross profit"]'::jsonb, 1, 'EBIT = EBITDA − D&A, often equivalent to operating income.', 'Financial statements', 'Beginner', null),
  ('fin-018', 'What are accounts receivable?', '["Cash owed to suppliers","Money owed to the company by customers","Inventory","Equipment"]'::jsonb, 1, 'Receivables are amounts customers owe for goods/services already delivered.', 'Financial statements', 'Beginner', null),
  ('fin-019', 'What are accounts payable?', '["Money owed to customers","Money the company owes to suppliers","Tax expense","Revenue"]'::jsonb, 1, 'Payables are amounts the company owes to suppliers.', 'Financial statements', 'Beginner', null),
  ('fin-020', 'What is inventory?', '["Cash","Goods held for sale or in production","Receivables","Liabilities"]'::jsonb, 1, 'Inventory is raw materials, work-in-progress, and finished goods awaiting sale.', 'Financial statements', 'Beginner', null),
  ('fin-021', 'What is goodwill?', '["Cash reserves","Premium paid in an acquisition above identifiable asset value","Inventory write-up","Net income"]'::jsonb, 1, 'Goodwill arises in acquisitions when purchase price exceeds the fair value of net identifiable assets.', 'Financial statements', 'Beginner', null),
  ('fin-022', 'What is shareholders'' equity?', '["Total assets","Net worth: assets minus liabilities","Net income","Revenue"]'::jsonb, 1, 'Shareholders'' equity is the residual claim — assets minus liabilities.', 'Financial statements', 'Beginner', null),
  ('fin-023', 'What is retained earnings?', '["Cash on hand","Cumulative net income retained in the business (not paid as dividends)","Capital raised","COGS"]'::jsonb, 1, 'Retained earnings accumulate prior profits not distributed to shareholders.', 'Financial statements', 'Beginner', null),
  ('fin-024', 'Which is true about non-GAAP earnings?', '["Always equal to GAAP","Company-adjusted numbers — useful but can mask real expenses","SEC-mandated","Required for taxes"]'::jsonb, 1, 'Non-GAAP measures strip out items like stock comp — useful but require scrutiny.', 'Financial statements', 'Beginner', null),
  ('fin-025', 'Which is most likely capital expenditure (capex)?', '["Salaries","New manufacturing equipment","Rent","Marketing"]'::jsonb, 1, 'Capex is spending on long-lived assets like equipment, factories, software.', 'Financial statements', 'Beginner', null),
  ('fin-026', 'What is operating cash flow?', '["Profit","Cash generated from core operations after working capital changes","Investing inflow","Free cash flow"]'::jsonb, 1, 'OCF is cash produced by the actual business operations, adjusting for non-cash items and working capital.', 'Financial statements', 'Beginner', null),
  ('fin-027', 'What is free cash flow?', '["Operating cash flow minus capital expenditures","Net income","Revenue","Gross margin"]'::jsonb, 0, 'FCF = OCF − capex. It''s the cash truly available after maintaining the business.', 'Financial statements', 'Beginner', null),
  ('fin-028', 'What is the matching principle?', '["Match revenue to cash","Expenses recognized in the same period as related revenues","Match assets to equity","Match periods to taxes"]'::jsonb, 1, 'Accrual accounting matches expenses to the revenues they produce, not when cash moves.', 'Financial statements', 'Beginner', null),
  ('fin-029', 'What is accrual accounting?', '["Cash basis","Recognizes revenue/expenses when earned/incurred, regardless of cash","Tax method","Bond accounting only"]'::jsonb, 1, 'Accrual recognizes revenue when earned and expenses when incurred — independent of cash timing.', 'Financial statements', 'Beginner', null),
  ('fin-030', 'Which is true about deferred revenue?', '["Earned but not yet received","Cash received but services/goods not yet delivered","Same as receivables","Treated as expense"]'::jsonb, 1, 'Deferred revenue is a liability — the company owes the customer future delivery.', 'Financial statements', 'Beginner', null),
  ('fin-031', 'Which is true about "quality of revenue"?', '["All revenue is equal","Recurring, paying-customer revenue is higher quality than one-time or barter","Quality is irrelevant","Always reported in cash"]'::jsonb, 1, 'High-quality revenue is sticky, recurring, and converts to cash promptly.', 'Financial statements', 'Intermediate', null),
  ('fin-032', 'Which expense reduces taxable income but is non-cash?', '["Salaries","Depreciation/amortization","Rent","Inventory purchase"]'::jsonb, 1, 'D&A reduces taxable income but doesn''t consume cash in the period.', 'Financial statements', 'Intermediate', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('fin-033', 'Which is true about "accounts receivable growing faster than revenue"?', '["Healthy sign","Warning: customers may be paying slower, hurting cash conversion","Always temporary","Always restated"]'::jsonb, 1, 'Rising DSO can signal weakening collections, customer credit issues, or aggressive revenue recognition.', 'Financial statements', 'Intermediate', null),
  ('fin-034', 'What is DSO (days sales outstanding)?', '["Profit margin","Average days to collect receivables","Inventory turnover","Tax rate"]'::jsonb, 1, 'DSO = (AR / revenue) × days; lower means faster collections.', 'Financial statements', 'Intermediate', null),
  ('fin-035', 'Which is true about "goodwill" on the balance sheet?', '["Always amortized","Tested annually for impairment, not amortized under US GAAP","Cash-backed","Tax-deductible"]'::jsonb, 1, 'US GAAP requires annual impairment testing of goodwill rather than scheduled amortization.', 'Financial statements', 'Intermediate', null),
  ('fin-036', 'Which is true about "intangible assets"?', '["Always cash","Non-physical assets like patents, brands, customer relationships","Always goodwill","Same as inventory"]'::jsonb, 1, 'Intangibles are non-physical valuable assets — IP, brand, customer lists.', 'Financial statements', 'Intermediate', null),
  ('fin-037', 'Which is the "current ratio"?', '["Current assets / current liabilities","Revenue / equity","Net income / sales","Debt / equity"]'::jsonb, 0, 'Current ratio measures short-term liquidity — assets vs liabilities due within a year.', 'Financial statements', 'Intermediate', null),
  ('fin-038', 'Which is the "quick ratio" (acid test)?', '["Current assets / current liabilities","(Cash + receivables + securities) / current liabilities","Revenue / cogs","Net income / liabilities"]'::jsonb, 1, 'Quick ratio excludes inventory — a stricter liquidity test.', 'Financial statements', 'Intermediate', null),
  ('fin-039', 'Which is true about "capitalizing" expenses?', '["Hits income immediately","Recording as an asset, spreading cost over future periods","Avoids reporting","Required for all costs"]'::jsonb, 1, 'Capitalization defers expense recognition by treating outlays as assets that depreciate/amortize.', 'Financial statements', 'Intermediate', null),
  ('fin-040', 'Which is true about "R&D under US GAAP"?', '["Capitalized","Generally expensed as incurred","Treated as goodwill","Tax-only"]'::jsonb, 1, 'Most R&D is expensed under US GAAP — different from IFRS which allows some capitalization.', 'Financial statements', 'Intermediate', null),
  ('fin-041', 'What is "deferred tax"?', '["Cash tax","Tax effect of timing differences between book and tax accounting","Sales tax","Property tax"]'::jsonb, 1, 'Deferred taxes arise when book income and taxable income differ in timing.', 'Financial statements', 'Intermediate', null),
  ('fin-042', 'What is a "contingent liability"?', '["Definite obligation","Potential obligation depending on a future event (lawsuit, warranty claim)","Always cash","An asset"]'::jsonb, 1, 'Contingent liabilities are disclosed when probable and estimable; otherwise just noted in footnotes.', 'Financial statements', 'Intermediate', null),
  ('fin-043', 'Which is true about "operating lease accounting" (ASC 842)?', '["Off-balance-sheet","Right-of-use asset and lease liability now on the balance sheet","Cash only","Equity"]'::jsonb, 1, 'Post-ASC 842/IFRS 16, leases appear on the balance sheet as ROU assets and lease liabilities.', 'Financial statements', 'Intermediate', null),
  ('fin-044', 'What is "net debt"?', '["Total debt","Total debt minus cash and equivalents","Equity","Working capital"]'::jsonb, 1, 'Net debt nets cash against debt for a clearer leverage picture.', 'Financial statements', 'Intermediate', null),
  ('fin-045', 'What is "debt-to-equity" ratio?', '["Total debt / equity","Cash / equity","Debt / assets","Equity / debt"]'::jsonb, 0, 'Debt/equity measures leverage from a capital-structure standpoint.', 'Financial statements', 'Intermediate', null),
  ('fin-046', 'Which is true about "interest coverage ratio"?', '["Debt / interest","EBIT / interest expense","Cash / debt","Equity / liabilities"]'::jsonb, 1, 'Interest coverage gauges how comfortably EBIT covers interest payments.', 'Financial statements', 'Intermediate', null),
  ('fin-047', 'What does the "cash conversion cycle" measure?', '["Tax timing","Time from paying for inputs to collecting cash from sales","Inventory only","Receivables only"]'::jsonb, 1, 'CCC = DSO + DIO − DPO. Shorter cycles mean less capital tied up.', 'Financial statements', 'Intermediate', null),
  ('fin-048', 'What is "inventory turnover"?', '["COGS / average inventory","Revenue / equity","Cash / inventory","Net income / inventory"]'::jsonb, 0, 'Inventory turnover shows how many times inventory is sold and replaced in a period.', 'Financial statements', 'Intermediate', null),
  ('fin-049', 'Which is true about "earnings management via accruals"?', '["Doesn''t exist","Aggressive accrual policies can boost reported earnings without underlying cash improvement","Always illegal","Increases cash"]'::jsonb, 1, 'Companies can shift accruals to manage reported earnings — sometimes legally, sometimes not.', 'Financial statements', 'Intermediate', null),
  ('fin-050', 'Which is true about "channel stuffing"?', '["Boosts cash","Pulling future demand forward by pushing inventory to distributors","Reduces revenue","Tax strategy"]'::jsonb, 1, 'Channel stuffing accelerates revenue recognition by overloading distributors — unsustainable.', 'Financial statements', 'Intermediate', null),
  ('fin-051', 'Which is true about "working capital" and growth?', '["Always positive","Rapid growth can consume working capital, straining cash even with rising profits","Always negative","Eliminated by accrual"]'::jsonb, 1, 'Fast-growing companies often need more receivables and inventory, tying up cash.', 'Financial statements', 'Advanced', null),
  ('fin-052', 'Which is true about "negative working capital"?', '["Always bad","Can be very desirable: customers pay before suppliers, financing growth","Always fraud","Tax mistake"]'::jsonb, 1, 'Negative working capital can be a strength — customers (or subscribers) pay upfront, generating float.', 'Financial statements', 'Advanced', null),
  ('fin-053', 'Which is true about "reconciliation of GAAP to non-GAAP"?', '["Optional","SEC requires public reconciliation when non-GAAP figures are presented","Banned","Forbidden in 10-K"]'::jsonb, 1, 'Reg G requires reconciliation of any non-GAAP measure to its closest GAAP counterpart.', 'Financial statements', 'Advanced', null),
  ('fin-054', 'Which is the most cash-faithful metric?', '["Reported EPS","Free cash flow","EBITDA","Gross margin"]'::jsonb, 1, 'FCF most closely mirrors actual cash generation available to capital providers.', 'Financial statements', 'Advanced', null),
  ('fin-055', 'Which is true about "stock-based compensation" on the cash flow statement?', '["Cash outflow","Added back to net income in operating section — non-cash","Treated as capex","Tax deduction only"]'::jsonb, 1, 'SBC is added back to net income in operating cash flow because it''s non-cash — but it dilutes shareholders.', 'Financial statements', 'Advanced', null),
  ('fin-056', 'Which is true about "asset turnover ratio"?', '["Revenue / total assets — efficiency at generating sales","Net income / equity","Cash / debt","Inventory / sales"]'::jsonb, 0, 'Asset turnover measures how productively assets generate revenue.', 'Financial statements', 'Advanced', null),
  ('fin-057', 'Which is true about "DuPont decomposition of ROE"?', '["Single metric","ROE = net margin × asset turnover × equity multiplier","Random formula","Banned by GAAP"]'::jsonb, 1, 'DuPont breaks ROE into operational, efficiency, and leverage components.', 'Financial statements', 'Advanced', null),
  ('fin-058', 'Which is true about "return on invested capital" (ROIC)?', '["Same as ROE","Operating profit (after tax) / invested capital — captures true business returns","Cash measure","Equity-only"]'::jsonb, 1, 'ROIC measures returns on the total capital employed (debt + equity), agnostic to financing mix.', 'Financial statements', 'Advanced', null),
  ('fin-059', 'Which is true about "capex vs maintenance capex"?', '["Identical","Maintenance capex preserves current operations; growth capex expands them","Same as goodwill","Equity term"]'::jsonb, 1, 'Distinguishing maintenance from growth capex matters for understanding true free cash flow.', 'Financial statements', 'Advanced', null),
  ('fin-060', 'Which is true about "deferred revenue growth"?', '["Negative signal","Positive indicator of forward bookings/subscriber commitments","Equals revenue","Reduces cash"]'::jsonb, 1, 'Growing deferred revenue is a leading indicator of business momentum, especially in subscription models.', 'Financial statements', 'Advanced', null),
  ('fin-061', 'Which is true about "accrued liabilities"?', '["Cash outflow now","Expenses incurred but not yet paid (wages, taxes, utilities)","Equity","Inventory"]'::jsonb, 1, 'Accrued liabilities reflect expenses recognized before the actual payment.', 'Financial statements', 'Advanced', null),
  ('fin-062', 'Which is true about "impairment"?', '["Routine D&A","Write-down of an asset''s carrying value below recoverable amount","Cash inflow","Always tax-savings only"]'::jsonb, 1, 'Impairments adjust assets down when their carrying value exceeds expected recoverable value.', 'Financial statements', 'Advanced', null),
  ('fin-063', 'Which is true about "capital structure"?', '["Only equity","The mix of debt and equity financing a company","Cash balance","Total revenue"]'::jsonb, 1, 'Capital structure is how a company finances itself — the debt/equity blend.', 'Financial statements', 'Advanced', null),
  ('fin-064', 'Which is true about "book value" vs "market value"?', '["Always equal","Book reflects accounting history; market reflects investor expectations","Always opposite","Same thing"]'::jsonb, 1, 'Book value is historical accounting equity; market value is the current stock-market valuation.', 'Financial statements', 'Advanced', null),
  ('fin-065', 'Which is true about "economic earnings"?', '["Reported earnings","Earnings adjusted for the true cost of capital and replacement of capital assets","Cash flow only","Tax basis"]'::jsonb, 1, 'Economic earnings (EVA / residual income) reflect returns above the cost of capital — true value creation.', 'Financial statements', 'Advanced', null),
  ('fin-066', 'Which is true about "depreciation methods"?', '["Always straight-line","Straight-line, declining-balance, units-of-production each spread cost differently","Cash basis","Banned"]'::jsonb, 1, 'Different methods front- or back-load depreciation, affecting reported earnings timing.', 'Financial statements', 'Advanced', null),
  ('fin-067', 'Which is true about "accruals quality"?', '["High accruals always great","Persistent large accruals relative to cash flow can foreshadow earnings reversals","Always cash","Tax issue"]'::jsonb, 1, 'High accruals (income that hasn''t shown up in cash) often precede future earnings disappointments.', 'Financial statements', 'Advanced', null),
  ('rat-001', 'What is the P/E ratio?', '["Price ÷ revenue","Price ÷ earnings per share","Price ÷ book value","Price ÷ dividend"]'::jsonb, 1, 'P/E = price per share ÷ earnings per share. A valuation multiple of profit.', 'Ratios & valuation', 'Basic', null),
  ('rat-002', 'A high P/E suggests:', '["The market expects little growth","The market expects strong future earnings growth (or stock is overvalued)","Stock is cheap","Company is unprofitable"]'::jsonb, 1, 'High P/E reflects high expectations — fast growth or premium quality (or simply overvalued).', 'Ratios & valuation', 'Basic', null),
  ('rat-003', 'A low P/E suggests:', '["Always undervalued","Lower growth expectations or possibly a value trap","Always overvalued","No earnings"]'::jsonb, 1, 'Low P/E can indicate undervaluation or signal real fundamental risk.', 'Ratios & valuation', 'Basic', null),
  ('rat-004', 'What is the P/B ratio?', '["Price ÷ book value per share","Price ÷ earnings","Price ÷ dividends","Price ÷ revenue"]'::jsonb, 0, 'P/B compares market price to accounting book value per share.', 'Ratios & valuation', 'Basic', null),
  ('rat-005', 'What is the P/S ratio?', '["Price ÷ sales per share","Price ÷ earnings","Price ÷ assets","Price ÷ cash"]'::jsonb, 0, 'P/S divides market cap by revenue — useful when earnings are negative.', 'Ratios & valuation', 'Basic', null),
  ('rat-006', 'What is dividend yield?', '["Annual dividend per share ÷ stock price","EPS ÷ price","Buyback yield","Coupon rate"]'::jsonb, 0, 'Dividend yield is the annual dividend divided by current price.', 'Ratios & valuation', 'Basic', null),
  ('rat-007', 'What is earnings yield?', '["EPS ÷ price (inverse of P/E)","Dividend yield","Sales / price","Bond yield"]'::jsonb, 0, 'Earnings yield = 1/PE. Useful for comparing equity earnings to bond yields.', 'Ratios & valuation', 'Basic', null),
  ('rat-008', 'What is market cap?', '["Total assets","Share price × shares outstanding","Net income","Total equity"]'::jsonb, 1, 'Market cap is the total market value of all outstanding shares.', 'Ratios & valuation', 'Basic', null),
  ('rat-009', 'What is enterprise value (EV)?', '["Same as market cap","Market cap + debt − cash","Equity only","Revenue × multiple"]'::jsonb, 1, 'EV represents the total value of the business — to both debt and equity holders.', 'Ratios & valuation', 'Basic', null),
  ('rat-010', 'Why is EV used instead of market cap?', '["EV is simpler","EV reflects the cost to acquire the entire business, capital-structure-agnostic","EV ignores debt","EV is mandatory"]'::jsonb, 1, 'EV gives a capital-structure-neutral view — useful when comparing companies with different debt loads.', 'Ratios & valuation', 'Basic', null),
  ('rat-011', 'What is EV/EBITDA?', '["A leverage ratio","Enterprise value ÷ EBITDA — a popular operating-business multiple","Equity / earnings","Cash / revenue"]'::jsonb, 1, 'EV/EBITDA values the operating business independent of capital structure or tax.', 'Ratios & valuation', 'Beginner', null),
  ('rat-012', 'What is EV/Revenue (or EV/Sales)?', '["Equity-based ratio","Enterprise value ÷ revenue — used when EBITDA is negative","Tax ratio","Cash ratio"]'::jsonb, 1, 'EV/Revenue works for unprofitable or early-stage companies where EBITDA isn''t meaningful.', 'Ratios & valuation', 'Beginner', null),
  ('rat-013', 'What is the PEG ratio?', '["P/E divided by EPS growth rate","P/E only","Earnings ÷ growth","Cash / earnings"]'::jsonb, 0, 'PEG = P/E ÷ growth rate. Adjusts P/E for expected growth.', 'Ratios & valuation', 'Beginner', null),
  ('rat-014', 'A PEG of 1.0 traditionally suggests:', '["Overvalued","Fairly valued relative to growth","Undervalued always","No earnings"]'::jsonb, 1, 'PEG near 1.0 is often considered fair value, though it''s an oversimplification.', 'Ratios & valuation', 'Beginner', null),
  ('rat-015', 'What is the dividend payout ratio?', '["Dividend ÷ market cap","Dividend ÷ net income","Dividend ÷ book value","Dividend / revenue"]'::jsonb, 1, 'Payout ratio measures what share of earnings is paid out as dividends.', 'Ratios & valuation', 'Beginner', null),
  ('rat-016', 'A payout ratio above 100% means:', '["Healthy","Dividends exceed earnings — typically unsustainable","Required by law","Negative dividends"]'::jsonb, 1, 'Paying more than you earn isn''t sustainable long-term without depleting cash.', 'Ratios & valuation', 'Beginner', null),
  ('rat-017', 'What is return on assets (ROA)?', '["Net income ÷ total assets","Net income ÷ equity","Revenue ÷ assets","Operating income ÷ debt"]'::jsonb, 0, 'ROA measures how productively a company uses its assets to generate profit.', 'Ratios & valuation', 'Beginner', null),
  ('rat-018', 'What is return on equity (ROE)?', '["Net income ÷ shareholders'' equity","Net income ÷ assets","Revenue ÷ equity","Cash / equity"]'::jsonb, 0, 'ROE captures profit generated per dollar of equity capital.', 'Ratios & valuation', 'Beginner', null),
  ('rat-019', 'What is operating margin?', '["Gross profit ÷ revenue","Operating income ÷ revenue","Net income ÷ revenue","Cash ÷ revenue"]'::jsonb, 1, 'Operating margin = operating income / revenue. Reflects core business profitability.', 'Ratios & valuation', 'Beginner', null),
  ('rat-020', 'What is gross margin?', '["Gross profit ÷ revenue","Operating margin","Net margin","Tax rate"]'::jsonb, 0, 'Gross margin = (revenue − COGS) / revenue. Higher means more pricing power or efficient production.', 'Ratios & valuation', 'Beginner', null),
  ('rat-021', 'What is net margin?', '["Operating income / revenue","Net income / revenue","Gross profit / revenue","Cash / revenue"]'::jsonb, 1, 'Net margin is bottom-line profit as a percent of revenue.', 'Ratios & valuation', 'Beginner', null),
  ('rat-022', 'Which is true about "discounted cash flow" (DCF)?', '["Backward-looking","Values business by projecting future cash flows and discounting them to present value","P/E only","Bond-only"]'::jsonb, 1, 'DCF estimates intrinsic value by discounting forecasted future cash flows.', 'Ratios & valuation', 'Beginner', null),
  ('rat-023', 'Which is true about the "discount rate" in DCF?', '["Always zero","Reflects time value of money and risk; higher discount → lower present value","Always 10%","Equal to inflation"]'::jsonb, 1, 'The discount rate combines time value and risk; higher rates compress DCF values.', 'Ratios & valuation', 'Beginner', null),
  ('rat-024', 'What is the "terminal value" in a DCF?', '["First year cash","The value of cash flows beyond the explicit forecast period","Salvage value","Book value"]'::jsonb, 1, 'Terminal value captures all cash flows after the explicit forecast window — often dominates DCF outputs.', 'Ratios & valuation', 'Beginner', null),
  ('rat-025', 'What is "WACC"?', '["Working assets cash cycle","Weighted average cost of capital — blended cost of debt and equity","Wages and capital cost","Working capital"]'::jsonb, 1, 'WACC blends after-tax debt cost and equity cost weighted by their share of capital.', 'Ratios & valuation', 'Beginner', null),
  ('rat-026', 'Which is true about "cost of equity"?', '["Always zero","The return equity investors demand for their risk; often estimated via CAPM","Always the dividend yield","Same as bond yield"]'::jsonb, 1, 'Cost of equity is the required return on equity capital, typically derived from CAPM.', 'Ratios & valuation', 'Beginner', null),
  ('rat-027', 'What is CAPM?', '["Capital Asset Pricing Model: r = rf + β × (rm − rf)","A regulator","An index","Cash model"]'::jsonb, 0, 'CAPM estimates required return from risk-free rate, beta, and equity risk premium.', 'Ratios & valuation', 'Beginner', null),
  ('rat-028', 'What is the "equity risk premium"?', '["Bond yield","Expected market return minus risk-free rate","Currency premium","Tax rate"]'::jsonb, 1, 'ERP is the extra expected return for bearing equity risk versus risk-free assets.', 'Ratios & valuation', 'Beginner', null),
  ('rat-029', 'What is "beta" in CAPM?', '["Volatility","A stock''s sensitivity to market movements","Dividend rate","P/E"]'::jsonb, 1, 'Beta scales systematic risk: 1.0 moves with market, >1 amplifies, <1 dampens.', 'Ratios & valuation', 'Beginner', null),
  ('rat-030', 'Which is true about "comparable company analysis"?', '["Use only one peer","Value a company using multiples of similar publicly traded firms","DCF only","No multiples"]'::jsonb, 1, 'Comps value a company using market-derived multiples from similar businesses.', 'Ratios & valuation', 'Beginner', null),
  ('rat-031', 'Which is true about "precedent transactions"?', '["Theoretical only","Value derived from multiples paid in past M&A deals","Bond pricing","Index method"]'::jsonb, 1, 'Precedent transaction analysis uses observed deal multiples — usually includes a control premium.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-032', 'Which is true about "control premium"?', '["Always zero","Buyer typically pays above current market price for full control","Negative discount","Always 1%"]'::jsonb, 1, 'Acquirers usually pay 20-40%+ premiums to gain control of a target company.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-033', 'Which is true about "liquidity discount" for private firms?', '["Same as public","Private stakes trade at a discount due to lack of marketability","Liquid","Premium"]'::jsonb, 1, 'Private firm valuations are typically discounted for lack of liquidity vs publicly traded equivalents.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-034', 'Which is true about "normalizing earnings" for valuation?', '["Use raw earnings","Adjust for one-time items to estimate sustainable earnings power","Use highest year","Use lowest year"]'::jsonb, 1, 'Analysts adjust reported earnings for non-recurring items to find sustainable run-rate.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-035', 'Which is true about "forward vs trailing multiples"?', '["Both identical","Forward uses estimates; trailing uses reported — forward is more relevant if estimates are reliable","Trailing always wrong","Forward always right"]'::jsonb, 1, 'Forward multiples reflect expectations; trailing reflect history. Both have uses.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-036', 'Which is true about "P/E for cyclical companies"?', '["Best at peak","Peak P/E often looks low at cycle tops and high at cycle bottoms — misleading","Stable across cycle","Not used"]'::jsonb, 1, 'Cyclicals can show deceptively low P/E at peaks (earnings about to fall) and high P/E at troughs.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-037', 'Which is true about "Shiller P/E" (CAPE)?', '["Single-year P/E","Price ÷ 10-year inflation-adjusted earnings — smooths cycles","Forward P/E","Bond yield"]'::jsonb, 1, 'CAPE divides price by 10-year real earnings to smooth cyclical noise.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-038', 'Which is true about "price-to-FCF"?', '["Avoids non-cash distortions in earnings","Equal to P/E","Always lower than P/E","Banned"]'::jsonb, 0, 'P/FCF often gives a clearer profitability view by skipping non-cash items that affect earnings.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-039', 'Which is true about "market cap vs enterprise value" in a leveraged firm?', '["Equal","EV materially exceeds market cap because of debt","EV < market cap","Both equal cash"]'::jsonb, 1, 'Heavy debt makes EV substantially larger than market cap.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-040', 'Which is true about "sum-of-the-parts" valuation?', '["One multiple for everything","Value each segment separately, then sum","Bond-only","Tax method"]'::jsonb, 1, 'SOTP values business segments separately, capturing diverse economics within a conglomerate.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-041', 'Which is true about "dividend discount model"?', '["DCF on cash flows","Values stock as present value of expected future dividends","Bond yield","P/E based"]'::jsonb, 1, 'DDM values a stock as the present value of all expected future dividends.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-042', 'Which is true about "Gordon Growth Model"?', '["Two-stage DCF","P = D / (r − g) — perpetual dividend growth model","Risk-free rate only","Inverse of P/E"]'::jsonb, 1, 'Gordon Growth values a perpetuity of dividends growing at constant g, requires r > g.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-043', 'Which is true about "residual income" valuation?', '["Net income only","Equity value = book value + present value of future residual incomes","Bond pricing","Tax accounting"]'::jsonb, 1, 'Residual income models account for earnings above the cost of equity to find intrinsic value.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-044', 'Which is true about "DCF sensitivity" to terminal value?', '["Negligible","Often dominant — small changes in terminal growth or discount rate swing valuation dramatically","Fixed","Zero"]'::jsonb, 1, 'Terminal value typically drives 60-80% of total DCF value — small assumption changes matter a lot.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-045', 'Which is true about "reverse DCF"?', '["Solve for the assumptions implied by current price","Discount future losses","Tax filing","Bond pricing"]'::jsonb, 0, 'Reverse DCF starts with current price and backs out the growth/cash-flow assumptions required to justify it.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-046', 'Which is true about "multiple expansion"?', '["Stock falls","Stock rises because P/E (or another multiple) increased, not earnings","Stock split","Buyback"]'::jsonb, 1, 'Multiple expansion = price up driven by higher valuation multiple, not improved fundamentals.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-047', 'Which is true about "multiple compression"?', '["Stock rises","Stock falls because valuation multiple shrinks, often despite stable earnings","Always fraud","Never happens"]'::jsonb, 1, 'Multiple compression typically hits high-multiple stocks when sentiment or rates change.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-048', 'Which is true about "high multiple + rising rates"?', '["Multiples expand","Multiples typically compress; growth-stock valuations are particularly rate-sensitive","No effect","Always positive"]'::jsonb, 1, 'Higher rates raise discount rates, hitting long-duration cash flow stocks hardest.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-049', 'Which is true about "price-to-book < 1"?', '["Bankruptcy","Stock trades below accounting book value — may indicate distress or hidden value","Always overvalued","Required for dividends"]'::jsonb, 1, 'P/B < 1 can signal real distress or be a value opportunity if book value is conservative.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-050', 'Which is true about "asset-light vs asset-heavy" comparisons?', '["Same multiples apply","Asset-light businesses often warrant higher EBITDA multiples","Always reverse","Use book value only"]'::jsonb, 1, 'Asset-light businesses convert revenue to cash with less reinvestment, supporting higher multiples.', 'Ratios & valuation', 'Intermediate', null),
  ('rat-051', 'Which is true about "DCF circularity"?', '["No circularity","Cost of equity depends on capital structure; capital structure depends on value — iterative","Always linear","Fixed"]'::jsonb, 1, 'DCF inputs (WACC, capital structure, value) are interdependent — careful iteration is needed.', 'Ratios & valuation', 'Advanced', null),
  ('rat-052', 'Which is true about "adjusted present value" (APV)?', '["Standard DCF","Separately values unlevered cash flows and tax shield from debt","Sum-of-parts","Forward P/E"]'::jsonb, 1, 'APV decomposes DCF into operating value and financing-side effects, useful for leveraged structures.', 'Ratios & valuation', 'Advanced', null),
  ('rat-053', 'Which is true about "WACC pitfalls in distress"?', '["Always reliable","Cost of debt rises with risk; equity beta destabilizes — WACC becomes unreliable","Stable","Equal to cash"]'::jsonb, 1, 'In distress, both debt and equity costs rise sharply; standard WACC breaks down.', 'Ratios & valuation', 'Advanced', null),
  ('rat-054', 'Which is true about "option pricing for distressed equity"?', '["Use DCF only","Equity in highly leveraged firms can be modeled as a call option on enterprise value","Bond-only","Tax model"]'::jsonb, 1, 'Merton''s model treats equity as a long call on firm value with strike = debt — captures distress optionality.', 'Ratios & valuation', 'Advanced', null),
  ('rat-055', 'Which is true about "real options" in valuation?', '["No optionality","Strategic flexibility (delay, expand, abandon) has value beyond expected cash flows","Same as financial options","Tax credit"]'::jsonb, 1, 'Real-options valuation captures managerial flexibility — value that DCF often understates.', 'Ratios & valuation', 'Advanced', null),
  ('rat-056', 'Which is true about "private company valuation discounts"?', '["No discounts","DLOM (lack of marketability) and DLOC (lack of control) typically apply","Premium","Tax-only"]'::jsonb, 1, 'Private interests typically trade below comparable public-market values due to liquidity and control adjustments.', 'Ratios & valuation', 'Advanced', null),
  ('rat-057', 'Which is true about "liquidity premium" in WACC?', '["Always zero","Illiquid stocks may carry higher cost of equity reflecting liquidity premium","Equal to inflation","Always 1%"]'::jsonb, 1, 'Investors demand extra return for illiquidity — adjusting cost of equity upward.', 'Ratios & valuation', 'Advanced', null),
  ('rat-058', 'Which is true about "country risk premium"?', '["Same globally","Required return rises in higher-risk countries; adjusts equity discount rate","Bond-only","Same as inflation"]'::jsonb, 1, 'Equity costs in higher-risk countries include country risk premia, often derived from sovereign spreads.', 'Ratios & valuation', 'Advanced', null),
  ('rat-059', 'Which is true about "size premium" (Fama-French SMB)?', '["Same return as large-cap","Small-cap stocks have historically earned higher returns, partly a risk premium","Higher in large-cap","Always zero"]'::jsonb, 1, 'The size premium suggests small-cap stocks historically deliver higher returns, possibly compensating for risk.', 'Ratios & valuation', 'Advanced', null),
  ('rat-060', 'Which is true about "value premium" (HML)?', '["Same returns as growth","Value stocks have historically outperformed growth, though periods of underperformance exist","Always equal","Zero post-1990"]'::jsonb, 1, 'The HML factor — high-book-to-market minus low — has produced a long-term value premium, with volatile periods.', 'Ratios & valuation', 'Advanced', null),
  ('rat-061', 'Which is true about "profitability factor" (RMW)?', '["Profitability doesn''t matter","More profitable firms have historically outperformed less profitable peers","Negative premium","Random"]'::jsonb, 1, 'Fama-French''s RMW factor shows robust-minus-weak profitability — quality premium.', 'Ratios & valuation', 'Advanced', null),
  ('rat-062', 'Which is true about "investment factor" (CMA)?', '["Investing more is better","Conservative investing companies (low asset growth) outperform aggressive ones on average","Random","Zero"]'::jsonb, 1, 'The CMA factor shows that lower-investment firms tend to outperform high-investment ones.', 'Ratios & valuation', 'Advanced', null),
  ('rat-063', 'Which is true about "reverse engineering" market implied growth?', '["Cannot be done","From current price + WACC, back out implied long-term growth assumption","Always identical","Bond model"]'::jsonb, 1, 'Reverse DCF lets you compute the growth rate the market is implicitly assuming.', 'Ratios & valuation', 'Advanced', null),
  ('rat-064', 'Which is true about "cycle-adjusted" multiples?', '["Single year","Average earnings/cash flow across a cycle for a more representative multiple","Random","Always tax-adjusted"]'::jsonb, 1, 'Smoothing earnings over a cycle avoids the trap of capitalizing peak or trough single-year figures.', 'Ratios & valuation', 'Advanced', null),
  ('rat-065', 'Which is true about "economic value added" (EVA)?', '["Same as net income","NOPAT − (invested capital × WACC) — measures value above cost of capital","Cash flow","Revenue"]'::jsonb, 1, 'EVA quantifies whether returns exceed the cost of capital — a true value-creation metric.', 'Ratios & valuation', 'Advanced', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('rat-066', 'Which is true about "option-based equity valuation" for distressed firms?', '["Use book value only","Equity behaves like a call on assets struck at debt face value","Tax method","Always linear"]'::jsonb, 1, 'In highly levered or distressed firms, equity holders effectively own a long call on firm value.', 'Ratios & valuation', 'Advanced', null),
  ('rat-067', 'Which is true about "valuation in negative-rate environments"?', '["Same as positive rates","Lower discount rates inflate present values, especially for long-duration assets","Eliminated","Always lower"]'::jsonb, 1, 'When discount rates fall sharply, long-duration cash flows (growth stocks, long bonds) gain disproportionately.', 'Ratios & valuation', 'Advanced', null),
  ('mac-001', 'What is the Federal Reserve?', '["A bank","The US central bank that sets monetary policy","An exchange","An ETF sponsor"]'::jsonb, 1, 'The Fed is the US central bank — it conducts monetary policy and regulates banks.', 'Macro & monetary policy', 'Basic', null),
  ('mac-002', 'What is the FOMC?', '["A regulator","Federal Open Market Committee — the Fed body that sets policy rates","An index","A bank"]'::jsonb, 1, 'The FOMC is the policy-making committee within the Fed that sets the federal funds rate.', 'Macro & monetary policy', 'Basic', null),
  ('mac-003', 'What is the federal funds rate?', '["Mortgage rate","Overnight interbank lending rate targeted by the Fed","Prime rate","Treasury yield"]'::jsonb, 1, 'The fed funds rate is the rate banks lend each other overnight; the Fed targets a range.', 'Macro & monetary policy', 'Basic', null),
  ('mac-004', 'What is inflation?', '["A drop in prices","General sustained rise in prices over time","Deflation","Stagflation"]'::jsonb, 1, 'Inflation is the broad rise in consumer prices over time.', 'Macro & monetary policy', 'Basic', null),
  ('mac-005', 'What is deflation?', '["Inflation","A sustained drop in the general price level","Stagnation","Hyperinflation"]'::jsonb, 1, 'Deflation is broadly falling prices — often associated with weak demand and high real debt burdens.', 'Macro & monetary policy', 'Basic', null),
  ('mac-006', 'What is stagflation?', '["Strong growth + low inflation","High inflation + stagnant growth","Boom","Recession"]'::jsonb, 1, 'Stagflation pairs sluggish growth or high unemployment with persistent inflation.', 'Macro & monetary policy', 'Basic', null),
  ('mac-007', 'What does GDP measure?', '["Stock market","Total value of goods/services produced in an economy","Inflation","Interest rates"]'::jsonb, 1, 'Gross Domestic Product measures total economic output.', 'Macro & monetary policy', 'Basic', null),
  ('mac-008', 'What is a recession?', '["Boom","Significant decline in economic activity, often defined as 2+ quarters of negative GDP growth","Mild slowdown","High inflation"]'::jsonb, 1, 'Recessions are broad, deep, durable declines in activity.', 'Macro & monetary policy', 'Basic', null),
  ('mac-009', 'What is the CPI?', '["Bond index","Consumer Price Index — measures price changes in a basket of consumer goods","Currency index","Bank index"]'::jsonb, 1, 'CPI tracks consumer-good price changes — the most-watched inflation gauge.', 'Macro & monetary policy', 'Basic', null),
  ('mac-010', 'Which is true about "core CPI"?', '["Includes everything","Excludes food and energy (volatile components) for a smoother trend","Includes only food","Excludes housing"]'::jsonb, 1, 'Core CPI strips out volatile food and energy to expose underlying inflation.', 'Macro & monetary policy', 'Basic', null),
  ('mac-011', 'Which is the Fed''s preferred inflation gauge?', '["CPI","PCE deflator (personal consumption expenditures)","M2","GDP"]'::jsonb, 1, 'The Fed prefers PCE, especially core PCE, for its broader basket and updated weighting.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-012', 'Which is true about Fed rate hikes?', '["Stimulate borrowing","Generally aim to slow inflation by tightening financial conditions","Always cause recession","Reduce yields"]'::jsonb, 1, 'Higher rates make borrowing more expensive — slowing demand and inflation.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-013', 'Which is true about Fed rate cuts?', '["Slow economy","Generally ease financial conditions, supporting growth","Raise inflation always","Tax cut"]'::jsonb, 1, 'Cuts lower borrowing costs, supporting credit, spending, and risk assets.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-014', 'What is the Fed''s "dual mandate"?', '["Inflation only","Maximum employment + price stability","Stock market + employment","FX rates + inflation"]'::jsonb, 1, 'The Fed targets both maximum sustainable employment and stable prices (~2% inflation).', 'Macro & monetary policy', 'Beginner', null),
  ('mac-015', 'What is quantitative easing (QE)?', '["Rate hike","Large-scale asset purchases by the central bank to inject liquidity","Tax policy","FX intervention"]'::jsonb, 1, 'QE expands the central bank balance sheet by buying bonds — pushing rates down and reserves up.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-016', 'What is quantitative tightening (QT)?', '["Asset purchases","Reducing the central bank balance sheet by letting bonds roll off or selling","Rate cut","Tax policy"]'::jsonb, 1, 'QT reverses QE — shrinking the balance sheet and withdrawing reserves.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-017', 'Which is true about "M2 money supply"?', '["Cash only","Broader monetary aggregate: currency + checking + savings + money market","Treasuries","Equity"]'::jsonb, 1, 'M2 includes cash, checking, savings, and money market funds — a broad money measure.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-018', 'What is fiscal policy?', '["Central bank actions","Government taxing and spending decisions","Trade policy","Currency policy"]'::jsonb, 1, 'Fiscal policy is the government''s spending/taxation lever — distinct from monetary policy.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-019', 'What is monetary policy?', '["Government taxes","Central bank actions to influence money supply and interest rates","Tariffs","Treasury actions"]'::jsonb, 1, 'Monetary policy is the central bank''s toolkit — primarily rates and balance sheet operations.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-020', 'What is unemployment rate?', '["Labor force ÷ population","Unemployed ÷ labor force","Job openings","Wages growth"]'::jsonb, 1, 'Unemployment rate = unemployed who are actively looking ÷ labor force.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-021', 'What is "NAIRU"?', '["Inflation","Non-Accelerating Inflation Rate of Unemployment — unemployment at which inflation is stable","Recession","Real rate"]'::jsonb, 1, 'NAIRU is the unemployment rate consistent with steady inflation — a key Fed reference.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-022', 'What is the "Phillips curve"?', '["GDP-inflation relationship","Trade-off (historical) between unemployment and inflation","Currency relation","Bond curve"]'::jsonb, 1, 'The Phillips curve posits an inverse relationship between unemployment and inflation, though it has weakened.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-023', 'Which is true about "real interest rates"?', '["Nominal − inflation","Nominal × inflation","Always positive","Always zero"]'::jsonb, 0, 'Real rate = nominal rate − inflation. Negative real rates discourage saving.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-024', 'Which is true about inflation expectations?', '["Don''t matter","Self-fulfilling: expected inflation often becomes actual inflation","Always 0%","Always 5%"]'::jsonb, 1, 'Inflation expectations influence wage demands and pricing decisions — they shape outcomes.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-025', 'What is GDP per capita?', '["Total GDP","GDP ÷ population — proxy for average living standard","Wages","Inflation"]'::jsonb, 1, 'GDP per capita normalizes output by population — a rough living-standard proxy.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-026', 'What is a "trade deficit"?', '["Imports > exports","Imports exceed exports","Surplus","Tariff"]'::jsonb, 1, 'A trade deficit means a country imports more than it exports.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-027', 'What is a "trade surplus"?', '["Imports > exports","Exports exceed imports","Equilibrium","Tariff"]'::jsonb, 1, 'A trade surplus means exports exceed imports.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-028', 'What is the "current account"?', '["Equity account","Net trade balance plus net income/transfers with rest of world","Tax account","Capital account"]'::jsonb, 1, 'Current account = net trade + net foreign income + net transfers.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-029', 'What is the "capital account"?', '["Same as current","Records cross-border capital flows and investments","Stock account","Tax account"]'::jsonb, 1, 'The capital (financial) account records inbound/outbound investment flows.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-030', 'Which is true about currency strength and exports?', '["Strong dollar helps US exports","A stronger currency makes exports relatively more expensive abroad","No effect","Always weakens exports"]'::jsonb, 1, 'A stronger home currency typically reduces export competitiveness.', 'Macro & monetary policy', 'Beginner', null),
  ('mac-031', 'Which is true about "yield curve inversion"?', '["Bullish signal","Historically correlated with recession 6-18 months ahead","Always means deflation","No predictive power"]'::jsonb, 1, 'Sustained inversions of the 2s/10s or 3m/10y have preceded most US recessions.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-032', 'Which is true about "forward guidance"?', '["Hidden policy","Central bank communication shaping market expectations for future policy","FX rate","Tax law"]'::jsonb, 1, 'Forward guidance — what the central bank signals it will do — moves rates and asset prices.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-033', 'What is the "Taylor rule"?', '["A tax law","A policy benchmark relating Fed rate to inflation and output gap","FX rule","Buying rule"]'::jsonb, 1, 'Taylor rules give a baseline policy rate from inflation and output gaps — a benchmark.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-034', 'Which is true about "real GDP growth"?', '["Includes inflation","Inflation-adjusted growth — true output growth","Same as nominal","Currency-adjusted"]'::jsonb, 1, 'Real GDP strips out price changes to measure real output growth.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-035', 'Which is true about "output gap"?', '["Zero always","Difference between actual GDP and potential GDP; negative means slack","Positive always","Currency gap"]'::jsonb, 1, 'Output gap shows how far actual output is from sustainable potential — informs policy.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-036', 'Which is true about "oil prices and inflation"?', '["No relationship","Higher energy prices feed into headline inflation but less into core","Always lower inflation","Lower core inflation"]'::jsonb, 1, 'Oil affects headline CPI directly; core CPI strips out energy but second-round effects can leak in.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-037', 'Which is true about "liquidity trap"?', '["Tight monetary policy","Rates near zero where monetary policy loses traction","High inflation","Currency crisis"]'::jsonb, 1, 'In a liquidity trap, cutting rates further has little impact — pushing on a string.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-038', 'Which is true about "helicopter money"?', '["QE","Direct cash distributions to households, often financed by central bank","Tax cut","FX intervention"]'::jsonb, 1, 'Helicopter money refers to direct transfers to citizens, sometimes financed by money creation.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-039', 'Which is true about "velocity of money"?', '["M2 × CPI","Frequency of money exchange per period — falling velocity dampens inflation","Same as M2","FX rate"]'::jsonb, 1, 'Velocity = nominal GDP / money supply. Falling velocity offsets money growth on prices.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-040', 'Which is true about "reserve requirements"?', '["Tax","Banks must hold a percentage of deposits as reserves; current ratio is 0% in US","Equity","Inflation"]'::jsonb, 1, 'The Fed cut required reserves to 0% in 2020; the policy lever shifted to interest on reserve balances.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-041', 'Which is true about "interest on reserves" (IORB)?', '["Tax","Fed pays banks interest on reserves held at the Fed; key floor rate tool","Bank fee","Treasury yield"]'::jsonb, 1, 'IORB anchors money-market rates and is now the Fed''s primary policy floor.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-042', 'Which is true about "repo rate" / SOFR?', '["Same as fed funds","Secured overnight financing rate — major benchmark replacing LIBOR","FX","Coupon"]'::jsonb, 1, 'SOFR is the secured-overnight benchmark for USD rates that has replaced LIBOR.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-043', 'Which is true about "reverse repo" facility (RRP)?', '["Bank fee","Fed offers counterparties to park cash overnight at a fixed rate, draining reserves","FX intervention","Loan"]'::jsonb, 1, 'The ON RRP gives money market funds and others a safe overnight place to park cash, setting a floor.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-044', 'Which is true about "Fed independence"?', '["Always politically influenced","Operationally independent from short-term political pressures by design","Government department","Privately owned"]'::jsonb, 1, 'The Fed is designed to be operationally independent so politicians can''t manipulate rates for short-term gain.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-045', 'Which is true about "central bank credibility"?', '["Irrelevant","Anchors inflation expectations; lost credibility makes inflation harder to control","Cost-free","Fixed by law"]'::jsonb, 1, 'Credibility lowers the cost of maintaining stable inflation — anchored expectations require less action to enforce.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-046', 'Which is true about "global growth" and US risk assets?', '["No connection","US equities tend to benefit from stronger global growth","Negative correlation","Random"]'::jsonb, 1, 'Strong global growth supports US multinationals'' earnings and risk appetite broadly.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-047', 'Which is true about "USD as reserve currency"?', '["Negligible","Dominant role in global trade and reserves; gives US borrowing advantages","Phased out","Replaced by gold"]'::jsonb, 1, 'The dollar''s reserve status provides demand for Treasuries and lowers US funding costs ("exorbitant privilege").', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-048', 'Which is true about "safe haven" flows during stress?', '["Cash sells off","Treasuries and USD typically rally during global risk-off events","Stocks rally","Bonds fall"]'::jsonb, 1, 'During market stress, capital flees to Treasuries, USD, gold, and the Swiss franc — classic safe havens.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-049', 'Which is true about "hawks" vs "doves"?', '["Random labels","Hawks favor tighter policy to fight inflation; doves favor accommodative policy","Opposite roles","Banned terms"]'::jsonb, 1, 'Hawks worry about inflation; doves worry about unemployment. The labels track Fed policy preferences.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-050', 'Which is true about "data dependence" in Fed communication?', '["Predetermined path","Policy adjusts based on incoming inflation and labor data","Tax-determined","Calendar-only"]'::jsonb, 1, '"Data dependent" means the policy path will shift with macro data rather than follow a preset path.', 'Macro & monetary policy', 'Intermediate', null),
  ('mac-051', 'Which is true about "Volcker shock" lessons?', '["Easier later","Demonstrated central bank willingness to inflict pain to defeat inflation","Easy fix","Always optional"]'::jsonb, 1, 'Volcker''s tight policy in the early 1980s ended high inflation but caused a sharp recession — a credibility-anchor case study.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-052', 'Which is true about "natural rate of interest" (r*)?', '["Always zero","The real rate consistent with stable inflation at full employment — unobservable","Bond yield","Tax rate"]'::jsonb, 1, 'r* is unobservable and inferred; it anchors policy decisions about how stimulative or restrictive rates are.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-053', 'Which is true about "shadow rate" estimates?', '["Same as policy rate","Estimate of effective policy stance when constrained by zero lower bound","Bond yield","Required reserves"]'::jsonb, 1, 'Shadow rates extend policy measurement below zero by accounting for unconventional tools like QE.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-054', 'Which is true about "financial conditions index"?', '["Single rate","Composite of rates, credit spreads, equity prices, and FX — broader policy stance","FX-only","Tax-only"]'::jsonb, 1, 'FCIs aggregate market signals into a holistic measure of how stimulative or restrictive conditions are.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-055', 'Which is true about "hysteresis" in unemployment?', '["Quick reversibility","Long unemployment spells can erode skills, lowering potential output","No effect","Tax issue"]'::jsonb, 1, 'Hysteresis suggests prolonged unemployment damages labor force participation and productivity permanently.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-056', 'Which is true about "global savings glut" hypothesis?', '["Less savings","Excess savings (especially Asian) pushed down global yields","Currency effect","Tax issue"]'::jsonb, 1, 'Bernanke''s hypothesis: excess global savings depressed global real yields, especially long-end Treasuries.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-057', 'Which is true about "secular stagnation" thesis?', '["Boom thesis","Aging demographics + capital glut + weak demand → persistently low growth/rates","Currency thesis","Tax thesis"]'::jsonb, 1, 'Summers'' framework: structural factors keep equilibrium rates low for extended periods.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-058', 'Which is true about "MMT" (Modern Monetary Theory)?', '["Same as conventional","Argues fiscal capacity in currency-issuing countries is limited by inflation, not solvency","Tax policy","Bond yield only"]'::jsonb, 1, 'MMT reframes deficits as constrained by real-resource inflation, not financing — controversial framework.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-059', 'Which is true about "fiscal dominance"?', '["Monetary primacy","When fiscal needs constrain monetary policy, limiting central bank independence","FX policy","Tax cut"]'::jsonb, 1, 'Fiscal dominance occurs when high debt forces the central bank to keep rates low to preserve solvency.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-060', 'Which is true about "unconventional monetary policy"?', '["Higher rates","Tools beyond rate moves: QE, forward guidance, yield-curve control","Tax cuts","Bond buying only"]'::jsonb, 1, 'Unconventional policy expanded after 2008 when rates hit ZLB — QE, guidance, YCC, etc.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-061', 'Which is true about "yield curve control"?', '["Setting rates","Central bank caps yields at specific maturities by buying as needed","Tax tool","FX tool"]'::jsonb, 1, 'YCC pins longer yields at a target by committing unlimited buying — pioneered by BoJ.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-062', 'Which is true about "negative interest rate policy" (NIRP)?', '["Tax cut","Central bank charges banks for parking reserves — used in eurozone, Japan","Bond yield","FX-only"]'::jsonb, 1, 'NIRP penalizes excess reserves to encourage bank lending — used by ECB and BoJ at times.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-063', 'Which is true about "FX reserves" and emerging markets?', '["Irrelevant","Hold for defense against currency runs and to manage exchange rates","Always USD","Always gold"]'::jsonb, 1, 'EM central banks hoard reserves to defend their currencies in crises and manage exchange rate volatility.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-064', 'Which is true about "impossible trinity" / "trilemma"?', '["Choose all three","Cannot simultaneously have fixed FX, free capital flows, and independent monetary policy","Always feasible","Bond yield"]'::jsonb, 1, 'The Mundell-Fleming trilemma: you can pick any two of fixed FX, free capital mobility, and monetary independence.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-065', 'Which is true about "global financial cycle"?', '["Domestic only","US monetary policy and risk sentiment drive global asset prices and capital flows","Tax-only","FX-only"]'::jsonb, 1, 'Hélène Rey''s work: the global financial cycle dilutes the trilemma''s choice by transmitting US policy worldwide.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-066', 'Which is true about "R-star" and demographics?', '["Independent","Aging populations and slower productivity have lowered estimates of r* globally","Increasing","Random"]'::jsonb, 1, 'Demographics and productivity slowdowns are key drivers behind the secular decline in r*.', 'Macro & monetary policy', 'Advanced', null),
  ('mac-067', 'Which is true about "unexpected vs expected inflation"?', '["Same impact","Unexpected inflation transfers wealth from creditors to debtors; expected is priced","No transfer","Tax neutral"]'::jsonb, 1, 'Surprise inflation hurts bondholders and benefits debtors; expected inflation gets embedded into nominal rates.', 'Macro & monetary policy', 'Advanced', null),
  ('opt-001', 'What is an option?', '["A type of bond","A contract giving the right (not obligation) to buy/sell an asset at a set price","An ETF","A futures contract"]'::jsonb, 1, 'Options give the holder a right, not an obligation, to trade at the strike price.', 'Options & derivatives', 'Basic', null),
  ('opt-002', 'What is a call option?', '["Right to sell","Right to buy the underlying at the strike price","Obligation to buy","Bond payment"]'::jsonb, 1, 'A call gives the holder the right to buy at the strike.', 'Options & derivatives', 'Basic', null),
  ('opt-003', 'What is a put option?', '["Right to buy","Right to sell the underlying at the strike price","Stock dividend","Right to short"]'::jsonb, 1, 'A put gives the holder the right to sell at the strike.', 'Options & derivatives', 'Basic', null),
  ('opt-004', 'What is the strike price?', '["Stock price today","The agreed price at which the option can be exercised","Last sale","Premium"]'::jsonb, 1, 'The strike is the predetermined price at which the holder can buy (call) or sell (put).', 'Options & derivatives', 'Basic', null),
  ('opt-005', 'What is the option premium?', '["Strike price","The price paid for the option","Dividend","Margin"]'::jsonb, 1, 'The premium is the cost of the option contract.', 'Options & derivatives', 'Basic', null),
  ('opt-006', 'What does "in the money" (ITM) mean for a call?', '["Stock < strike","Stock > strike (intrinsic value > 0)","Stock = strike","No relation"]'::jsonb, 1, 'A call is ITM when the stock is above the strike — has intrinsic value.', 'Options & derivatives', 'Basic', null),
  ('opt-007', 'What does "in the money" (ITM) mean for a put?', '["Stock > strike","Stock < strike (intrinsic value > 0)","Stock = strike","No relation"]'::jsonb, 1, 'A put is ITM when the stock is below the strike.', 'Options & derivatives', 'Basic', null),
  ('opt-008', 'What does "out of the money" (OTM) mean for a call?', '["Stock > strike","Stock < strike","Stock = strike","Doubled"]'::jsonb, 1, 'A call is OTM when the stock is below the strike — no intrinsic value.', 'Options & derivatives', 'Basic', null),
  ('opt-009', 'What does "at the money" (ATM) mean?', '["Stock far from strike","Stock approximately equal to strike","ITM","OTM"]'::jsonb, 1, 'ATM means strike ≈ current stock price.', 'Options & derivatives', 'Basic', null),
  ('opt-010', 'What is the expiration date?', '["Inception","Date the option expires (becomes worthless or exercised)","Strike date","Dividend date"]'::jsonb, 1, 'Options expire on a specified date — after that, they cease to exist.', 'Options & derivatives', 'Basic', null),
  ('opt-011', 'What is intrinsic value?', '["Premium","The value if exercised right now (max(S-K, 0) for call)","Time value","Strike"]'::jsonb, 1, 'Intrinsic value = the amount ITM. Zero if OTM.', 'Options & derivatives', 'Beginner', null),
  ('opt-012', 'What is time value (extrinsic value)?', '["Strike","Premium minus intrinsic value — pays for possibility before expiration","Stock dividend","Margin"]'::jsonb, 1, 'Time value is the portion of premium beyond intrinsic — pays for the possibility of further moves.', 'Options & derivatives', 'Beginner', null),
  ('opt-013', 'What is an American-style option?', '["Can be exercised at any time before expiration","Only at expiration","Only at open","Only weekly"]'::jsonb, 0, 'American options can be exercised any time up to expiration.', 'Options & derivatives', 'Beginner', null),
  ('opt-014', 'What is a European-style option?', '["Anytime","Exercisable only at expiration","Daily","Weekly"]'::jsonb, 1, 'European options can only be exercised at expiration.', 'Options & derivatives', 'Beginner', null),
  ('opt-015', 'What is one US equity option contract typically worth?', '["1 share","100 shares of the underlying","10 shares","1000 shares"]'::jsonb, 1, 'Standard US equity options cover 100 shares per contract.', 'Options & derivatives', 'Beginner', null),
  ('opt-016', 'Which is true about "covered call"?', '["Naked short","Own shares + sell a call against them — generates income with capped upside","Long put","Risk-free arb"]'::jsonb, 1, 'A covered call generates premium income; the stock gains are capped at the strike.', 'Options & derivatives', 'Beginner', null),
  ('opt-017', 'Which is true about "naked call"?', '["Limited risk","Sell a call without owning the underlying — unlimited upside risk for the seller","Hedged","Bond strategy"]'::jsonb, 1, 'Naked calls expose the seller to unbounded losses if the stock rallies.', 'Options & derivatives', 'Beginner', null),
  ('opt-018', 'Which is true about "cash-secured put"?', '["Naked short","Sell a put while holding enough cash to buy the underlying if assigned","Long call","Margin only"]'::jsonb, 1, 'Cash-secured puts collect premium with the willingness/ability to buy the stock at strike if assigned.', 'Options & derivatives', 'Beginner', null),
  ('opt-019', 'Which is true about "protective put"?', '["Cancels gains","Long stock + long put — limits downside (insurance)","Naked short","Random strategy"]'::jsonb, 1, 'Protective puts hedge a long position against large drops — like portfolio insurance.', 'Options & derivatives', 'Beginner', null),
  ('opt-020', 'Which is true about a "long straddle"?', '["Bet on stable price","Long call + long put at same strike — profits from large moves either way","Short volatility","Income strategy"]'::jsonb, 1, 'Straddles profit from big directional moves regardless of direction.', 'Options & derivatives', 'Beginner', null),
  ('opt-021', 'Which is true about a "short straddle"?', '["Bet on big moves","Short call + short put — profits if stock stays near strike (sell volatility)","Long volatility","Hedge"]'::jsonb, 1, 'Short straddles collect premium and profit if the stock doesn''t move much; risk is unlimited.', 'Options & derivatives', 'Beginner', null),
  ('opt-022', 'Which is true about a "long strangle"?', '["Same strike straddle","Long OTM call + long OTM put — cheaper than straddle, needs bigger move","Bond strategy","Random"]'::jsonb, 1, 'Strangles use different strikes — cheaper premium but require a larger move.', 'Options & derivatives', 'Beginner', null),
  ('opt-023', 'Which is the "break-even" of a long call at expiration?', '["Strike","Strike + premium paid","Strike - premium","Spot price"]'::jsonb, 1, 'Break-even for long call = strike + premium.', 'Options & derivatives', 'Beginner', null),
  ('opt-024', 'Which is the "break-even" of a long put at expiration?', '["Strike","Strike − premium paid","Strike + premium","Spot price"]'::jsonb, 1, 'Break-even for long put = strike − premium.', 'Options & derivatives', 'Beginner', null),
  ('opt-025', 'Which is true about "option time decay"?', '["Premium grows over time","All else equal, option time value erodes as expiration approaches","Strike falls","Bond decay"]'::jsonb, 1, 'Time value decays over time (theta) — accelerating as expiration nears.', 'Options & derivatives', 'Beginner', null),
  ('opt-026', 'What is theta?', '["Volatility","Time decay — how much premium drops per day","Strike change","Interest"]'::jsonb, 1, 'Theta measures the daily premium loss from time passing — usually negative for long options.', 'Options & derivatives', 'Beginner', null),
  ('opt-027', 'What is delta?', '["Time decay","Option''s price change for a $1 move in the underlying","Strike","Volatility"]'::jsonb, 1, 'Delta approximates price sensitivity — also serves as a hedge ratio.', 'Options & derivatives', 'Beginner', null),
  ('opt-028', 'Approximate delta of a near-ATM call?', '["~0","~0.5","~1.0","~−1.0"]'::jsonb, 1, 'ATM calls have delta around 0.50.', 'Options & derivatives', 'Beginner', null),
  ('opt-029', 'Approximate delta of a near-ATM put?', '["~0","~−0.5","~1.0","~+1.0"]'::jsonb, 1, 'ATM puts have delta around −0.50.', 'Options & derivatives', 'Beginner', null),
  ('opt-030', 'What is gamma?', '["Same as theta","Rate of change of delta per $1 move in underlying","Volatility","Strike"]'::jsonb, 1, 'Gamma measures convexity — how fast delta changes.', 'Options & derivatives', 'Beginner', null),
  ('opt-031', 'What is vega?', '["Time decay","Option sensitivity to a 1% change in implied volatility","Delta","Strike"]'::jsonb, 1, 'Vega measures sensitivity to implied volatility — typically positive for long options.', 'Options & derivatives', 'Intermediate', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('opt-032', 'What is rho?', '["Volatility","Option sensitivity to interest rates","Delta","Time"]'::jsonb, 1, 'Rho measures rate sensitivity — small for short-dated options, larger for LEAPS.', 'Options & derivatives', 'Intermediate', null),
  ('opt-033', 'What is implied volatility (IV)?', '["Historical vol","The volatility level implied by the option''s current price","Beta","Dividend"]'::jsonb, 1, 'IV is the market''s pricing of expected future volatility — derived from option prices.', 'Options & derivatives', 'Intermediate', null),
  ('opt-034', 'Which is true about IV around earnings?', '["Always flat","Tends to rise into earnings, then \"crush\" after the event","Falls before","Constant"]'::jsonb, 1, 'IV typically inflates before earnings on uncertainty, then collapses post-announcement (vol crush).', 'Options & derivatives', 'Intermediate', null),
  ('opt-035', 'Which is true about "the Black-Scholes" model?', '["Determines historical price","Closed-form formula for European option pricing under specific assumptions","Bond pricing","Random walk"]'::jsonb, 1, 'Black-Scholes prices European options assuming constant volatility, lognormal returns, etc.', 'Options & derivatives', 'Intermediate', null),
  ('opt-036', 'Which is true about "put-call parity"?', '["Random equation","C − P = S − Ke^(-rT) (for European options on non-dividend stock)","Bond identity","Tax law"]'::jsonb, 1, 'Put-call parity is a no-arbitrage relationship linking puts, calls, and the underlying.', 'Options & derivatives', 'Intermediate', null),
  ('opt-037', 'What is a "vertical spread"?', '["Two different expirations","Long and short options of same type at different strikes, same expiration","Bond pair","Calendar"]'::jsonb, 1, 'Vertical spreads use different strikes within the same expiration — define risk and reward.', 'Options & derivatives', 'Intermediate', null),
  ('opt-038', 'What is a "calendar spread"?', '["Same expiration","Long and short options of same type/strike but different expirations","Bond ladder","Box"]'::jsonb, 1, 'Calendar spreads exploit differential time decay across expirations.', 'Options & derivatives', 'Intermediate', null),
  ('opt-039', 'What is a "butterfly spread"?', '["Pure long","Combination yielding maximum profit when stock pins a specific strike at expiration","Bond strategy","Random"]'::jsonb, 1, 'Butterflies profit from low realized volatility near a chosen strike.', 'Options & derivatives', 'Intermediate', null),
  ('opt-040', 'What is an "iron condor"?', '["Single option","Short call spread + short put spread, profits from low volatility within a range","Stock pair","Bond strategy"]'::jsonb, 1, 'Iron condors collect premium when the stock stays inside a range; defined risk.', 'Options & derivatives', 'Intermediate', null),
  ('opt-041', 'Which is true about "delta hedging"?', '["Buy more stock","Continuously adjust stock holdings to offset option delta — maintains market neutrality","Sell volatility","Random"]'::jsonb, 1, 'Delta hedging dynamically buys/sells the underlying to keep total delta near zero.', 'Options & derivatives', 'Intermediate', null),
  ('opt-042', 'Which is true about "gamma scalping"?', '["Sell premium","Adjust the delta hedge to capture profit from realized volatility on long-gamma positions","Bond strategy","Random"]'::jsonb, 1, 'Long gamma + delta hedge converts realized volatility into trading P&L.', 'Options & derivatives', 'Intermediate', null),
  ('opt-043', 'Which is true about "volatility skew"?', '["Always flat","OTM puts often imply higher IV than OTM calls (equity index skew)","Always negative","Random"]'::jsonb, 1, 'Equity index options typically show negative skew — OTM puts are pricier on a vol basis.', 'Options & derivatives', 'Intermediate', null),
  ('opt-044', 'Which is true about "volatility term structure"?', '["Flat","IV varies across expirations; sometimes upward (contango), sometimes inverted","Always flat","Random"]'::jsonb, 1, 'Term structure plots IV by maturity — provides info on event-driven vs structural views.', 'Options & derivatives', 'Intermediate', null),
  ('opt-045', 'Which is true about "VIX"?', '["VIX measures S&P 500 implied volatility over the next 30 days","Bond measure","Random","Realized only"]'::jsonb, 0, 'The VIX index proxies 30-day forward S&P 500 implied volatility.', 'Options & derivatives', 'Intermediate', null),
  ('opt-046', 'Which is true about "VIX futures"?', '["Spot VIX","Trade expectations of where the VIX will be at different forward dates","Bonds","Currency"]'::jsonb, 1, 'VIX futures price the market''s expectation of future spot VIX levels.', 'Options & derivatives', 'Intermediate', null),
  ('opt-047', 'Which is true about "VIX contango"?', '["Spot > futures","Futures higher than spot — common; ETP holders pay roll cost","Inverted","Bond term"]'::jsonb, 1, 'In contango, VIX futures are above spot — VIX-tracking ETPs suffer negative roll yield.', 'Options & derivatives', 'Intermediate', null),
  ('opt-048', 'Which is true about "VIX backwardation"?', '["Common","Spot > futures — unusual, often during stress; favorable for shorts","Always","Random"]'::jsonb, 1, 'Backwardation usually emerges during volatile/stressed markets.', 'Options & derivatives', 'Intermediate', null),
  ('opt-049', 'What is a "futures contract"?', '["Loan","Standardized agreement to buy/sell an asset at a future date at a set price","Bond","Equity"]'::jsonb, 1, 'Futures are exchange-traded, standardized forward contracts.', 'Options & derivatives', 'Intermediate', null),
  ('opt-050', 'Which is true about futures margin?', '["Same as equity","Initial margin posted; daily mark-to-market with maintenance margin requirements","Equity-only","No margin"]'::jsonb, 1, 'Futures use posted margin; daily settlement adjusts P&L through variation margin.', 'Options & derivatives', 'Intermediate', null),
  ('opt-051', 'Which is true about "physical vs cash settlement"?', '["Identical","Physical delivers the asset; cash settles in dollars based on final price","Always cash","Always physical"]'::jsonb, 1, 'Some futures (like oil) physically deliver; others (like equity index) settle in cash.', 'Options & derivatives', 'Advanced', null),
  ('opt-052', 'Which is true about "basis" in futures?', '["Always zero","Difference between futures price and spot price","Strike difference","Random"]'::jsonb, 1, 'Basis = spot − futures (or vice versa); reflects carry, dividends, interest.', 'Options & derivatives', 'Advanced', null),
  ('opt-053', 'Which is true about "contango" in commodities?', '["Spot > futures","Futures > spot — typical for storable commodities, reflecting carrying cost","Same","Always"]'::jsonb, 1, 'Contango exists when futures prices exceed spot — reflecting storage and carry costs.', 'Options & derivatives', 'Advanced', null),
  ('opt-054', 'Which is true about "backwardation" in commodities?', '["Spot < futures","Spot > futures — often signals tight supply","Same","Equity-only"]'::jsonb, 1, 'Backwardation arises when spot exceeds futures — typically signaling supply shortage.', 'Options & derivatives', 'Advanced', null),
  ('opt-055', 'Which is true about "convexity adjustment" for futures?', '["Same as forward","Daily margin financing introduces small differences from forwards","Always equal","No adjustment"]'::jsonb, 1, 'Daily margining of futures creates a small convexity-related discrepancy vs forward contracts.', 'Options & derivatives', 'Advanced', null),
  ('opt-056', 'Which is true about "swap" contracts?', '["Stock trade","Exchange of cash-flow streams (e.g., fixed for floating rates)","Bond","Equity"]'::jsonb, 1, 'Swaps exchange streams of cash flows — interest rate, currency, equity, total return.', 'Options & derivatives', 'Advanced', null),
  ('opt-057', 'Which is true about "interest-rate swaps"?', '["FX-only","Exchange fixed rate for floating (or vice versa) on a notional principal","Always equity","Tax tool"]'::jsonb, 1, 'IRS are the most common derivatives — convert between fixed and floating rate exposures.', 'Options & derivatives', 'Advanced', null),
  ('opt-058', 'Which is true about "credit default swaps"?', '["Equity hedge","Buyer pays premium; seller pays out on credit event (default/restructuring)","FX","Stock"]'::jsonb, 1, 'CDS contracts protect against credit events; sellers earn premium for assuming default risk.', 'Options & derivatives', 'Advanced', null),
  ('opt-059', 'Which is true about "variance swap"?', '["Index","Pays the difference between realized variance and a fixed strike — pure vol exposure","FX","Bond"]'::jsonb, 1, 'Variance swaps deliver clean exposure to realized volatility squared.', 'Options & derivatives', 'Advanced', null),
  ('opt-060', 'Which is true about "volatility swap"?', '["Equity swap","Pays the difference between realized volatility and a fixed strike","FX","Bond"]'::jsonb, 1, 'Volatility swaps pay realized vol minus the strike, in volatility units.', 'Options & derivatives', 'Advanced', null),
  ('opt-061', 'Which is true about "binary options"?', '["Standard call","Pays a fixed amount if a condition is met at expiration, zero otherwise","Forward","Stock"]'::jsonb, 1, 'Binary options have all-or-nothing payouts based on a discrete condition.', 'Options & derivatives', 'Advanced', null),
  ('opt-062', 'Which is true about "barrier options"?', '["Always exercised","Knock-in or knock-out features activate/cancel based on price level being touched","No barrier","Random"]'::jsonb, 1, 'Barrier options have price thresholds that can activate or extinguish them.', 'Options & derivatives', 'Advanced', null),
  ('opt-063', 'Which is true about "Asian options"?', '["Standard exotic","Payoff based on average price over a period, not single expiration","Bond-like","Knock-out"]'::jsonb, 1, 'Asian options use average prices, which lowers volatility and premium vs vanilla options.', 'Options & derivatives', 'Advanced', null),
  ('opt-064', 'Which is true about "option-implied probability"?', '["Risk-neutral","Derived risk-neutral probabilities differ from real-world probabilities","Identical","Tax method"]'::jsonb, 1, 'Option prices imply risk-neutral probabilities, which incorporate risk preferences and differ from real probabilities.', 'Options & derivatives', 'Advanced', null),
  ('opt-065', 'Which is true about "volatility surface"?', '["Single number","IV across strikes and expirations — 3D structure capturing skew + term structure","Always flat","Random"]'::jsonb, 1, 'The volatility surface reveals the full structure of implied vols across the options chain.', 'Options & derivatives', 'Advanced', null),
  ('opt-066', 'Which is true about "American option early exercise"?', '["Always optimal","Rarely optimal except for ITM puts or pre-dividend calls","Never possible","Random"]'::jsonb, 1, 'Early exercise is rarely optimal for American calls (except just before dividends) but more common for deep ITM puts.', 'Options & derivatives', 'Advanced', null),
  ('opt-067', 'Which is true about "variance risk premium" (VRP)?', '["Always zero","Implied vol typically exceeds realized vol — selling vol earns a premium on average","Negative","Tax"]'::jsonb, 1, 'On average, implied vol overpredicts realized vol — short-vol strategies earn this premium, with tail risk.', 'Options & derivatives', 'Advanced', null),
  ('etf-001', 'What is an ETF?', '["Bond fund","Exchange-traded fund — basket of securities trading like a single stock","Single stock","Closed-end fund"]'::jsonb, 1, 'ETFs are pooled investment vehicles that trade intraday on exchanges.', 'ETFs & funds', 'Basic', null),
  ('etf-002', 'What is a mutual fund?', '["Pooled investment that prices and trades once daily at NAV","Same as ETF","Single stock","Bond"]'::jsonb, 0, 'Mutual funds price/transact at end-of-day NAV — not intraday like ETFs.', 'ETFs & funds', 'Basic', null),
  ('etf-003', 'What is an index fund?', '["Active fund","Fund tracking a market index passively","Hedge fund","Bond fund only"]'::jsonb, 1, 'Index funds mechanically replicate a benchmark index — passive investing.', 'ETFs & funds', 'Basic', null),
  ('etf-004', 'What is the largest US ETF by AUM?', '["GLD","SPY","QQQ","BND"]'::jsonb, 1, 'SPY (SPDR S&P 500) is typically the largest US ETF by AUM.', 'ETFs & funds', 'Basic', null),
  ('etf-005', 'What is NAV?', '["Net Asset Value — per-share value of a fund''s holdings","Annual return","Net Annual Volume","Coupon"]'::jsonb, 0, 'NAV = (assets − liabilities) ÷ shares outstanding. The fund''s per-share asset value.', 'ETFs & funds', 'Basic', null),
  ('etf-006', 'Which is true about ETF intraday trading?', '["Only at end-of-day","Trades like a stock throughout the session","Always at NAV","Block trades only"]'::jsonb, 1, 'ETFs trade intraday; price can differ from NAV but arbitrage typically keeps them aligned.', 'ETFs & funds', 'Basic', null),
  ('etf-007', 'What is an expense ratio?', '["Buyer''s fee","Annual fund operating cost as a percentage of assets","Trade fee","Bond yield"]'::jsonb, 1, 'Expense ratio is the annual fund cost charged against assets.', 'ETFs & funds', 'Basic', null),
  ('etf-008', 'Which typically has lower expense ratios?', '["Active mutual funds","Passive index funds/ETFs","Hedge funds","Private funds"]'::jsonb, 1, 'Passive index funds and ETFs typically charge much lower fees than active managers.', 'ETFs & funds', 'Basic', null),
  ('etf-009', 'What does it mean for an ETF to be "passively managed"?', '["Manager picks stocks","Tracks an index mechanically","Always profitable","Cash-only"]'::jsonb, 1, 'Passive ETFs follow rule-based indexes rather than discretionary stock-picking.', 'ETFs & funds', 'Basic', null),
  ('etf-010', 'What does it mean for an ETF to be "actively managed"?', '["Tracks index","Manager makes discretionary buy/sell decisions to beat a benchmark","Passive","Bond only"]'::jsonb, 1, 'Actively managed funds try to outperform via security selection or market timing.', 'ETFs & funds', 'Basic', null),
  ('etf-011', 'Which is true about ETF tax efficiency vs mutual funds?', '["Same","ETFs are typically more tax-efficient due to in-kind creation/redemption","Mutual funds win","Identical"]'::jsonb, 1, 'In-kind redemptions help ETFs avoid distributing capital gains, often making them tax-efficient.', 'ETFs & funds', 'Beginner', null),
  ('etf-012', 'What are "authorized participants" in ETFs?', '["Random retail","Large institutions that create/redeem ETF shares in exchange for underlying baskets","Brokerages","Banks"]'::jsonb, 1, 'APs facilitate creation/redemption, arbitraging price vs NAV deviations.', 'ETFs & funds', 'Beginner', null),
  ('etf-013', 'Which is true about "creation units"?', '["1 share","Large blocks (often 50k shares) used in ETF creation/redemption","Small","Optional"]'::jsonb, 1, 'Creation units are the bulk-share units APs trade with ETF sponsors — typically 50,000-100,000 shares.', 'ETFs & funds', 'Beginner', null),
  ('etf-014', 'What is a "sector ETF"?', '["Single stock","Fund focused on a specific industry sector","Bond only","Currency"]'::jsonb, 1, 'Sector ETFs target a particular industry — XLK (tech), XLF (financials), etc.', 'ETFs & funds', 'Beginner', null),
  ('etf-015', 'What is a "smart beta" ETF?', '["Pure passive","Rules-based fund tilting toward factors (value, momentum, quality)","Hedge fund","Crypto"]'::jsonb, 1, 'Smart beta combines passive structure with factor-based tilts away from market-cap weighting.', 'ETFs & funds', 'Beginner', null),
  ('etf-016', 'Which is true about "leveraged ETFs"?', '["Standard 1×","Target multiples (2×, 3×) of daily returns; not designed for long holding","Bond","Currency only"]'::jsonb, 1, 'Leveraged ETFs amplify daily returns but suffer compounding decay over longer holding periods.', 'ETFs & funds', 'Beginner', null),
  ('etf-017', 'Which is true about "inverse ETFs"?', '["Match index","Designed to deliver the inverse of index daily returns","Always bond","Long-only"]'::jsonb, 1, 'Inverse ETFs deliver -1× (or more) the daily index return — useful for short-duration hedges.', 'ETFs & funds', 'Beginner', null),
  ('etf-018', 'Which is true about "international ETFs"?', '["Cash only","Provide exposure to foreign markets via a single fund","Bond only","Tax-free"]'::jsonb, 1, 'International ETFs simplify foreign market access — VXUS, EFA, EEM are common.', 'ETFs & funds', 'Beginner', null),
  ('etf-019', 'Which is true about "bond ETFs"?', '["Same as stocks","ETFs holding bonds that trade like stocks intraday","Cash","Equity"]'::jsonb, 1, 'Bond ETFs let investors trade bond-market exposure intraday with stock-like ease.', 'ETFs & funds', 'Beginner', null),
  ('etf-020', 'Which is true about "target-date funds"?', '["Random allocation","Automatically adjust asset mix to grow more conservative as target retirement date nears","Currency fund","Cash only"]'::jsonb, 1, 'TDFs are one-decision retirement vehicles that glide toward conservative allocation over time.', 'ETFs & funds', 'Beginner', null),
  ('etf-021', 'Which is true about "money market funds"?', '["Stock fund","Hold short-term, high-quality debt; aim for stable $1 share price","Bond-only","Crypto"]'::jsonb, 1, 'MMFs invest in T-bills, commercial paper, and other very short-term debt for cash-like properties.', 'ETFs & funds', 'Beginner', null),
  ('etf-022', 'Which is true about "closed-end funds" (CEFs)?', '["Same as ETF","Issue a fixed number of shares; can trade at premium/discount to NAV","Always trades at NAV","Bond only"]'::jsonb, 1, 'CEFs have fixed shares — their price can persistently diverge from NAV.', 'ETFs & funds', 'Beginner', null),
  ('etf-023', 'Which is true about "open-end funds"?', '["Fixed shares","Issue and redeem shares directly with the fund at NAV","Always at premium","Crypto"]'::jsonb, 1, 'Open-end mutual funds and ETFs continuously issue/redeem shares at NAV.', 'ETFs & funds', 'Beginner', null),
  ('etf-024', 'Which is true about "index reconstitution"?', '["Constant","Index periodically adds/removes constituents — can cause front-running","Random","Tax event"]'::jsonb, 1, 'Reconstitution events drive forced ETF buying/selling — sometimes exploited by traders.', 'ETFs & funds', 'Beginner', null),
  ('etf-025', 'Which is true about "tracking error"?', '["Always zero","Difference between fund returns and benchmark returns","Same as fees","Always positive"]'::jsonb, 1, 'Tracking error measures how closely a passive fund matches its benchmark.', 'ETFs & funds', 'Beginner', null),
  ('etf-026', 'Which is true about "premiums/discounts" on ETFs?', '["Always zero","ETFs can briefly trade above or below NAV; arbitrage usually narrows quickly","Never","Tax event"]'::jsonb, 1, 'ETF prices can deviate slightly from NAV; APs typically arbitrage gaps away.', 'ETFs & funds', 'Beginner', null),
  ('etf-027', 'Which is true about "securities lending" by funds?', '["Tax fraud","Funds lend portfolio holdings for fees, partially offsetting expenses","Banned","No income"]'::jsonb, 1, 'Funds lend out holdings (with collateral) to short-sellers, earning lending fees.', 'ETFs & funds', 'Beginner', null),
  ('etf-028', 'Which is true about "actively-managed ETFs"?', '["Banned","Allowed under SEC rules (e.g., ARK funds, ETF rule 6c-11)","Same as mutual","Cash only"]'::jsonb, 1, 'Active ETFs combine active management with the ETF wrapper — growing rapidly.', 'ETFs & funds', 'Beginner', null),
  ('etf-029', 'Which is true about "semi-transparent ETFs"?', '["Disclose daily","Disclose holdings less frequently (e.g., quarterly) using SEC-approved structures","Crypto","Hidden"]'::jsonb, 1, 'Semi-transparent ETFs hide holdings to protect active strategies from front-running.', 'ETFs & funds', 'Beginner', null),
  ('etf-030', 'Which is true about "ETF wrapper" advantages?', '["Higher fees","Intraday liquidity, tax efficiency, transparency","Worse than mutual","Random"]'::jsonb, 1, 'The ETF wrapper delivers intraday tradability, often lower fees, and tax efficiency.', 'ETFs & funds', 'Beginner', null),
  ('etf-031', 'Which is true about "factor ETFs" targeting value?', '["Track market cap weights","Tilt to low-P/B, low-P/E stocks systematically","Always cash","Random"]'::jsonb, 1, 'Value-factor ETFs systematically overweight stocks with cheap valuation multiples.', 'ETFs & funds', 'Intermediate', null),
  ('etf-032', 'Which is true about "momentum ETFs"?', '["Buy losers","Tilt to recent winners (12-month minus most recent month)","Bond fund","Random"]'::jsonb, 1, 'Momentum ETFs systematically buy past winners and rebalance periodically.', 'ETFs & funds', 'Intermediate', null),
  ('etf-033', 'Which is true about "quality ETFs"?', '["Random stocks","Tilt to high ROE, low debt, stable earnings","Cash only","Bond only"]'::jsonb, 1, 'Quality factor ETFs target durable, profitable, financially-strong businesses.', 'ETFs & funds', 'Intermediate', null),
  ('etf-034', 'Which is true about "low-volatility ETFs"?', '["High beta","Target stocks with historically lower volatility","Speculative","Crypto"]'::jsonb, 1, 'Low-vol ETFs select stocks with lower realized volatility — pursuing better risk-adjusted returns.', 'ETFs & funds', 'Intermediate', null),
  ('etf-035', 'Which is true about "dividend ETFs"?', '["No dividends","Focus on dividend-paying stocks for income/yield","Bond-only","Cash"]'::jsonb, 1, 'Dividend ETFs select for current yield (or dividend growth) characteristics.', 'ETFs & funds', 'Intermediate', null),
  ('etf-036', 'Which is true about "high yield bond ETFs"?', '["Treasury-only","Hold below-investment-grade corporates for higher yield/risk","Money market","Tax-free"]'::jsonb, 1, 'HY bond ETFs (e.g., HYG, JNK) provide diversified exposure to below-IG corporate credit.', 'ETFs & funds', 'Intermediate', null),
  ('etf-037', 'Which is true about "TIPS ETFs"?', '["Nominal Treasuries","Hold inflation-protected Treasury bonds","Junk bonds","Equity"]'::jsonb, 1, 'TIPS ETFs (e.g., TIP) deliver inflation-linked Treasury exposure.', 'ETFs & funds', 'Intermediate', null),
  ('etf-038', 'Which is true about "municipal bond ETFs"?', '["Taxable","Hold munis, often delivering tax-advantaged income","Corporate only","Always taxable"]'::jsonb, 1, 'Muni ETFs aggregate state/local bonds, typically delivering federally tax-exempt income.', 'ETFs & funds', 'Intermediate', null),
  ('etf-039', 'Which is true about "international developed market ETFs"?', '["Emerging markets","Cover countries like EU/UK/Japan/Canada","US only","Crypto"]'::jsonb, 1, 'Developed-market ETFs (e.g., EFA, VEA) hold non-US developed equities.', 'ETFs & funds', 'Intermediate', null),
  ('etf-040', 'Which is true about "emerging market ETFs"?', '["US-only","Hold equities from developing economies — higher risk, higher growth","Bonds only","Cash"]'::jsonb, 1, 'EM ETFs (e.g., EEM, VWO) deliver emerging-market exposure with elevated volatility.', 'ETFs & funds', 'Intermediate', null),
  ('etf-041', 'Which is true about "currency-hedged ETFs"?', '["Currency exposure","Use derivatives to remove currency moves from foreign equity/bond returns","No hedging","Tax-only"]'::jsonb, 1, 'Currency-hedged versions strip currency from foreign returns, isolating local-market performance.', 'ETFs & funds', 'Intermediate', null),
  ('etf-042', 'Which is true about "commodity ETFs"?', '["Bonds","Provide exposure to physical or futures-based commodities","Equity only","FX only"]'::jsonb, 1, 'Commodity ETFs hold physical metals or commodity futures — gold, oil, agriculture.', 'ETFs & funds', 'Intermediate', null),
  ('etf-043', 'Which is true about "GLD"?', '["Stock fund","Physical-gold-backed ETF","Bond","Currency"]'::jsonb, 1, 'GLD holds physical gold bullion in vaults.', 'ETFs & funds', 'Intermediate', null),
  ('etf-044', 'Which is true about "oil ETFs" using futures?', '["Track spot directly","Roll futures contracts; contango erodes returns over time","Bond","Stock"]'::jsonb, 1, 'Futures-based commodity ETFs (like USO) face roll-yield drag in contango markets.', 'ETFs & funds', 'Intermediate', null),
  ('etf-045', 'Which is true about "K-1 vs 1099" tax reporting?', '["Identical","Partnership-structured commodity funds issue K-1s; standard ETFs issue 1099s","Always K-1","Always 1099"]'::jsonb, 1, 'Some commodity futures funds use partnership structures (K-1); most ETFs use RIC structure (1099).', 'ETFs & funds', 'Intermediate', null),
  ('etf-046', 'Which is true about "thematic ETFs"?', '["Broad market","Concentrated bets on themes (AI, clean energy, robotics)","Treasuries","Cash"]'::jsonb, 1, 'Thematic ETFs target narrative-driven themes — concentrated, often volatile.', 'ETFs & funds', 'Intermediate', null),
  ('etf-047', 'Which is true about "REIT ETFs"?', '["Stock-only","Hold real estate investment trusts; sensitive to rates and property fundamentals","Bond-only","Currency"]'::jsonb, 1, 'REIT ETFs (e.g., VNQ) deliver real-estate exposure with high dividend distributions.', 'ETFs & funds', 'Intermediate', null),
  ('etf-048', 'Which is true about "covered call ETFs"?', '["Pure stock","Hold stocks and write calls for income; cap upside","Bond","Crypto"]'::jsonb, 1, 'Covered-call funds (e.g., JEPI) sell calls to generate yield at the cost of upside.', 'ETFs & funds', 'Intermediate', null),
  ('etf-049', 'Which is true about "buffered/defined outcome ETFs"?', '["Pure equity","Use options to cap upside and buffer downside over an outcome period","Bond","Cash"]'::jsonb, 1, 'Defined-outcome ETFs (e.g., Innovator) shape risk/return profiles using option overlays.', 'ETFs & funds', 'Intermediate', null),
  ('etf-050', 'Which is true about "single-stock ETFs"?', '["Holds index","Single-underlying leveraged/inverse exposure to one stock","Bond","Currency"]'::jsonb, 1, 'Single-stock ETFs (e.g., TSLL) deliver leveraged exposure to one underlying — recent product innovation.', 'ETFs & funds', 'Intermediate', null),
  ('etf-051', 'Which is true about "in-kind creation/redemption"?', '["Cash-based","APs deliver baskets of securities for ETF shares (and vice versa) — tax-efficient","Bond only","Banned"]'::jsonb, 1, 'In-kind transactions avoid the fund realizing taxable gains — a structural ETF advantage.', 'ETFs & funds', 'Advanced', null),
  ('etf-052', 'Which is true about "heartbeat trades"?', '["Random","Strategic AP-driven trades to flush low-basis securities — controversial tax tactic","Banned","Tax event"]'::jsonb, 1, 'Heartbeat trades use in-kind redemptions to refresh basis without distributing gains — under SEC scrutiny.', 'ETFs & funds', 'Advanced', null),
  ('etf-053', 'Which is true about "premium/discount to NAV" in stressed markets?', '["Always zero","Can widen significantly when underlying markets become illiquid","Banned","Cash only"]'::jsonb, 1, 'During credit/liquidity stress (e.g., March 2020), ETF prices can diverge meaningfully from NAV.', 'ETFs & funds', 'Advanced', null),
  ('etf-054', 'Which is true about "NAV vs iNAV"?', '["Identical","NAV is end-of-day; iNAV is intraday estimate of underlying value","No difference","Bond only"]'::jsonb, 1, 'iNAV provides intraday NAV estimates to help arbitrage, though it''s an approximation.', 'ETFs & funds', 'Advanced', null),
  ('etf-055', 'Which is true about "the ETF Rule 6c-11"?', '["Banned ETFs","SEC rule streamlining ETF creation/redemption and product approval","Tax law","Bond regulation"]'::jsonb, 1, 'Adopted in 2019, Rule 6c-11 standardized ETF operations and accelerated launches.', 'ETFs & funds', 'Advanced', null),
  ('etf-056', 'Which is true about "securities lending revenue" sharing?', '["Always full","Lending revenue may be partially shared with fund holders, offsetting fees","Zero","Equity only"]'::jsonb, 1, 'Some ETFs share lending income with investors, lowering effective expense ratios.', 'ETFs & funds', 'Advanced', null),
  ('etf-057', 'Which is true about "swap-based ETFs"?', '["Hold securities directly","Use total-return swaps for exposure — counterparty risk introduced","Cash-only","Banned"]'::jsonb, 1, 'Synthetic ETFs use swaps for tracking but introduce counterparty risk on the swap dealer.', 'ETFs & funds', 'Advanced', null),
  ('etf-058', 'Which is true about "physical vs synthetic replication"?', '["Same","Physical holds the actual securities; synthetic uses derivatives","Always synthetic","Always physical"]'::jsonb, 1, 'European ETFs often use synthetic replication; US ETFs predominantly use physical replication.', 'ETFs & funds', 'Advanced', null),
  ('etf-059', 'Which is true about "sampling vs full replication"?', '["Identical","Sampling holds a representative subset; full replication holds every constituent","Always full","Always sampling"]'::jsonb, 1, 'Sampling reduces costs/turnover; full replication minimizes tracking error — tradeoffs apply.', 'ETFs & funds', 'Advanced', null),
  ('etf-060', 'Which is true about "liquidity mismatch" in bond ETFs?', '["No issue","ETF shares can trade more liquidly than underlying bonds — stress test for redemptions","Equity issue","Tax issue"]'::jsonb, 1, 'Bond ETFs offer intraday liquidity but underlying bonds can be illiquid — risk in stress.', 'ETFs & funds', 'Advanced', null),
  ('etf-061', 'Which is true about "ETF arbitrage breakdown"?', '["Never breaks","In stress, AP capacity or underlying liquidity can fail — premiums/discounts widen","Always perfect","Crypto-only"]'::jsonb, 1, 'Arbitrage requires functioning underlying markets; severe stress can disable it temporarily.', 'ETFs & funds', 'Advanced', null),
  ('etf-062', 'Which is true about "fund of funds" (FoF)?', '["Single fund","Funds investing primarily in other funds — adds layered fees","Bond","Cash"]'::jsonb, 1, 'FoFs invest in other funds; layering can stack expense ratios.', 'ETFs & funds', 'Advanced', null),
  ('etf-063', 'Which is true about "interval funds"?', '["Liquid daily","Allow periodic (e.g., quarterly) redemptions; hold less-liquid assets","Stocks-only","Always closed"]'::jsonb, 1, 'Interval funds compromise between mutual funds and CEFs — limited periodic liquidity for illiquid assets.', 'ETFs & funds', 'Advanced', null),
  ('etf-064', 'Which is true about "BDCs" (business development companies)?', '["Equity only","Closed-end funds investing in private mid-market companies (debt + equity)","Treasury","Crypto"]'::jsonb, 1, 'BDCs provide retail exposure to middle-market private credit and equity.', 'ETFs & funds', 'Advanced', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('etf-065', 'Which is true about "interval funds" liquidity terms?', '["Daily redemption","Quarterly or other periodic redemption windows with caps","Hourly","Annual only"]'::jsonb, 1, 'Interval funds typically offer 5-25% periodic redemption windows on a schedule.', 'ETFs & funds', 'Advanced', null),
  ('etf-066', 'Which is true about "private equity ETFs"?', '["Direct PE","Liquid proxies via PE-listed firms (KKR, BX) or PE-themed indexes","Closed","Banned"]'::jsonb, 1, 'Listed-PE ETFs hold publicly-traded private equity sponsors, not direct private holdings.', 'ETFs & funds', 'Advanced', null),
  ('etf-067', 'Which is true about "tokenized fund shares"?', '["Banned","Emerging blockchain-based representations of fund shares — regulatory in progress","Always crypto","Public-only"]'::jsonb, 1, 'Tokenized fund shares are an emerging structure; regulatory frameworks are developing.', 'ETFs & funds', 'Advanced', null),
  ('tec-001', 'What is technical analysis?', '["Studying financials","Studying historical price and volume to forecast price moves","Tax analysis","Bond pricing"]'::jsonb, 1, 'Technical analysis uses price/volume patterns to inform trading decisions.', 'Technical analysis', 'Basic', null),
  ('tec-002', 'What does a candlestick chart show?', '["Volume only","Open, high, low, close per period","Just close","Just high/low"]'::jsonb, 1, 'Each candle shows OHLC for the period — quick visual of price action.', 'Technical analysis', 'Basic', null),
  ('tec-003', 'What is a moving average?', '["Random average","Average price over a fixed lookback window","Volume measure","Bond yield"]'::jsonb, 1, 'Moving averages smooth price by averaging over recent periods.', 'Technical analysis', 'Basic', null),
  ('tec-004', 'What is the SMA?', '["Stock market analysis","Simple Moving Average — equal weights across the window","Specialized momentum","Always 50-day"]'::jsonb, 1, 'SMA equally weights each price in the window.', 'Technical analysis', 'Basic', null),
  ('tec-005', 'What is the EMA?', '["Equal moving average","Exponential Moving Average — weights recent prices more heavily","Same as SMA","Bond average"]'::jsonb, 1, 'EMA emphasizes recent data, reacting faster to changes.', 'Technical analysis', 'Basic', null),
  ('tec-006', 'What is support?', '["Resistance level","Price level where buying interest historically emerges","Sell signal","High volume"]'::jsonb, 1, 'Support is a price where demand tends to slow declines.', 'Technical analysis', 'Basic', null),
  ('tec-007', 'What is resistance?', '["Support","Price level where selling tends to cap rallies","Always buy","Low volume"]'::jsonb, 1, 'Resistance is a price where supply tends to cap further gains.', 'Technical analysis', 'Basic', null),
  ('tec-008', 'What is a trendline?', '["Random line","Line connecting series of highs or lows to identify a trend","Volume","Open"]'::jsonb, 1, 'Trendlines visually identify direction by linking successive lows (uptrend) or highs (downtrend).', 'Technical analysis', 'Basic', null),
  ('tec-009', 'Which is true about "breakouts"?', '["Always reverse","Price moving above resistance (or below support) with conviction","Random","Bond signal"]'::jsonb, 1, 'Breakouts occur when price decisively pierces support or resistance levels.', 'Technical analysis', 'Basic', null),
  ('tec-010', 'Which is true about volume in TA?', '["Ignored","Confirms moves — breakouts on heavy volume are more credible","Bond-only","Random"]'::jsonb, 1, 'High volume confirms moves; thin volume breakouts often fail.', 'Technical analysis', 'Basic', null),
  ('tec-011', 'What is the 50-day moving average?', '["Random","Average of the last 50 daily closes","Random window","Volume measure"]'::jsonb, 1, 'The 50-day SMA is a widely-followed medium-term trend indicator.', 'Technical analysis', 'Beginner', null),
  ('tec-012', 'What is the 200-day moving average?', '["50-day","Average of the last 200 daily closes — long-term trend gauge","Random","Bond"]'::jsonb, 1, 'The 200-day SMA is widely watched as a long-term trend filter.', 'Technical analysis', 'Beginner', null),
  ('tec-013', 'What is a "golden cross"?', '["50-day SMA crosses ABOVE 200-day — bullish signal","Random","Bear signal","Volume measure"]'::jsonb, 0, 'Golden cross is the 50-day rising through the 200-day — interpreted as bullish.', 'Technical analysis', 'Beginner', null),
  ('tec-014', 'What is a "death cross"?', '["50-day SMA crosses BELOW 200-day — bearish signal","Bullish","Volume","Random"]'::jsonb, 0, 'Death cross is the bearish mirror — 50-day cuts under the 200-day.', 'Technical analysis', 'Beginner', null),
  ('tec-015', 'What is RSI?', '["Relative Strength Index — momentum oscillator, 0-100 scale","Index name","Bond yield","Random"]'::jsonb, 0, 'RSI measures speed of price changes; usually >70 overbought, <30 oversold.', 'Technical analysis', 'Beginner', null),
  ('tec-016', 'Which is true about RSI > 70?', '["Oversold","Often labeled overbought — may suggest pullback potential","No info","Bond signal"]'::jsonb, 1, 'RSI > 70 is commonly seen as overbought, signaling potential mean reversion.', 'Technical analysis', 'Beginner', null),
  ('tec-017', 'Which is true about RSI < 30?', '["Overbought","Often labeled oversold — may suggest bounce potential","No info","Bond signal"]'::jsonb, 1, 'RSI < 30 is commonly seen as oversold.', 'Technical analysis', 'Beginner', null),
  ('tec-018', 'What is MACD?', '["Moving Average Convergence/Divergence — trend-following momentum indicator","Bond","Stock pair","Random"]'::jsonb, 0, 'MACD compares short and long EMAs to spot momentum shifts.', 'Technical analysis', 'Beginner', null),
  ('tec-019', 'Which is true about MACD crossover above signal line?', '["Bearish","Often interpreted as bullish momentum signal","Random","Bond"]'::jsonb, 1, 'MACD crossing above its signal line is read as a bullish trigger.', 'Technical analysis', 'Beginner', null),
  ('tec-020', 'What are Bollinger Bands?', '["Random","Moving average ± multiple of standard deviation — volatility envelope","Bond strategy","Always 10%"]'::jsonb, 1, 'Bollinger Bands plot price relative to volatility — width signals regime changes.', 'Technical analysis', 'Beginner', null),
  ('tec-021', 'Which is true about "bands tightening"?', '["High volatility","Low volatility — often precedes expansion","Random","Bond"]'::jsonb, 1, 'Narrowing Bollinger bands signal low volatility; expansion typically follows.', 'Technical analysis', 'Beginner', null),
  ('tec-022', 'What is a chart pattern "head and shoulders"?', '["Bullish always","Reversal pattern: three peaks with middle highest, neckline as support","Volume","Bond"]'::jsonb, 1, 'H&S is a classic top-reversal pattern — break of the neckline signals trend change.', 'Technical analysis', 'Beginner', null),
  ('tec-023', 'What is a "double top"?', '["Bullish","Two failed attempts at a resistance — bearish reversal","Volume","Random"]'::jsonb, 1, 'Double tops form when a level rejects twice — often signaling a reversal lower.', 'Technical analysis', 'Beginner', null),
  ('tec-024', 'What is a "double bottom"?', '["Bearish","Two successful tests of support — often signals reversal higher","Volume","Random"]'::jsonb, 1, 'Double bottoms suggest the downtrend has exhausted and an upward reversal may follow.', 'Technical analysis', 'Beginner', null),
  ('tec-025', 'What is a "flag" pattern?', '["Pure reversal","Brief consolidation in a strong trend, typically continuing in the trend direction","Bond","Volume"]'::jsonb, 1, 'Flags are short pause patterns that usually resolve in the prior trend''s direction.', 'Technical analysis', 'Beginner', null),
  ('tec-026', 'What is a "pennant"?', '["Same as flag","Symmetrical triangle consolidation; usually continuation","Reversal","Volume"]'::jsonb, 1, 'Pennants are like flags but with converging trendlines — continuation patterns.', 'Technical analysis', 'Beginner', null),
  ('tec-027', 'What is a "gap"?', '["Same as breakout","Discontinuous jump in price between two periods","Random","Volume"]'::jsonb, 1, 'Gaps occur when price opens significantly above/below the prior close.', 'Technical analysis', 'Beginner', null),
  ('tec-028', 'Which is true about "gap-and-go"?', '["Always reverses","Gap up at open followed by continued upward movement","Bond","Random"]'::jsonb, 1, 'Gap-and-go traders aim to ride strong opening momentum.', 'Technical analysis', 'Beginner', null),
  ('tec-029', 'Which is true about "gap fills"?', '["Always immediate","Markets often (but not always) trade back to fill prior gaps","Always at close","Bond"]'::jsonb, 1, 'Gap fills are a common technical phenomenon, though not guaranteed.', 'Technical analysis', 'Beginner', null),
  ('tec-030', 'Which is true about "volume profile"?', '["Same as RSI","Volume traded at each price level — reveals significant prices","Random","Bond"]'::jsonb, 1, 'Volume-at-price reveals where most trading interest exists — key support/resistance candidates.', 'Technical analysis', 'Beginner', null),
  ('tec-031', 'What is VWAP?', '["Random","Volume-weighted average price intraday — institutional reference","Bond yield","RSI variant"]'::jsonb, 1, 'VWAP gives a daily volume-weighted reference price often used by institutions.', 'Technical analysis', 'Intermediate', null),
  ('tec-032', 'Which is true about "trading above VWAP"?', '["Always bearish","Often interpreted as bullish positioning","No meaning","Bond signal"]'::jsonb, 1, 'Trading above VWAP is generally seen as bullish; below as bearish.', 'Technical analysis', 'Intermediate', null),
  ('tec-033', 'What is ATR?', '["Average True Range — measures daily price range/volatility","Index","Bond","Random"]'::jsonb, 0, 'ATR captures average volatility — useful for sizing positions and stops.', 'Technical analysis', 'Intermediate', null),
  ('tec-034', 'Which is true about stochastic oscillator?', '["Trend follow","Compares closing price to range over period; oscillates 0-100","Volume","Bond"]'::jsonb, 1, 'Stochastics compare close vs recent range — overbought/oversold signal.', 'Technical analysis', 'Intermediate', null),
  ('tec-035', 'What is an "engulfing candle"?', '["Same as doji","Candle whose body fully engulfs prior candle''s body — reversal signal","Tax tool","Random"]'::jsonb, 1, 'Engulfing candles often mark short-term trend changes.', 'Technical analysis', 'Intermediate', null),
  ('tec-036', 'What is a "doji"?', '["Tall candle","Candle with very small body — indecision","Always bullish","Bond"]'::jsonb, 1, 'Doji candles signal indecision; context determines whether reversal or continuation.', 'Technical analysis', 'Intermediate', null),
  ('tec-037', 'What is a "hammer" candle?', '["Bullish reversal candle with long lower shadow at a downtrend low","Bearish","Random","Bond"]'::jsonb, 0, 'Hammers form at lows — long lower wicks suggest buyers stepped in.', 'Technical analysis', 'Intermediate', null),
  ('tec-038', 'What is a "shooting star"?', '["Bullish","Bearish reversal candle at uptrend high with long upper wick","Random","Bond"]'::jsonb, 1, 'Shooting stars signal failed rallies — sellers rejected higher prices.', 'Technical analysis', 'Intermediate', null),
  ('tec-039', 'Which is true about "Fibonacci retracements"?', '["Random levels","Common retracement levels (23.6%, 38.2%, 50%, 61.8%, 78.6%) used as support/resistance","Bond yield","Volume"]'::jsonb, 1, 'Fib retracements provide reference levels traders watch for support during pullbacks.', 'Technical analysis', 'Intermediate', null),
  ('tec-040', 'Which is true about "Elliott wave theory"?', '["Pure science","Pattern-based theory positing 5-wave impulse + 3-wave correction structures","Bond strategy","Random"]'::jsonb, 1, 'Elliott Wave is a pattern recognition framework; popular but subjective.', 'Technical analysis', 'Intermediate', null),
  ('tec-041', 'Which is true about "divergence" between price and RSI?', '["Random","Price makes new high but RSI doesn''t (or vice versa) — possible reversal signal","Volume","Bond"]'::jsonb, 1, 'Divergences hint that momentum is weakening even as price continues — often precede reversals.', 'Technical analysis', 'Intermediate', null),
  ('tec-042', 'Which is true about "trendline breaks"?', '["Always continue","Often signal trend change; require confirmation","Bond","Random"]'::jsonb, 1, 'Trendline breaks attract attention; confirmation (volume, retests) increases reliability.', 'Technical analysis', 'Intermediate', null),
  ('tec-043', 'Which is true about "market profile"?', '["Same as RSI","Time-price-opportunity histogram identifying value areas and balance ranges","Bond","Random"]'::jsonb, 1, 'Market profile breaks the session into time-price segments to identify acceptance/rejection.', 'Technical analysis', 'Intermediate', null),
  ('tec-044', 'Which is true about "sector rotation indicators"?', '["Random","Track relative strength among sectors to identify leadership shifts","Bond","Volume"]'::jsonb, 1, 'Relative strength among sectors reveals where capital is flowing — important context.', 'Technical analysis', 'Intermediate', null),
  ('tec-045', 'Which is true about "relative strength"?', '["Random ratio","Price ratio between two assets to gauge outperformance","Bond yield","RSI"]'::jsonb, 1, 'Relative strength compares an asset''s performance against a benchmark — different from RSI.', 'Technical analysis', 'Intermediate', null),
  ('tec-046', 'Which is true about "breakout failures"?', '["Always continue","Failed breakouts often reverse sharply (\"head fake\")","Bond","Random"]'::jsonb, 1, 'Failed breakouts can produce strong reversals as trapped traders unwind.', 'Technical analysis', 'Intermediate', null),
  ('tec-047', 'Which is true about "volume preceding price" in tops?', '["Always","Often: volume divergence accompanies major tops","Never","Bond"]'::jsonb, 1, 'Volume often peaks before price at major tops — a classic warning sign.', 'Technical analysis', 'Intermediate', null),
  ('tec-048', 'Which is true about "ADX" indicator?', '["Volume","Average Directional Index — measures trend strength, not direction","Bond","Stock pair"]'::jsonb, 1, 'ADX measures trend strength (0-100); +DI/-DI lines give direction.', 'Technical analysis', 'Intermediate', null),
  ('tec-049', 'Which is true about "Ichimoku cloud"?', '["RSI variant","Multi-line system showing trend, support/resistance, momentum in one view","Volume","Bond"]'::jsonb, 1, 'Ichimoku combines several indicators into a comprehensive trend system.', 'Technical analysis', 'Intermediate', null),
  ('tec-050', 'Which is true about "Wyckoff method"?', '["Always bullish","Framework analyzing accumulation/distribution phases by smart money","Bond","Volume only"]'::jsonb, 1, 'Wyckoff analyzes price/volume to identify institutional accumulation/distribution patterns.', 'Technical analysis', 'Intermediate', null),
  ('tec-051', 'Which is true about "point and figure charts"?', '["Time-based","Filter out small moves; built on column reversals — time-agnostic","Bond","Volume"]'::jsonb, 1, 'P&F charts filter noise by plotting only meaningful price moves, ignoring time.', 'Technical analysis', 'Advanced', null),
  ('tec-052', 'Which is true about "Kagi charts"?', '["Time-based","Reversal-based line chart; ignores time, focuses on price reversals","Bond","Random"]'::jsonb, 1, 'Kagi charts emphasize trend changes based on reversal magnitudes.', 'Technical analysis', 'Advanced', null),
  ('tec-053', 'Which is true about "renko bricks"?', '["Time-based","Bricks built only on minimum price moves; ignores time","Bond","Volume"]'::jsonb, 1, 'Renko charts filter time, drawing fixed-size bricks on each meaningful price move.', 'Technical analysis', 'Advanced', null),
  ('tec-054', 'Which is true about "market internals" (e.g., TICK, TRIN)?', '["Always misleading","Real-time breadth indicators measuring buying/selling pressure across stocks","Bond","Random"]'::jsonb, 1, 'TICK, TRIN, advance/decline lines measure intraday market breadth — useful context.', 'Technical analysis', 'Advanced', null),
  ('tec-055', 'Which is true about "advance-decline line"?', '["Random","Cumulative net advancing minus declining stocks — broad market health","Bond","FX"]'::jsonb, 1, 'A-D lines reveal whether rallies are broad or driven by a few names — divergences warn.', 'Technical analysis', 'Advanced', null),
  ('tec-056', 'Which is true about "McClellan oscillator"?', '["Random","Momentum measure of advancing vs declining stocks","Bond","Volume"]'::jsonb, 1, 'McClellan oscillator filters A-D data to highlight breadth turns.', 'Technical analysis', 'Advanced', null),
  ('tec-057', 'Which is true about "put-call ratio" as sentiment indicator?', '["Always bullish","High put/call may indicate excessive fear (contrarian bullish); low may indicate complacency","Always bearish","Bond"]'::jsonb, 1, 'Sentiment indicators like P/C ratio are often used contrarian — extremes mark turns.', 'Technical analysis', 'Advanced', null),
  ('tec-058', 'Which is true about "VIX term structure inversions"?', '["Common","Backwardation signals near-term fear; often precedes stabilization","No info","Bond"]'::jsonb, 1, 'VIX backwardation typically marks stress; resolution often comes shortly after.', 'Technical analysis', 'Advanced', null),
  ('tec-059', 'Which is true about "intermarket analysis"?', '["Single asset","Compare bonds, stocks, currencies, commodities to gauge market context","Bond only","Random"]'::jsonb, 1, 'Intermarket analysis reads relationships across asset classes to inform decisions.', 'Technical analysis', 'Advanced', null),
  ('tec-060', 'Which is true about "chart patterns reliability" in modern markets?', '["Bullet-proof","Algorithmic flows have weakened some classic patterns; require confirmation","Always","Never"]'::jsonb, 1, 'Modern algo activity can blur classic patterns; combining patterns with confirmation matters more.', 'Technical analysis', 'Advanced', null),
  ('tec-061', 'Which is true about "signal vs noise" in TA?', '["Same","Filters and multi-timeframe confirmation help separate trends from noise","Bond","Random"]'::jsonb, 1, 'Effective TA combines multiple timeframes and filters to reduce false signals.', 'Technical analysis', 'Advanced', null),
  ('tec-062', 'Which is true about "system curve fitting"?', '["Always good","Backtests can overfit; out-of-sample tests are essential","Always bad","Bond"]'::jsonb, 1, 'Overfitted strategies look great in-sample but fail forward — out-of-sample testing is critical.', 'Technical analysis', 'Advanced', null),
  ('tec-063', 'Which is true about "walk-forward analysis"?', '["Backtest only","Re-train and validate strategies sequentially through time","Look-ahead","Bond"]'::jsonb, 1, 'Walk-forward simulates live trading by training and testing on sequential out-of-sample data.', 'Technical analysis', 'Advanced', null),
  ('tec-064', 'Which is true about "survivorship bias" in TA backtests?', '["No effect","Using only currently-listed stocks inflates backtest returns","Equal","Random"]'::jsonb, 1, 'Backtests using only survivors miss delisted names — overstating historical returns.', 'Technical analysis', 'Advanced', null),
  ('tec-065', 'Which is true about "transaction cost" assumptions in backtests?', '["Optional","Realistic slippage and fees can erase apparent edges","Always zero","Bond only"]'::jsonb, 1, 'Many "edges" in backtests vanish once realistic costs and slippage are included.', 'Technical analysis', 'Advanced', null),
  ('tec-066', 'Which is true about "mean reversion" vs "momentum" strategies?', '["Same","Mean reversion buys dips; momentum follows trends — both can work in different regimes","Always reversion","Always momentum"]'::jsonb, 1, 'Mean reversion and momentum often coexist; horizon and asset matter.', 'Technical analysis', 'Advanced', null),
  ('tec-067', 'Which is true about "regime detection"?', '["Static","Identifying market state (trending vs choppy) to choose appropriate strategy","Bond","Random"]'::jsonb, 1, 'Regime detection adapts strategy choice to current market behavior.', 'Technical analysis', 'Advanced', null),
  ('cor-001', 'What is a stock split?', '["Issuing new debt","Dividing existing shares into more shares while preserving total value","Buyback","Merger"]'::jsonb, 1, 'Stock splits increase share count proportionally while total value stays constant.', 'Corporate actions', 'Basic', null),
  ('cor-002', 'Which is true about a 2-for-1 split?', '["Doubles total value","Doubles share count; halves per-share price","Halves shares","Random"]'::jsonb, 1, 'In a 2-for-1, each shareholder gets 1 extra share for each held; price halves.', 'Corporate actions', 'Basic', null),
  ('cor-003', 'Which is true about a reverse stock split?', '["Increase shares","Decrease share count, increase price; often done to maintain listing requirements","Cancel shares","Random"]'::jsonb, 1, 'Reverse splits consolidate shares, raising price — often used to stay above $1 minimums.', 'Corporate actions', 'Basic', null),
  ('cor-004', 'Which is true about a cash dividend?', '["Always equity dilution","Company pays cash from earnings/reserves to shareholders","Buyback","Tax credit"]'::jsonb, 1, 'Cash dividends transfer corporate cash to shareholders.', 'Corporate actions', 'Basic', null),
  ('cor-005', 'Which is true about a stock dividend?', '["Cash payment","Distribution of additional shares instead of cash","Bond","Buyback"]'::jsonb, 1, 'Stock dividends give shareholders more shares pro-rata — value-neutral.', 'Corporate actions', 'Basic', null),
  ('cor-006', 'What is the "ex-dividend date"?', '["Payment date","First date a buyer is NOT entitled to the announced dividend","Same as record","Random"]'::jsonb, 1, 'Buying on or after the ex-date forfeits the current dividend.', 'Corporate actions', 'Basic', null),
  ('cor-007', 'What is the "record date"?', '["Same as ex-date","Date used to identify shareholders eligible for the dividend","Pay date","Random"]'::jsonb, 1, 'Holders on the record date are the legal recipients of the dividend.', 'Corporate actions', 'Basic', null),
  ('cor-008', 'What is the "pay date"?', '["Same as ex-date","Date the dividend is actually paid to eligible holders","Record date","Random"]'::jsonb, 1, 'Pay date is when the cash hits the holder''s account.', 'Corporate actions', 'Basic', null),
  ('cor-009', 'What is a stock buyback (share repurchase)?', '["Issuing shares","Company buying its own shares from the market","Stock split","Spin-off"]'::jsonb, 1, 'Buybacks return cash to shareholders while reducing share count.', 'Corporate actions', 'Basic', null),
  ('cor-010', 'What is a merger?', '["IPO","Two companies combining into one","Stock split","Spin-off"]'::jsonb, 1, 'Mergers combine two firms into a single entity, often through stock-for-stock or cash deals.', 'Corporate actions', 'Basic', null),
  ('cor-011', 'What is an acquisition?', '["Merger of equals","One company purchases another and takes ownership","IPO","Spin-off"]'::jsonb, 1, 'Acquisitions occur when one company buys controlling interest in another.', 'Corporate actions', 'Beginner', null),
  ('cor-012', 'What is a "hostile takeover"?', '["Friendly merger","Acquirer pursues target without target board''s consent","IPO","Random"]'::jsonb, 1, 'Hostile takeovers bypass uncooperative target boards via tender offers or proxy fights.', 'Corporate actions', 'Beginner', null),
  ('cor-013', 'What is a "tender offer"?', '["Random offer","Public offer to buy shares directly from existing shareholders at a specified price","Bond offer","IPO"]'::jsonb, 1, 'Tender offers solicit shareholders to sell their shares to the acquirer at a stated price.', 'Corporate actions', 'Beginner', null),
  ('cor-014', 'What is a "proxy fight"?', '["Stock split","Battle for board seats via shareholder votes — common in hostile takeovers","Bond fight","Tax dispute"]'::jsonb, 1, 'Proxy contests recruit shareholder votes to replace board members or change policy.', 'Corporate actions', 'Beginner', null),
  ('cor-015', 'What is a "spin-off"?', '["Merger","Parent distributes a subsidiary to shareholders as a separate company","Buyback","IPO"]'::jsonb, 1, 'Spin-offs create standalone companies, often unlocking value through focus.', 'Corporate actions', 'Beginner', null),
  ('cor-016', 'What is a "carve-out"?', '["Merger","Parent sells a minority stake in subsidiary via IPO","Tender","Buyback"]'::jsonb, 1, 'Carve-outs partially divest a subsidiary while parent retains majority, often pre-cursor to a spin-off.', 'Corporate actions', 'Beginner', null),
  ('cor-017', 'What is a "divestiture"?', '["Acquisition","Selling a portion of the business","IPO","Stock split"]'::jsonb, 1, 'Divestitures dispose of business units — for cash, strategic refocus, or regulatory reasons.', 'Corporate actions', 'Beginner', null),
  ('cor-018', 'What is "goodwill" in an acquisition?', '["Cash bonus","Purchase price minus fair value of identifiable net assets","Brand only","Tax credit"]'::jsonb, 1, 'Goodwill represents the premium paid over net asset value in an acquisition.', 'Corporate actions', 'Beginner', null),
  ('cor-019', 'What is a "poison pill"?', '["Tender offer","Anti-takeover defense diluting hostile acquirers via shareholder rights","IPO","Bond"]'::jsonb, 1, 'Poison pills issue rights that dilute acquirers when they exceed a threshold.', 'Corporate actions', 'Beginner', null),
  ('cor-020', 'What is a "white knight"?', '["Hostile bidder","Friendly acquirer brought in to fend off a hostile takeover","Buyback","Bond"]'::jsonb, 1, 'White knights are preferred friendly bidders that rescue targets from hostile takeovers.', 'Corporate actions', 'Beginner', null),
  ('cor-021', 'What is a "golden parachute"?', '["Stock split","Large severance packages for executives if their company is acquired","Bond","IPO"]'::jsonb, 1, 'Golden parachutes compensate executives for job loss in a change of control.', 'Corporate actions', 'Beginner', null),
  ('cor-022', 'Which is true about "breakup fees"?', '["No penalties","Payment to one party if a deal collapses under specific conditions","Tax credit","Bond"]'::jsonb, 1, 'Breakup fees compensate the would-be counterparty if the deal falls apart for specified reasons.', 'Corporate actions', 'Beginner', null),
  ('cor-023', 'What is an LBO?', '["Stock split","Leveraged buyout — acquisition financed primarily with debt","IPO","Bond"]'::jsonb, 1, 'LBOs use heavy debt to acquire a target, often by private equity sponsors.', 'Corporate actions', 'Beginner', null),
  ('cor-024', 'What is a "management buyout" (MBO)?', '["IPO","Existing management team buys the company","Tender","Spin-off"]'::jsonb, 1, 'MBOs let management acquire the company they run — often with PE backing.', 'Corporate actions', 'Beginner', null),
  ('cor-025', 'What is an IPO?', '["Initial Public Offering — first sale of shares to public","Buyback","Stock split","Bond"]'::jsonb, 0, 'IPOs are a private company''s debut on public exchanges.', 'Corporate actions', 'Beginner', null),
  ('cor-026', 'What is a "direct listing"?', '["Standard IPO","Listing existing shares directly without raising new capital via underwriters","Bond issue","Random"]'::jsonb, 1, 'Direct listings list existing shares without issuing new ones — used by Spotify, Slack, others.', 'Corporate actions', 'Beginner', null),
  ('cor-027', 'What is a "SPAC"?', '["Stock split","Special purpose acquisition company — shell that goes public to find an acquisition","IPO","Bond"]'::jsonb, 1, 'SPACs raise IPO capital with the explicit plan to acquire a private business later.', 'Corporate actions', 'Beginner', null),
  ('cor-028', 'What is a "de-SPAC" transaction?', '["SPAC IPO","SPAC merging with a target, taking it public","Buyback","Bond"]'::jsonb, 1, 'The de-SPAC is when the SPAC merges with its target, completing the public listing.', 'Corporate actions', 'Beginner', null),
  ('cor-029', 'Which is true about IPO "lockup periods"?', '["No lockup","Insiders restricted from selling for typically 90-180 days post-IPO","Indefinite","Bond"]'::jsonb, 1, 'IPO lockups prevent immediate insider selling, expiring 90-180 days after the offering.', 'Corporate actions', 'Beginner', null),
  ('cor-030', 'Which is true about "underwriters" in IPOs?', '["No role","Investment banks pricing, marketing, and selling new issues","Buyers only","Tax preparers"]'::jsonb, 1, 'Underwriters price and place the offering and often stabilize the post-IPO market.', 'Corporate actions', 'Beginner', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('cor-031', 'Which is true about "greenshoe option"?', '["Stock split","Underwriter option to issue extra shares to stabilize price post-IPO","Bond","Buyback"]'::jsonb, 1, 'Greenshoes let underwriters sell up to 15% extra shares to manage demand and stabilize the price.', 'Corporate actions', 'Intermediate', null),
  ('cor-032', 'Which is true about "PIPE" transactions?', '["Public IPO","Private investment in public equity — large investors buy shares directly from a public company","Bond","Spin-off"]'::jsonb, 1, 'PIPEs are private placements with public companies, often used in SPACs and capital raises.', 'Corporate actions', 'Intermediate', null),
  ('cor-033', 'Which is true about "convertible bonds" in M&A?', '["Pure equity","Often used to finance acquisitions; convertible features sweeten terms","Always cash","Random"]'::jsonb, 1, 'Convertibles in M&A let issuers raise cheaper financing with optional equity upside.', 'Corporate actions', 'Intermediate', null),
  ('cor-034', 'Which is true about "stock-for-stock" deals?', '["Cash deal","Target shareholders receive acquirer''s stock; ratio fixed or floating","Bond","Tax credit"]'::jsonb, 1, 'Stock-for-stock deals pay target holders in acquirer shares — exposure shifts to combined company.', 'Corporate actions', 'Intermediate', null),
  ('cor-035', 'Which is true about "all-cash" acquisitions?', '["Stock only","Target shareholders receive cash; clean and certain valuation","Bond","Random"]'::jsonb, 1, 'All-cash deals offer immediate certainty but eliminate future upside in the combined company.', 'Corporate actions', 'Intermediate', null),
  ('cor-036', 'Which is true about "collar" provisions in stock deals?', '["No cushion","Adjust exchange ratio if acquirer stock moves outside specified bands","Tax tool","Random"]'::jsonb, 1, 'Collars stabilize deal economics for the target when the acquirer''s stock fluctuates.', 'Corporate actions', 'Intermediate', null),
  ('cor-037', 'Which is true about "earnouts"?', '["Cash at close","Additional payments tied to post-close performance milestones","Tax credit","Bond"]'::jsonb, 1, 'Earnouts defer part of consideration based on future performance — bridges valuation gaps.', 'Corporate actions', 'Intermediate', null),
  ('cor-038', 'Which is true about "antitrust review"?', '["No review","Regulators review M&A for anticompetitive effects (HSR, EU rules)","Tax review","Bond"]'::jsonb, 1, 'Major deals require antitrust clearance; some are blocked or restructured to satisfy regulators.', 'Corporate actions', 'Intermediate', null),
  ('cor-039', 'Which is true about "deal arbitrage"?', '["Pre-IPO","Buying target shares post-announcement at a discount to deal price","Bond","Random"]'::jsonb, 1, 'Merger arb captures the spread between current target price and announced deal terms.', 'Corporate actions', 'Intermediate', null),
  ('cor-040', 'Which is true about "deal spread"?', '["Always negative","Gap between target trading price and deal price; reflects deal close risk","Equal to dividends","Bond"]'::jsonb, 1, 'Deal spread compensates risk-arb investors for the possibility the deal fails.', 'Corporate actions', 'Intermediate', null),
  ('cor-041', 'Which is true about "break fees"?', '["No fees","Payments owed if the deal breaks under specified conditions","Tax credit","Bond"]'::jsonb, 1, 'Break fees protect both sides against bad-faith deal walks — typically 2-4% of deal value.', 'Corporate actions', 'Intermediate', null),
  ('cor-042', 'Which is true about "reverse termination fees"?', '["Pure tax","Payment from acquirer to target if acquirer walks away","Bond","Random"]'::jsonb, 1, 'Reverse termination fees compensate the target if the acquirer pulls out — common in PE deals.', 'Corporate actions', 'Intermediate', null),
  ('cor-043', 'Which is true about "material adverse change" (MAC) clauses?', '["Always trivial","Permit deal termination if business deteriorates significantly","Tax tool","Bond"]'::jsonb, 1, 'MAC clauses let buyers walk if the target''s business significantly worsens between sign and close.', 'Corporate actions', 'Intermediate', null),
  ('cor-044', 'Which is true about "go-shop" provisions?', '["No competition","Allow target board to actively seek superior bids for a set period","Bond","Tax"]'::jsonb, 1, 'Go-shop provisions let targets solicit competing bids for a limited window post-signing.', 'Corporate actions', 'Intermediate', null),
  ('cor-045', 'Which is true about "fiduciary out" clauses?', '["Locked deal","Target board can accept a superior bid despite signed deal — fulfilling fiduciary duty","Tax tool","Random"]'::jsonb, 1, 'Fiduciary outs let the target board switch to a superior proposal in service of shareholder interest.', 'Corporate actions', 'Intermediate', null),
  ('cor-046', 'Which is true about "stock buybacks vs dividends" — tax treatment?', '["Identical","Buybacks defer taxes (gains taxed on sale); dividends taxed when paid","Always identical","Tax credit"]'::jsonb, 1, 'Buybacks let shareholders defer tax recognition; dividends are immediate taxable income.', 'Corporate actions', 'Intermediate', null),
  ('cor-047', 'Which is true about "Dutch auction" buybacks?', '["Fixed price","Company specifies price range; tenders shares at the lowest accepted price","Same as ASR","Random"]'::jsonb, 1, 'Dutch auctions discover the price at which target shares are tendered — flexible and transparent.', 'Corporate actions', 'Intermediate', null),
  ('cor-048', 'Which is true about "accelerated share repurchase" (ASR)?', '["Slow buyback","Company gets shares immediately from a bank; price settles later","Tax credit","Bond"]'::jsonb, 1, 'ASRs deliver shares upfront; the final price is determined over a forward period.', 'Corporate actions', 'Intermediate', null),
  ('cor-049', 'Which is true about "rights offering"?', '["Tender","Existing shareholders get rights to buy new shares, often at a discount","IPO","Bond"]'::jsonb, 1, 'Rights offerings give existing holders pro-rata access to new shares at a discount.', 'Corporate actions', 'Intermediate', null),
  ('cor-050', 'Which is true about "warrants"?', '["Same as options","Long-dated, company-issued options to buy shares at set strike — often included in deals","Bond","Cash"]'::jsonb, 1, 'Warrants are company-issued long-dated options — common in SPAC packages and convertible deals.', 'Corporate actions', 'Intermediate', null),
  ('cor-051', 'Which is true about "reverse mergers"?', '["IPO","Private company merges with a public shell to go public without traditional IPO","Buyback","Spin-off"]'::jsonb, 1, 'Reverse mergers let private firms go public via existing shells — quicker but less prestigious.', 'Corporate actions', 'Advanced', null),
  ('cor-052', 'Which is true about "recapitalizations"?', '["Stock split","Restructuring capital mix (e.g., debt for equity, or vice versa)","IPO","Random"]'::jsonb, 1, 'Recaps alter the debt/equity mix — often leveraged for shareholder distributions or growth.', 'Corporate actions', 'Advanced', null),
  ('cor-053', 'Which is true about "dividend recapitalization"?', '["Standard dividend","Company borrows to pay a special dividend — common in PE-owned firms","Stock split","Buyback"]'::jsonb, 1, 'Div recaps use new debt to fund a special dividend — sponsor-friendly but increases leverage.', 'Corporate actions', 'Advanced', null),
  ('cor-054', 'Which is true about "split-off" vs "spin-off"?', '["Identical","Split-off lets shareholders choose to exchange parent shares for subsidiary; spin-off is automatic","Always identical","Bond"]'::jsonb, 1, 'Split-offs are elective exchanges; spin-offs distribute new-co shares pro-rata to all parent holders.', 'Corporate actions', 'Advanced', null),
  ('cor-055', 'Which is true about "tracking stock"?', '["Same as common","Equity tracking the performance of a specific business segment within a parent","Bond","Random"]'::jsonb, 1, 'Tracking stocks reflect segment economics while keeping the legal entity unified.', 'Corporate actions', 'Advanced', null),
  ('cor-056', 'Which is true about "Section 338(h)(10) election"?', '["No tax effect","US tax election treating stock purchase as asset purchase","No tax","Random"]'::jsonb, 1, '338(h)(10) provides step-up in basis benefits — common in private deal structures.', 'Corporate actions', 'Advanced', null),
  ('cor-057', 'Which is true about "NOLs in M&A"?', '["Always usable","Net operating loss carryforwards face Section 382 limits after ownership change","Tax-free","Random"]'::jsonb, 1, 'Section 382 limits the use of pre-acquisition NOLs after a change of control.', 'Corporate actions', 'Advanced', null),
  ('cor-058', 'Which is true about "morris trust" structures?', '["Common buyback","Tax-efficient combinations involving spin-off + merger","Direct listing","Random"]'::jsonb, 1, 'Reverse Morris Trust deals combine spin-offs with mergers to achieve tax-free treatment.', 'Corporate actions', 'Advanced', null),
  ('cor-059', 'Which is true about "appraisal rights"?', '["No rights","Dissenting shareholders can demand judicial valuation in certain mergers","Tax credit","Bond"]'::jsonb, 1, 'Appraisal rights allow shareholders who reject a merger to seek a court-determined fair value.', 'Corporate actions', 'Advanced', null),
  ('cor-060', 'Which is true about "Section 13(d)" filings?', '["Tax filing","Required when an investor crosses 5% beneficial ownership","Bond","Random"]'::jsonb, 1, '13(d) discloses 5%+ stakes; passive investors can use 13(g) with less detail.', 'Corporate actions', 'Advanced', null),
  ('cor-061', 'Which is true about "activist shareholders"?', '["Always banned","Investors taking stakes to influence corporate strategy/governance","Tax filers","Bond"]'::jsonb, 1, 'Activist investors push for changes — capital allocation, M&A, governance — to unlock value.', 'Corporate actions', 'Advanced', null),
  ('cor-062', 'Which is true about "poison pill" longevity?', '["Permanent","Typically time-limited (often 1-3 years); shareholders may vote to extend","Forever","Random"]'::jsonb, 1, 'Modern poison pills are often time-limited and subject to shareholder ratification.', 'Corporate actions', 'Advanced', null),
  ('cor-063', 'Which is true about "NOL preservation" via pill?', '["Tax-free","Trigger thresholds set lower to prevent ownership change that would impair NOL usage","Bond","Random"]'::jsonb, 1, 'NOL pills protect tax assets by triggering at low ownership change thresholds.', 'Corporate actions', 'Advanced', null),
  ('cor-064', 'Which is true about "two-tier" tender offers?', '["Single price","Higher price for early tenderers, lower for late — coercive structure","Always banned","Bond"]'::jsonb, 1, 'Two-tier tenders pressure shareholders to tender early — historically used in hostile situations.', 'Corporate actions', 'Advanced', null),
  ('cor-065', 'Which is true about "control premiums" in M&A?', '["Always zero","Acquirers typically pay 20-40% above market for controlling stake","Discount","Random"]'::jsonb, 1, 'Control premiums compensate target shareholders for transferring control.', 'Corporate actions', 'Advanced', null),
  ('cor-066', 'Which is true about "synergies" in acquisitions?', '["Always realized","Often overstated; cost synergies more reliable than revenue synergies","Always cost","Always revenue"]'::jsonb, 1, 'M&A synergy projections frequently disappoint; cost synergies materialize more often than revenue ones.', 'Corporate actions', 'Advanced', null),
  ('cor-067', 'Which is true about "deal premium" effects on acquirer stock?', '["Always positive","Acquirer stocks often decline on announcement reflecting integration risk + premium","Always positive","Random"]'::jsonb, 1, 'Acquirer stocks typically dip on announcement due to integration risk and dilution; targets jump.', 'Corporate actions', 'Advanced', null),
  ('cry-001', 'What is Bitcoin?', '["A stock","A decentralized digital currency on a public blockchain","A central bank product","An ETF"]'::jsonb, 1, 'Bitcoin is the original cryptocurrency, a decentralized digital asset on a public ledger.', 'Crypto', 'Basic', null),
  ('cry-002', 'What is a blockchain?', '["Bank ledger","Distributed digital ledger of transactions secured cryptographically","Centralized DB","Spreadsheet"]'::jsonb, 1, 'A blockchain is an immutable, append-only ledger replicated across nodes.', 'Crypto', 'Basic', null),
  ('cry-003', 'Who created Bitcoin?', '["Vitalik Buterin","Pseudonymous \"Satoshi Nakamoto\"","Elon Musk","Bill Gates"]'::jsonb, 1, 'Bitcoin''s whitepaper was published in 2008 by the pseudonymous Satoshi Nakamoto.', 'Crypto', 'Basic', null),
  ('cry-004', 'What is Ethereum?', '["Same as Bitcoin","Smart-contract-capable blockchain with the native token ETH","Bank","Stock"]'::jsonb, 1, 'Ethereum extends blockchain capabilities with smart contracts and decentralized applications.', 'Crypto', 'Basic', null),
  ('cry-005', 'What is a "wallet" in crypto?', '["Bank account","Software/hardware managing the cryptographic keys needed to access funds","Always centralized","Coin"]'::jsonb, 1, 'Crypto wallets store and manage private keys controlling on-chain funds.', 'Crypto', 'Basic', null),
  ('cry-006', 'What is a private key?', '["Public address","Secret cryptographic key proving ownership of crypto assets","Username","ETF"]'::jsonb, 1, 'Private keys authorize transactions; whoever holds the key controls the funds.', 'Crypto', 'Basic', null),
  ('cry-007', 'What is a public key/address?', '["Same as private key","Identifier others can use to send crypto to you","Hidden","Required password"]'::jsonb, 1, 'Public addresses are like account numbers — share them to receive funds.', 'Crypto', 'Basic', null),
  ('cry-008', 'What is mining (proof of work)?', '["Storing coins","Process of validating transactions and creating new blocks via computation","Centralized signature","Coin sale"]'::jsonb, 1, 'Proof-of-work miners compete to solve cryptographic puzzles, earning newly minted coins as reward.', 'Crypto', 'Basic', null),
  ('cry-009', 'What is proof of stake?', '["Mining","Consensus mechanism where validators stake tokens to participate","Bank validation","Central authority"]'::jsonb, 1, 'PoS replaces compute with capital — validators stake tokens for the right to validate blocks.', 'Crypto', 'Basic', null),
  ('cry-010', 'Bitcoin''s total supply is capped at:', '["10 million","21 million","100 million","Unlimited"]'::jsonb, 1, 'Bitcoin''s protocol hard-caps total supply at 21 million coins.', 'Crypto', 'Basic', null),
  ('cry-011', 'What is a "halving" event in Bitcoin?', '["Hack","Block reward to miners cuts in half every ~4 years","Coin burn","Token issuance"]'::jsonb, 1, 'Bitcoin halvings cut new issuance every 210,000 blocks (~4 years), tightening supply.', 'Crypto', 'Beginner', null),
  ('cry-012', 'What is a stablecoin?', '["Volatile coin","Cryptocurrency designed to maintain stable value, typically pegged to USD","Stock","Bond"]'::jsonb, 1, 'Stablecoins (USDC, USDT) aim to peg to fiat (typically the US dollar).', 'Crypto', 'Beginner', null),
  ('cry-013', 'Which is true about "USDC"?', '["Algorithmic","Fiat-collateralized stablecoin issued by Circle","Unbacked","Stock"]'::jsonb, 1, 'USDC is reserve-backed by fiat and short-term Treasuries, issued by Circle.', 'Crypto', 'Beginner', null),
  ('cry-014', 'Which is true about "USDT"?', '["Stock","Largest stablecoin (Tether), reserves disclosed but historically controversial","ETF","Bond"]'::jsonb, 1, 'Tether is the largest stablecoin by volume; reserve composition has been a recurring concern.', 'Crypto', 'Beginner', null),
  ('cry-015', 'Which stablecoin famously collapsed in May 2022?', '["USDC","TerraUSD (UST)","DAI","USDT"]'::jsonb, 1, 'Algorithmic stablecoin UST de-pegged catastrophically alongside LUNA in May 2022.', 'Crypto', 'Beginner', null),
  ('cry-016', 'What is DeFi?', '["Centralized exchange","Decentralized Finance — financial protocols running on blockchains","Bank","Government"]'::jsonb, 1, 'DeFi runs lending, trading, and other financial services as smart contracts on public chains.', 'Crypto', 'Beginner', null),
  ('cry-017', 'What is a DEX?', '["Centralized exchange","Decentralized exchange — peer-to-peer trading via smart contracts","Stock","Bond"]'::jsonb, 1, 'DEXs like Uniswap let users swap tokens directly without an intermediary.', 'Crypto', 'Beginner', null),
  ('cry-018', 'What is a CEX?', '["Decentralized exchange","Centralized cryptocurrency exchange (Coinbase, Binance, etc.)","Wallet","Random"]'::jsonb, 1, 'CEXs are traditional company-run crypto exchanges holding user assets in custody.', 'Crypto', 'Beginner', null),
  ('cry-019', 'Which is true about "gas fees"?', '["Free","Transaction fees paid to network validators","Stable","Random"]'::jsonb, 1, 'Gas fees pay validators for transaction inclusion; they fluctuate with network demand.', 'Crypto', 'Beginner', null),
  ('cry-020', 'Which is true about Ethereum''s "merge" (2022)?', '["Move to mining","Transitioned from proof-of-work to proof-of-stake consensus","Random","Bond"]'::jsonb, 1, 'The 2022 Merge changed Ethereum''s consensus from PoW to PoS, reducing energy use ~99.9%.', 'Crypto', 'Beginner', null),
  ('cry-021', 'What is an NFT?', '["Fungible token","Non-fungible token representing unique digital asset","Always currency","Stock"]'::jsonb, 1, 'NFTs are unique on-chain tokens — typically representing digital art, collectibles, or other unique items.', 'Crypto', 'Beginner', null),
  ('cry-022', 'What is "yield farming"?', '["Stocks","Earning rewards by providing liquidity or staking in DeFi protocols","Bond","Random"]'::jsonb, 1, 'Yield farming routes capital through DeFi protocols to earn fees, interest, and token rewards.', 'Crypto', 'Beginner', null),
  ('cry-023', 'What is a "smart contract"?', '["Legal contract","Self-executing code on a blockchain enforcing agreement terms","Bond","Stock"]'::jsonb, 1, 'Smart contracts execute pre-programmed logic on-chain — no human intermediary.', 'Crypto', 'Beginner', null),
  ('cry-024', 'Which is true about Bitcoin ETFs (spot)?', '["Banned","SEC approved spot Bitcoin ETFs in January 2024","Available since 2010","Always closed"]'::jsonb, 1, 'After years of rejections, spot BTC ETFs (IBIT, FBTC, etc.) launched in January 2024.', 'Crypto', 'Beginner', null),
  ('cry-025', 'Which is true about Ethereum ETFs (spot)?', '["Banned","SEC approved spot ETH ETFs in 2024","Never","Random"]'::jsonb, 1, 'Spot ETH ETFs were approved and began trading in 2024 after BTC ETFs.', 'Crypto', 'Beginner', null),
  ('cry-026', 'Which is true about "cold storage"?', '["Online wallet","Storing keys offline (hardware wallet, paper) for security","Cloud","Bank"]'::jsonb, 1, 'Cold storage keeps keys offline — much safer than hot wallets connected to the internet.', 'Crypto', 'Beginner', null),
  ('cry-027', 'Which is true about "hot wallets"?', '["Offline","Connected to the internet — convenient but more vulnerable","Always safest","Random"]'::jsonb, 1, 'Hot wallets allow quick transactions but expose keys to online threats.', 'Crypto', 'Beginner', null),
  ('cry-028', 'Which is true about "seed phrases"?', '["Optional","Human-readable backup of wallet keys; lose it = lose access","Public info","Random"]'::jsonb, 1, 'Seed phrases (typically 12 or 24 words) recover wallet keys — must be stored securely.', 'Crypto', 'Beginner', null),
  ('cry-029', 'Which is true about "public blockchain transparency"?', '["Private","On-chain transactions are publicly viewable; addresses are pseudonymous","Hidden","Encrypted"]'::jsonb, 1, 'Public blockchains are transparent — anyone can see transactions; identities are pseudonymous.', 'Crypto', 'Beginner', null),
  ('cry-030', 'Which is true about "crypto custody"?', '["Same everywhere","Choices include self-custody, exchanges, qualified custodians — each with tradeoffs","Always self","Bank only"]'::jsonb, 1, 'Custody options range from fully self-custodied to qualified institutional custodians — security/convenience tradeoffs differ.', 'Crypto', 'Beginner', null),
  ('cry-031', 'Which is true about Bitcoin''s monetary policy?', '["Centralized","Hard-coded supply schedule with diminishing issuance via halvings","Random","Same as USD"]'::jsonb, 1, 'Bitcoin issuance follows a fixed schedule cutting in half every ~4 years until ~2140.', 'Crypto', 'Intermediate', null),
  ('cry-032', 'Which is true about "layer 2" scaling?', '["On-chain only","Off-chain or rollup solutions improving throughput while inheriting base-layer security","Random","Bond"]'::jsonb, 1, 'Layer 2s like Optimism, Arbitrum, and Lightning batch transactions to scale base layers.', 'Crypto', 'Intermediate', null),
  ('cry-033', 'Which is true about "rollups" (optimistic vs ZK)?', '["Same","Optimistic assume validity (fraud proofs); ZK use validity proofs","Banned","Random"]'::jsonb, 1, 'Optimistic rollups defer validity checks; ZK rollups use cryptographic proofs upfront.', 'Crypto', 'Intermediate', null),
  ('cry-034', 'Which is true about "miner extractable value" (MEV)?', '["Always zero","Value extractable by reordering/inserting transactions in a block","Tax","Random"]'::jsonb, 1, 'MEV is the value miners/validators can extract by reordering or front-running transactions.', 'Crypto', 'Intermediate', null),
  ('cry-035', 'Which is true about "flash loans"?', '["Long-dated loan","Uncollateralized loan repaid in the same transaction","Bond","Random"]'::jsonb, 1, 'Flash loans require repayment in the same transaction; used in arbitrage and exploits.', 'Crypto', 'Intermediate', null),
  ('cry-036', 'Which is true about "AMM" (automated market maker)?', '["Order book","Algorithmic pricing using liquidity pools (e.g., Uniswap x*y=k)","CEX","Random"]'::jsonb, 1, 'AMMs use formulas like constant product to price swaps from liquidity pools.', 'Crypto', 'Intermediate', null),
  ('cry-037', 'Which is true about "impermanent loss"?', '["No loss","Loss vs holding when LPs provide liquidity in volatile pairs","Always permanent","Bond"]'::jsonb, 1, 'Impermanent loss occurs to AMM LPs when one token in the pair appreciates significantly.', 'Crypto', 'Intermediate', null),
  ('cry-038', 'Which is true about "liquid staking tokens" (LSTs)?', '["Locked staking","Tokenized representation of staked assets, freely tradable (e.g., stETH)","Centralized","Random"]'::jsonb, 1, 'LSTs let stakers retain liquidity while earning staking rewards.', 'Crypto', 'Intermediate', null),
  ('cry-039', 'Which is true about "DAO"?', '["Centralized firm","Decentralized Autonomous Organization — governance via on-chain voting","Bond","Random"]'::jsonb, 1, 'DAOs coordinate decisions via token-weighted voting and smart contract execution.', 'Crypto', 'Intermediate', null),
  ('cry-040', 'Which is true about "smart contract risk"?', '["Zero risk","Bugs/exploits can drain funds; immutable contracts mean errors can be catastrophic","Tax-free","Bond"]'::jsonb, 1, 'Smart contracts are immutable; bugs can result in irreversible loss — auditing is essential.', 'Crypto', 'Intermediate', null),
  ('cry-041', 'Which is true about "oracle problem"?', '["Solved","Bringing off-chain data on-chain reliably is a fundamental challenge","Bond","Random"]'::jsonb, 1, 'Oracles bridge off-chain data to smart contracts but introduce trust and manipulation risks.', 'Crypto', 'Intermediate', null),
  ('cry-042', 'Which is true about "front-running" in DeFi?', '["Banned","Bots can see pending transactions and submit competing trades — MEV exploitation","Impossible","Bond"]'::jsonb, 1, 'Public mempools allow bots to front-run transactions for profit — sandwich attacks are a common MEV strategy.', 'Crypto', 'Intermediate', null),
  ('cry-043', 'Which is true about "on-chain analytics"?', '["Hidden","Public blockchains enable transparent flow analysis (Glassnode, Nansen)","Banned","Bond"]'::jsonb, 1, 'On-chain analytics firms parse blockchain data to derive market and behavioral insights.', 'Crypto', 'Intermediate', null),
  ('cry-044', 'Which is true about "Bitcoin Lightning Network"?', '["Bond","Layer-2 payment channel network enabling fast/cheap BTC transfers","Random","Same as Ethereum"]'::jsonb, 1, 'Lightning Network enables off-chain BTC payments with on-chain settlement.', 'Crypto', 'Intermediate', null),
  ('cry-045', 'Which is true about "sidechains"?', '["Same chain","Separate chains connected via two-way pegs (e.g., Polygon PoS, Liquid)","Random","Bond"]'::jsonb, 1, 'Sidechains run independently with bridge mechanisms allowing asset transfers.', 'Crypto', 'Intermediate', null),
  ('cry-046', 'Which is true about "bridge" hacks?', '["Rare","Major source of crypto losses — bridge contracts hold large pools and are frequent targets","Banned","Bond"]'::jsonb, 1, 'Cross-chain bridges have been hit by some of the largest exploits in crypto history (Ronin, Wormhole).', 'Crypto', 'Intermediate', null),
  ('cry-047', 'Which is true about "market cap" rankings in crypto?', '["Stable","Constantly shifting; major projects (BTC, ETH) dominate; long tail volatile","Stable","Bond"]'::jsonb, 1, 'Crypto market caps are volatile; mid/small-caps can swing dramatically.', 'Crypto', 'Intermediate', null),
  ('cry-048', 'Which is true about "correlation" of crypto with stocks?', '["Always zero","Correlation has increased over time, especially during risk-off periods","Negative","Random"]'::jsonb, 1, 'Crypto correlations with risk assets have risen, particularly with Nasdaq, in recent years.', 'Crypto', 'Intermediate', null),
  ('cry-049', 'Which is true about "crypto winters"?', '["Bull markets","Multi-quarter bear markets where prices fall sharply and activity slows","Always brief","Bond"]'::jsonb, 1, 'Crypto winters are periods of deep, prolonged drawdowns across the asset class.', 'Crypto', 'Intermediate', null),
  ('cry-050', 'Which is true about "institutional crypto adoption"?', '["No interest","Growing — spot ETFs, custody products, hedge fund allocations","Banned","Random"]'::jsonb, 1, 'Institutional adoption has accelerated, especially after spot ETF approvals.', 'Crypto', 'Intermediate', null),
  ('cry-051', 'Which is true about "zero-knowledge proofs" in crypto?', '["Always reveal","Allow proving knowledge without revealing the data itself — basis for ZK-rollups","Random","Bond"]'::jsonb, 1, 'ZK proofs verify statements without revealing underlying inputs — powerful for privacy and scaling.', 'Crypto', 'Advanced', null),
  ('cry-052', 'Which is true about "finality" in blockchains?', '["Same everywhere","Probabilistic (PoW) vs deterministic (BFT-style PoS) settlement guarantees","Random","Bond"]'::jsonb, 1, 'PoW chains offer probabilistic finality; PoS chains often provide near-deterministic finality.', 'Crypto', 'Advanced', null),
  ('cry-053', 'Which is true about "validator slashing" in PoS?', '["No penalty","Validators can lose staked tokens for misbehavior (double-signing, downtime)","Tax","Bond"]'::jsonb, 1, 'Slashing penalizes malicious or careless validators by burning a portion of their stake.', 'Crypto', 'Advanced', null),
  ('cry-054', 'Which is true about "restaking" (e.g., EigenLayer)?', '["Single use","Staked ETH used to secure additional services via shared security","Tax","Bond"]'::jsonb, 1, 'Restaking lets stakers extend security to other protocols, earning extra rewards (and risk).', 'Crypto', 'Advanced', null),
  ('cry-055', 'Which is true about "MEV-Boost" and PBS?', '["Same as old","Separates block builders from proposers to limit centralization risks from MEV","Banned","Bond"]'::jsonb, 1, 'Proposer-builder separation (PBS) was designed to mitigate MEV centralization pressure on validators.', 'Crypto', 'Advanced', null),
  ('cry-056', 'Which is true about "AMM v3" concentrated liquidity?', '["Old design","LPs choose price ranges, increasing capital efficiency","Centralized","Random"]'::jsonb, 1, 'Concentrated liquidity (Uniswap v3) lets LPs allocate liquidity in specific price bands for greater fee capture.', 'Crypto', 'Advanced', null),
  ('cry-057', 'Which is true about "crypto regulation" status (2025)?', '["Settled","Evolving and jurisdictionally fragmented; stablecoin and securities classification key issues","Banned globally","Random"]'::jsonb, 1, 'Crypto regulation continues to evolve; securities classification (Howey test) and stablecoin rules are key fronts.', 'Crypto', 'Advanced', null),
  ('cry-058', 'Which is true about "FTX collapse" (Nov 2022)?', '["Bull catalyst","Exchange insolvency exposed misuse of customer funds; major contagion event","Stable","Bond"]'::jsonb, 1, 'FTX''s collapse revealed massive customer-fund misappropriation and triggered industry-wide stress.', 'Crypto', 'Advanced', null),
  ('cry-059', 'Which is true about "proof of reserves"?', '["Always available","Cryptographic attestations that an exchange holds claimed assets — post-FTX standard","Banned","Random"]'::jsonb, 1, 'PoR systems aim to verify exchange solvency on-chain; methods vary in rigor.', 'Crypto', 'Advanced', null),
  ('cry-060', 'Which is true about "CBDC"?', '["Crypto","Central Bank Digital Currency — digital fiat issued by central banks","DeFi","Random"]'::jsonb, 1, 'CBDCs are digital fiat — distinct from crypto in being centrally issued and government-backed.', 'Crypto', 'Advanced', null),
  ('cry-061', 'Which is true about "crypto and AML/KYC"?', '["No requirements","Exchanges must comply with AML/KYC similar to TradFi","Banned","Random"]'::jsonb, 1, 'Centralized exchanges must implement AML/KYC; DeFi compliance remains an evolving regulatory frontier.', 'Crypto', 'Advanced', null),
  ('cry-062', 'Which is true about "Bitcoin as digital gold" thesis?', '["Identical fundamentals","Argues BTC''s scarce supply + portability makes it a digital store of value","Same as ETH","Tax"]'::jsonb, 1, 'The digital-gold thesis emphasizes BTC''s hard-capped supply and portability as macro hedges.', 'Crypto', 'Advanced', null),
  ('cry-063', 'Which is true about "crypto volatility" vs stocks?', '["Equal","Historically much higher than equities, though slowly compressing as market matures","Lower","Random"]'::jsonb, 1, 'Crypto remains substantially more volatile than equities, though volatility has trended lower over cycles.', 'Crypto', 'Advanced', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('cry-064', 'Which is true about "halving" impact historically?', '["Always neutral","Past halvings have preceded multi-year bull cycles (with confounding factors)","Negative","Bond"]'::jsonb, 1, 'Halvings have historically coincided with subsequent rallies, though attribution is uncertain.', 'Crypto', 'Advanced', null),
  ('cry-065', 'Which is true about "tokenization of real-world assets" (RWA)?', '["Banned","Bringing assets like Treasuries on-chain for programmability and 24/7 access","Stocks only","Random"]'::jsonb, 1, 'RWAs (e.g., tokenized Treasuries) are an emerging trend bridging TradFi and DeFi.', 'Crypto', 'Advanced', null),
  ('cry-066', 'Which is true about "smart contract upgradability"?', '["Always immutable","Some contracts include proxy/upgrade patterns introducing centralization tradeoffs","Banned","Random"]'::jsonb, 1, 'Upgrade patterns (proxies, governance) trade immutability for flexibility — security considerations apply.', 'Crypto', 'Advanced', null),
  ('cry-067', 'Which is true about "on-chain order books"?', '["Common","Less common than AMMs due to gas costs; some L2s and appchains use them","Always cheap","Random"]'::jsonb, 1, 'On-chain order books are rare due to gas overhead; AMMs dominate, though L2s/appchains experiment with CLOBs.', 'Crypto', 'Advanced', null),
  ('beh-001', 'What is behavioral finance?', '["Pure math","Study of how psychology affects financial decisions","Tax rules","Bond pricing"]'::jsonb, 1, 'Behavioral finance examines how cognitive and emotional biases shape investor behavior.', 'Behavioral finance', 'Basic', null),
  ('beh-002', 'What is "loss aversion"?', '["Risk seeking","Losses feel ~2× more painful than equivalent gains feel good","Always rational","Random"]'::jsonb, 1, 'Kahneman & Tversky''s prospect theory: losses loom larger than gains psychologically.', 'Behavioral finance', 'Basic', null),
  ('beh-003', 'What is "confirmation bias"?', '["Open-minded thinking","Seeking info that confirms existing beliefs, ignoring contrary evidence","Random","Mathematical"]'::jsonb, 1, 'Confirmation bias filters new information to reinforce prior views — a critical investing pitfall.', 'Behavioral finance', 'Basic', null),
  ('beh-004', 'What is "recency bias"?', '["Long-term focus","Overweighting recent events when forming expectations","Always rational","Random"]'::jsonb, 1, 'Recency bias makes investors extrapolate recent performance — chasing tops and selling bottoms.', 'Behavioral finance', 'Basic', null),
  ('beh-005', 'What is "herd behavior"?', '["Independent thinking","Following the crowd — buying when others buy, selling when others sell","Always rational","Random"]'::jsonb, 1, 'Herding drives bubbles and crashes — moving with the crowd feels safe but is often costly.', 'Behavioral finance', 'Basic', null),
  ('beh-006', 'What is "overconfidence bias"?', '["Realistic assessment","Overestimating one''s own skill, knowledge, or accuracy","Always cautious","Random"]'::jsonb, 1, 'Overconfidence leads to excessive trading, under-diversification, and underestimated risks.', 'Behavioral finance', 'Basic', null),
  ('beh-007', 'What is "anchoring"?', '["No reference","Fixating on a specific reference point (e.g., purchase price) when making decisions","Random","Always rational"]'::jsonb, 1, 'Anchoring biases decisions toward an initial reference — like refusing to sell below cost basis.', 'Behavioral finance', 'Basic', null),
  ('beh-008', 'What is "sunk cost fallacy"?', '["Forward-looking","Continuing a bad investment because of past costs already incurred","Always rational","Random"]'::jsonb, 1, 'Sunk costs shouldn''t influence future decisions — but emotionally, they often do.', 'Behavioral finance', 'Basic', null),
  ('beh-009', 'What is "availability heuristic"?', '["Comprehensive analysis","Judging probability by how easily examples come to mind","Mathematical","Random"]'::jsonb, 1, 'Vivid recent events feel more probable than they actually are — distorts risk perception.', 'Behavioral finance', 'Basic', null),
  ('beh-010', 'What is the "disposition effect"?', '["Sell winners, hold losers","Tendency to sell winners too early and hold losers too long","Always rational","Random"]'::jsonb, 1, 'The disposition effect contradicts the optimal tax/behavior of cutting losers and letting winners run.', 'Behavioral finance', 'Basic', null),
  ('beh-011', 'What is FOMO?', '["Calm planning","Fear of missing out — buying because others are profiting","Always rational","Random"]'::jsonb, 1, 'FOMO drives investors to chase rallies, often near tops.', 'Behavioral finance', 'Beginner', null),
  ('beh-012', 'What is "panic selling"?', '["Calm liquidation","Emotional dumping during sharp declines, often locking in losses","Rational rebalancing","Tax planning"]'::jsonb, 1, 'Panic selling typically realizes losses near bottoms — the worst time to sell.', 'Behavioral finance', 'Beginner', null),
  ('beh-013', 'What is "endowment effect"?', '["Equal valuation","Valuing assets more highly simply because you own them","Always rational","Random"]'::jsonb, 1, 'The endowment effect explains reluctance to part with owned assets even at fair market value.', 'Behavioral finance', 'Beginner', null),
  ('beh-014', 'What is "mental accounting"?', '["Single account","Treating money differently based on its source or designation","Always rational","Tax accounting"]'::jsonb, 1, 'Mental accounting separates money psychologically — "tax refund" feels different from salary.', 'Behavioral finance', 'Beginner', null),
  ('beh-015', 'What is "framing effect"?', '["No framing effect","Same information presented differently produces different decisions","Random","Mathematical"]'::jsonb, 1, 'Framing — 90% survival rate vs 10% mortality — changes choices despite identical content.', 'Behavioral finance', 'Beginner', null),
  ('beh-016', 'What is "hindsight bias"?', '["Forward thinking","Believing past events were more predictable than they actually were","Always rational","Random"]'::jsonb, 1, 'Hindsight bias makes us overestimate our ability to have predicted past outcomes.', 'Behavioral finance', 'Beginner', null),
  ('beh-017', 'What is "narrative fallacy"?', '["Pure data","Constructing stories to explain random events — gives false sense of understanding","Always rational","Random"]'::jsonb, 1, 'Narrative fallacy turns noise into causation — humans crave coherent stories even when none exists.', 'Behavioral finance', 'Beginner', null),
  ('beh-018', 'What is "home bias"?', '["Global allocation","Over-allocating to domestic assets relative to their global weight","Always rational","Random"]'::jsonb, 1, 'Home bias leads US investors to over-own US stocks and underweight international diversification.', 'Behavioral finance', 'Beginner', null),
  ('beh-019', 'What is "familiarity bias"?', '["Diverse holdings","Preferring familiar investments (employer stock, local companies)","Always rational","Random"]'::jsonb, 1, 'Familiarity bias concentrates portfolios in known names — often correlated with one''s own income/risks.', 'Behavioral finance', 'Beginner', null),
  ('beh-020', 'What is "action bias"?', '["Patience","Preferring action over inaction even when waiting would be optimal","Always rational","Random"]'::jsonb, 1, 'Action bias drives unnecessary trading during volatility, often worsening outcomes.', 'Behavioral finance', 'Beginner', null),
  ('beh-021', 'What is "status quo bias"?', '["Change-friendly","Tendency to stick with current state even when change would be better","Always rational","Random"]'::jsonb, 1, 'Status quo bias keeps people in suboptimal allocations (e.g., not enrolling in 401(k)) due to inertia.', 'Behavioral finance', 'Beginner', null),
  ('beh-022', 'What is "regret aversion"?', '["Risk taking","Avoiding decisions that might cause future regret — often inducing inaction","Always rational","Random"]'::jsonb, 1, 'Regret aversion prevents action that could turn out badly — even when expected value is positive.', 'Behavioral finance', 'Beginner', null),
  ('beh-023', 'What is "optimism bias"?', '["Realistic","Overestimating positive outcomes for oneself","Pessimistic","Random"]'::jsonb, 1, 'Optimism bias inflates expected returns and underestimates personal risks.', 'Behavioral finance', 'Beginner', null),
  ('beh-024', 'What is "self-attribution bias"?', '["External credit","Crediting wins to skill, losses to bad luck or external factors","Random","Tax"]'::jsonb, 1, 'Self-attribution bias prevents learning — wins feel earned, losses feel like bad luck.', 'Behavioral finance', 'Beginner', null),
  ('beh-025', 'What is "hot hand fallacy"?', '["Random outcomes","Believing recent success predicts continued success beyond what statistics support","Realistic","Random"]'::jsonb, 1, 'Hot hand fallacy extrapolates streaks; many empirical studies show patterns are weaker than perceived.', 'Behavioral finance', 'Beginner', null),
  ('beh-026', 'What is "gambler''s fallacy"?', '["Independent events","Believing past random outcomes affect future independent outcomes (\"red is due\")","Always rational","Random"]'::jsonb, 1, 'Gambler''s fallacy misunderstands independence — flipping heads doesn''t make tails more likely next.', 'Behavioral finance', 'Beginner', null),
  ('beh-027', 'What is "present bias"?', '["Long-term planning","Overvaluing immediate rewards vs future ones (impatience)","Always rational","Random"]'::jsonb, 1, 'Present bias drives underfunding retirement — immediate consumption beats deferred gains psychologically.', 'Behavioral finance', 'Beginner', null),
  ('beh-028', 'What is "hyperbolic discounting"?', '["Constant discount rate","Steeper discounting of near-term rewards vs distant ones","Always rational","Random"]'::jsonb, 1, 'Hyperbolic discounting explains why we''d take $100 now over $110 next week, but $110 in 53 weeks over $100 in 52.', 'Behavioral finance', 'Beginner', null),
  ('beh-029', 'What is "social proof"?', '["Independent","Looking to others'' behavior as evidence of correctness","Always rational","Random"]'::jsonb, 1, 'Social proof drives crowd-following behavior — momentum and bubbles are partly social-proof phenomena.', 'Behavioral finance', 'Beginner', null),
  ('beh-030', 'What is "authority bias"?', '["Critical thinking","Over-weighting opinions from perceived experts/authorities","Always rational","Random"]'::jsonb, 1, 'Authority bias makes us accept guru recommendations without sufficient skepticism.', 'Behavioral finance', 'Beginner', null),
  ('beh-031', 'Which is true about "prospect theory"?', '["Linear utility","People weight gains and losses asymmetrically, with reference points and probability distortions","Always linear","Random"]'::jsonb, 1, 'Prospect theory (Kahneman/Tversky) describes how people actually evaluate risky choices.', 'Behavioral finance', 'Intermediate', null),
  ('beh-032', 'Which is true about "prospect theory" probability weighting?', '["Linear","People overweight small probabilities and underweight large ones","Always linear","Random"]'::jsonb, 1, 'Probability weighting explains lottery participation and insurance — small probabilities feel bigger than they are.', 'Behavioral finance', 'Intermediate', null),
  ('beh-033', 'Which is true about "narrow framing"?', '["Holistic view","Evaluating individual investments in isolation instead of portfolio context","Always rational","Random"]'::jsonb, 1, 'Narrow framing leads to suboptimal portfolio decisions because individual position analysis ignores diversification.', 'Behavioral finance', 'Intermediate', null),
  ('beh-034', 'Which is true about "myopic loss aversion"?', '["Long-term focus","Frequent portfolio checking increases perceived losses, lowering equity allocation","Always rational","Random"]'::jsonb, 1, 'Daily portfolio checking surfaces losses ~half the time — reducing risk-bearing capacity through emotional response.', 'Behavioral finance', 'Intermediate', null),
  ('beh-035', 'Which is true about "equity premium puzzle"?', '["No puzzle","Historical equity returns exceed what standard models predict — partly explained by loss aversion","Always negative","Random"]'::jsonb, 1, 'Mehra-Prescott''s puzzle: the equity risk premium is hard to justify under standard utility models; behavioral factors help close the gap.', 'Behavioral finance', 'Intermediate', null),
  ('beh-036', 'Which is true about "overtrading"?', '["Profit boost","Empirically associated with lower net returns due to costs and behavioral errors","Always profitable","Random"]'::jsonb, 1, 'Barber & Odean''s classic study: investors who trade most underperform by largest margin.', 'Behavioral finance', 'Intermediate', null),
  ('beh-037', 'Which is true about "gender differences" in investing?', '["No difference","Studies find women tend to trade less and outperform men on average","Always equal","Random"]'::jsonb, 1, 'Studies (notably Barber & Odean) show women trade less frequently and achieve better net returns on average.', 'Behavioral finance', 'Intermediate', null),
  ('beh-038', 'Which is true about "professional vs retail" performance?', '["Pros always win","Professionals show many of the same biases as retail; net of fees most underperform indexes","Pros never err","Random"]'::jsonb, 1, 'Professional managers are subject to similar biases; most active funds underperform passive after fees.', 'Behavioral finance', 'Intermediate', null),
  ('beh-039', 'Which is true about "contrarian investing"?', '["Always wrong","Buying when others are fearful (and vice versa) — exploits behavioral excesses","Always right","Random"]'::jsonb, 1, 'Contrarian strategies attempt to profit from extremes of fear and greed.', 'Behavioral finance', 'Intermediate', null),
  ('beh-040', 'Which is true about "performance chasing" by retail?', '["Outperforms","Buying high-recent-performance funds after they''ve already run; usually underperforms","Always profitable","Random"]'::jsonb, 1, 'Performance chasing leads to buying funds after peaks — empirical underperformance follows.', 'Behavioral finance', 'Intermediate', null),
  ('beh-041', 'Which is true about "investor behavior gap"?', '["Zero","Investor returns lag fund returns due to mistimed buying/selling","Always positive","Random"]'::jsonb, 1, 'Morningstar studies show a persistent 1-2% annual gap between fund returns and investor experience.', 'Behavioral finance', 'Intermediate', null),
  ('beh-042', 'Which is true about "sentiment indicators"?', '["Useless","Often contrarian: extreme bullish sentiment correlates with poor forward returns","Always trend follow","Random"]'::jsonb, 1, 'Sentiment indicators (AAII, put/call, Investors Intelligence) often work as contrarian signals at extremes.', 'Behavioral finance', 'Intermediate', null),
  ('beh-043', 'Which is true about "bubbles"?', '["Rational pricing","Often driven by combinations of euphoria, momentum, and easy credit","Always engineered","Random"]'::jsonb, 1, 'Asset bubbles arise from feedback loops of belief, momentum, and credit availability.', 'Behavioral finance', 'Intermediate', null),
  ('beh-044', 'Which is true about "Minsky moments"?', '["Stable equilibrium","Sudden collapse of asset prices after long period of speculative borrowing","Government action","Random"]'::jsonb, 1, 'Minsky moments come at the end of cycles when leverage accumulates and confidence reverses sharply.', 'Behavioral finance', 'Intermediate', null),
  ('beh-045', 'Which is true about "Kahneman''s System 1 vs System 2"?', '["Same speed","System 1 fast/intuitive, System 2 slow/deliberate — most decisions use System 1","Always rational","Random"]'::jsonb, 1, 'Kahneman''s dual-process framework: most decisions are quick System 1; investing demands more System 2.', 'Behavioral finance', 'Intermediate', null),
  ('beh-046', 'Which is true about "affective forecasting" errors?', '["Accurate prediction","Overestimating how much future events will affect emotional state","Always exact","Random"]'::jsonb, 1, 'Affective forecasting errors make us misjudge how good winning or how bad losing will feel.', 'Behavioral finance', 'Intermediate', null),
  ('beh-047', 'Which is true about "choice overload"?', '["More options always better","Too many options can paralyze decision-making and reduce satisfaction","Always rational","Random"]'::jsonb, 1, 'Iyengar/Lepper: too many choices reduce decision satisfaction — applies to 401(k) plan menus.', 'Behavioral finance', 'Intermediate', null),
  ('beh-048', 'Which is true about "nudges" in retirement plans?', '["Useless","Auto-enrollment and auto-escalation dramatically increase savings","Mandate","Tax"]'::jsonb, 1, 'Auto-enrollment converts inertia from a barrier into a driver of higher savings.', 'Behavioral finance', 'Intermediate', null),
  ('beh-049', 'Which is true about "target-date fund" adoption?', '["Forced","Default option in many plans; reduces extreme allocation choices","Banned","Random"]'::jsonb, 1, 'TDFs as 401(k) default options leverage status-quo bias toward better allocations.', 'Behavioral finance', 'Intermediate', null),
  ('beh-050', 'Which is true about "financial literacy" and outcomes?', '["No effect","Higher financial literacy correlates with better savings/retirement outcomes","Always equal","Random"]'::jsonb, 1, 'Literacy is correlated with better financial outcomes; education improves planning behaviors.', 'Behavioral finance', 'Intermediate', null),
  ('beh-051', 'Which is true about "limits to arbitrage"?', '["Always works","Capital constraints, agency issues, and risk can prevent arbitrageurs from closing mispricings","Always fixed","Random"]'::jsonb, 1, 'Shleifer-Vishny: real-world arbitrageurs face constraints that can prevent fully correcting mispricings.', 'Behavioral finance', 'Advanced', null),
  ('beh-052', 'Which is true about "noise traders"?', '["Always informed","Trade on non-information, affecting prices in ways rational arbitrage may not eliminate","Always rational","Random"]'::jsonb, 1, 'Noise trader risk (DeLong et al.) shows non-fundamental traders can persistently move prices.', 'Behavioral finance', 'Advanced', null),
  ('beh-053', 'Which is true about "closed-end fund puzzle"?', '["Trade at NAV","Often trade at persistent discount/premium to NAV — challenges efficient markets","Always at NAV","Random"]'::jsonb, 1, 'Persistent CEF discounts/premiums suggest sentiment plays a real role in pricing.', 'Behavioral finance', 'Advanced', null),
  ('beh-054', 'Which is true about "value premium" behavioral explanations?', '["Pure risk story","Behavioral: investors overreact to bad/good news, mispricing both value and growth stocks","No premium","Random"]'::jsonb, 1, 'Behavioral models attribute the value premium to overreaction to news and slow correction.', 'Behavioral finance', 'Advanced', null),
  ('beh-055', 'Which is true about "momentum" behavioral explanations?', '["Pure random","Underreaction to news + delayed information dissemination can produce momentum","Always luck","Random"]'::jsonb, 1, 'Behavioral models attribute momentum to investor underreaction and slow diffusion of information.', 'Behavioral finance', 'Advanced', null),
  ('beh-056', 'Which is true about "endowment + status quo" combined?', '["Always rational","Creates inertia in portfolios — people leave allocations far from optimal","Always optimal","Random"]'::jsonb, 1, 'The combination explains why many investors leave portfolios in long-stale allocations.', 'Behavioral finance', 'Advanced', null),
  ('beh-057', 'Which is true about "prospect theory and tax-loss harvesting"?', '["Rational","Loss aversion makes investors reluctant to sell losers despite tax benefits","Always rational","Random"]'::jsonb, 1, 'Loss aversion fights against optimal tax-loss harvesting — selling losers feels emotionally costly.', 'Behavioral finance', 'Advanced', null),
  ('beh-058', 'Which is true about "reference-dependent" preferences?', '["Absolute outcomes","Decisions depend on outcomes relative to a reference point, not absolute wealth","Always absolute","Random"]'::jsonb, 1, 'Prospect theory shows people evaluate outcomes vs reference points — gains/losses vs current wealth.', 'Behavioral finance', 'Advanced', null),
  ('beh-059', 'Which is true about "probability weighting" extremes?', '["Linear","People overweight tiny probabilities (lottery) and underweight near-certain","Always linear","Random"]'::jsonb, 1, 'This explains demand for both lottery tickets and insurance — distorted probability weights at extremes.', 'Behavioral finance', 'Advanced', null),
  ('beh-060', 'Which is true about "investor sentiment indices" as predictors?', '["Useless","Some sentiment factors have shown predictive power for forward equity returns","Always predict","Random"]'::jsonb, 1, 'Baker-Wurgler sentiment index and others show contrarian predictive ability for certain stock characteristics.', 'Behavioral finance', 'Advanced', null),
  ('beh-061', 'Which is true about "mood and markets"?', '["No relationship","Weather, sports outcomes, daylight have been linked to market behavior in studies","Strict rationality","Random"]'::jsonb, 1, 'Behavioral studies find subtle mood/weather effects on markets — small but persistent.', 'Behavioral finance', 'Advanced', null),
  ('beh-062', 'Which is true about "echo chambers" in modern markets?', '["Diverse view","Social media reinforces narrow views; amplifies herd behavior","Always rational","Random"]'::jsonb, 1, 'Social media accelerates group-think; viral narratives can move markets faster than fundamentals warrant.', 'Behavioral finance', 'Advanced', null),
  ('beh-063', 'Which is true about "meme stocks" 2021?', '["Pure fundamentals","Behavioral coordination + short squeezes producing extreme dislocations","Random","Bond"]'::jsonb, 1, 'Meme stocks demonstrated how coordinated retail action plus short squeezes can drive sharp dislocations.', 'Behavioral finance', 'Advanced', null),
  ('beh-064', 'Which is true about "behavioral coaching" value?', '["Negligible","Advisor behavioral coaching can preserve significant return value over a lifetime","No value","Random"]'::jsonb, 1, 'Vanguard research suggests behavioral coaching by advisors adds 1-2%+ in long-run client returns.', 'Behavioral finance', 'Advanced', null),
  ('beh-065', 'Which is true about "rules-based" investing''s appeal?', '["Always emotional","Removes emotion from execution — automates discipline","Always discretionary","Random"]'::jsonb, 1, 'Rules-based strategies (rebalancing rules, DCA) reduce the harm of emotional reactions.', 'Behavioral finance', 'Advanced', null),
  ('beh-066', 'Which is true about "loss aversion intensity" by experience?', '["Equal","More-experienced investors show somewhat less extreme loss aversion","Equal","Random"]'::jsonb, 1, 'Experience can moderate but not eliminate loss aversion; specialized training and habits help.', 'Behavioral finance', 'Advanced', null),
  ('beh-067', 'Which is true about "behavioral alpha"?', '["Pure luck","Returns from exploiting persistent behavioral mispricings — slow and difficult","Always certain","Random"]'::jsonb, 1, 'Behavioral alpha exists but requires discipline to harvest — most arbs fade once well-known.', 'Behavioral finance', 'Advanced', null),
  ('tax-001', 'What is a 401(k)?', '["Pension plan","Employer-sponsored retirement plan with tax advantages","Brokerage","Insurance"]'::jsonb, 1, '401(k)s are employer-sponsored retirement plans with pre-tax (traditional) or post-tax (Roth) contribution options.', 'Taxes & retirement', 'Basic', null),
  ('tax-002', 'What is an IRA?', '["Stock account","Individual Retirement Account — personal tax-advantaged retirement account","Bond","Insurance"]'::jsonb, 1, 'IRAs are personal tax-advantaged retirement accounts outside employer plans.', 'Taxes & retirement', 'Basic', null),
  ('tax-003', 'Which is true about a Traditional IRA?', '["Tax-free now","Contributions may be tax-deductible; withdrawals taxed as income","Tax-free always","Cash account"]'::jsonb, 1, 'Traditional IRAs offer upfront tax deduction (subject to income limits); withdrawals are taxed.', 'Taxes & retirement', 'Basic', null),
  ('tax-004', 'Which is true about a Roth IRA?', '["Pre-tax contributions","Contributions after-tax; qualified withdrawals tax-free","Bond","Brokerage"]'::jsonb, 1, 'Roth IRAs use after-tax dollars but qualified withdrawals are entirely tax-free.', 'Taxes & retirement', 'Basic', null),
  ('tax-005', 'Which is true about "contribution limits" (IRA)?', '["Unlimited","Annual cap set by IRS, plus catch-up if 50+","No limit","Random"]'::jsonb, 1, 'IRAs have annual contribution limits (e.g., $7,000 in 2024) with additional catch-up for 50+.', 'Taxes & retirement', 'Basic', null),
  ('tax-006', 'Which is true about "capital gains taxes"?', '["Same as income","Long-term gains taxed at preferential rates (0/15/20%); short-term at ordinary income rates","Tax-free","Always 28%"]'::jsonb, 1, 'Long-term gains (>1 year holding) qualify for lower preferential rates.', 'Taxes & retirement', 'Basic', null),
  ('tax-007', 'Which is true about "short-term capital gains"?', '["Long preferential rate","Held ≤1 year; taxed as ordinary income","Tax-free","Random"]'::jsonb, 1, 'Short-term gains face ordinary income tax rates — typically higher than long-term.', 'Taxes & retirement', 'Basic', null),
  ('tax-008', 'Which is true about "dividend taxation"?', '["Always tax-free","Qualified dividends taxed at long-term capital gains rates; non-qualified at ordinary","Random","Always tax-free"]'::jsonb, 1, 'Qualified dividends meet IRS rules and get preferential treatment; non-qualified are taxed as income.', 'Taxes & retirement', 'Basic', null),
  ('tax-009', 'Which is true about "tax-loss harvesting"?', '["Generates losses","Selling losing positions to offset capital gains for tax purposes","Random","Always profitable"]'::jsonb, 1, 'Tax-loss harvesting realizes losses to offset gains, reducing tax liability.', 'Taxes & retirement', 'Basic', null),
  ('tax-010', 'What is the "wash sale rule"?', '["No restriction","Can''t claim a tax loss if substantially identical security repurchased within 30 days","Random","Always allowed"]'::jsonb, 1, 'Wash sale rule disallows loss recognition if the security (or substantially identical) is rebought within 30 days.', 'Taxes & retirement', 'Basic', null),
  ('tax-011', 'Which is true about "401(k) employer matching"?', '["No match","Many employers match part of employee contributions — free money","Always 100%","Random"]'::jsonb, 1, 'Employer matches effectively double your contribution up to the match percentage — capture this first.', 'Taxes & retirement', 'Beginner', null),
  ('tax-012', 'Which is true about "vesting"?', '["Always immediate","Employer match may require time before fully owned","Always 1 year","Random"]'::jsonb, 1, 'Vesting schedules can be immediate, graded, or cliff — important when changing jobs.', 'Taxes & retirement', 'Beginner', null),
  ('tax-013', 'What is an HSA?', '["Insurance","Health Savings Account — triple tax-advantaged for medical expenses","Stock account","Random"]'::jsonb, 1, 'HSAs offer pre-tax contributions, tax-free growth, and tax-free medical withdrawals — "triple-tax".', 'Taxes & retirement', 'Beginner', null),
  ('tax-014', 'Which is true about HSA after age 65?', '["Penalty","Non-medical withdrawals allowed; taxed as income (no penalty)","Tax-free","Banned"]'::jsonb, 1, 'After 65, HSA acts like an IRA for non-medical withdrawals — taxed but no penalty.', 'Taxes & retirement', 'Beginner', null),
  ('tax-015', 'Which is true about "Social Security"?', '["Tax-free retirement","Federal retirement benefit funded via payroll taxes","Pension","Random"]'::jsonb, 1, 'Social Security provides retirement, disability, and survivor benefits funded by payroll taxes.', 'Taxes & retirement', 'Beginner', null),
  ('tax-016', 'Which is true about "Roth conversions"?', '["Banned","Moving Traditional IRA to Roth, paying tax on converted amount","Tax-free always","Random"]'::jsonb, 1, 'Roth conversions trigger immediate tax but enable tax-free future growth — strategic in low-income years.', 'Taxes & retirement', 'Beginner', null),
  ('tax-017', 'Which is true about "required minimum distributions" (RMDs)?', '["Optional","Mandatory withdrawals from Traditional IRA/401(k) starting at age 73 (2023 SECURE 2.0)","Always 75","Random"]'::jsonb, 1, 'RMDs ensure tax-deferred accounts eventually get taxed; starts at 73 (rising to 75 in 2033 under SECURE 2.0).', 'Taxes & retirement', 'Beginner', null),
  ('tax-018', 'Which is true about "Roth" RMDs?', '["Same as Traditional","No lifetime RMDs for Roth IRAs (and Roth 401(k)s from 2024)","Always required","Random"]'::jsonb, 1, 'Roth IRAs have no lifetime RMDs; Roth 401(k) RMDs were eliminated starting 2024.', 'Taxes & retirement', 'Beginner', null),
  ('tax-019', 'What is "backdoor Roth"?', '["Banned","Contributing to non-deductible Traditional IRA then converting to Roth (income-limit workaround)","Tax-free","Random"]'::jsonb, 1, 'Backdoor Roth converts a nondeductible Traditional IRA contribution to Roth — bypasses Roth income limits.', 'Taxes & retirement', 'Beginner', null),
  ('tax-020', 'Which is true about "mega backdoor Roth"?', '["Same as backdoor","After-tax 401(k) contributions converted to Roth, large amounts possible","Banned","Random"]'::jsonb, 1, 'Mega backdoor uses after-tax 401(k) contributions + in-plan Roth conversion to add large Roth contributions.', 'Taxes & retirement', 'Beginner', null),
  ('tax-021', 'Which is true about "estimated taxes"?', '["W-2 only","Quarterly tax payments for income without withholding (self-employed, investments)","Random","Yearly only"]'::jsonb, 1, 'Estimated taxes must be paid quarterly to avoid penalties on income without withholding.', 'Taxes & retirement', 'Beginner', null),
  ('tax-022', 'Which is true about "tax brackets"?', '["Flat tax","Progressive — higher portions of income taxed at higher rates (marginal)","Flat 25%","Random"]'::jsonb, 1, 'US uses marginal brackets — only income above each threshold is taxed at the higher rate.', 'Taxes & retirement', 'Beginner', null),
  ('tax-023', 'What is "marginal tax rate"?', '["Average","Tax rate on the next dollar of income","Always 25%","Random"]'::jsonb, 1, 'Marginal rate is the rate on the next dollar — relevant for incremental decisions.', 'Taxes & retirement', 'Beginner', null),
  ('tax-024', 'What is "effective tax rate"?', '["Marginal","Total tax paid divided by total income — overall rate","Always 0","Random"]'::jsonb, 1, 'Effective rate captures the average across all income — usually lower than marginal.', 'Taxes & retirement', 'Beginner', null),
  ('tax-025', 'Which is true about "capital losses"?', '["Tax-free","Can offset capital gains; up to $3,000/year offsets ordinary income; rest carries forward","Random","Always lost"]'::jsonb, 1, 'Capital losses offset gains first, then up to $3,000 of ordinary income annually; excess carries forward.', 'Taxes & retirement', 'Beginner', null),
  ('tax-026', 'Which is true about "municipal bond interest" (federal)?', '["Taxable","Generally exempt from federal income tax","Random","Always taxable"]'::jsonb, 1, 'Muni interest is typically federal tax-free; state treatment varies.', 'Taxes & retirement', 'Beginner', null),
  ('tax-027', 'Which is true about "529 plans"?', '["IRA","Tax-advantaged education savings account","Bond","Insurance"]'::jsonb, 1, '529 plans grow tax-free; withdrawals for qualified education expenses are tax-free.', 'Taxes & retirement', 'Beginner', null),
  ('tax-028', 'Which is true about "step-up in basis"?', '["No step-up","Inherited assets reset to date-of-death value for capital gains purposes","Random","Always 0"]'::jsonb, 1, 'Inherited assets typically receive a stepped-up basis, erasing pre-death appreciation for tax purposes.', 'Taxes & retirement', 'Beginner', null),
  ('tax-029', 'Which is true about "estate tax"?', '["No exemption","Federal exemption ($13M+ in 2024); only applies above threshold","Always 50%","Random"]'::jsonb, 1, 'Federal estate tax has a high exemption indexed for inflation; only large estates owe federal estate tax.', 'Taxes & retirement', 'Beginner', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('tax-030', 'Which is true about "gift tax"?', '["Always due","Annual exclusion (~$18,000/recipient 2024) plus lifetime exemption","Always 0","Random"]'::jsonb, 1, 'Gift tax has annual per-recipient exclusion plus shared lifetime estate/gift exemption.', 'Taxes & retirement', 'Beginner', null),
  ('tax-031', 'Which is true about "NIIT" (Net Investment Income Tax)?', '["No surtax","3.8% surtax on investment income above income thresholds","Banned","Random"]'::jsonb, 1, 'NIIT is a 3.8% Medicare surtax on investment income above thresholds ($200k single, $250k MFJ).', 'Taxes & retirement', 'Intermediate', null),
  ('tax-032', 'Which is true about "AMT" (Alternative Minimum Tax)?', '["No exists","Parallel tax system limiting some deductions; mostly muted after TCJA","Always applies","Random"]'::jsonb, 1, 'AMT runs parallel to regular tax; post-TCJA exemption levels make AMT impact smaller for most filers.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-033', 'Which is true about "ESPP" (Employee Stock Purchase Plan)?', '["Always taxable","Discounted stock purchase via payroll; tax treatment depends on holding period","Random","Banned"]'::jsonb, 1, 'ESPPs allow discounted stock purchases; qualifying dispositions get preferential tax treatment.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-034', 'Which is true about "RSU" taxation?', '["No tax","Taxed as ordinary income at vest (W-2); subsequent sale = capital gains/losses","Always capital","Random"]'::jsonb, 1, 'RSUs are taxed as ordinary income at vesting; later sales trigger capital gains/losses on appreciation/depreciation.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-035', 'Which is true about "ISO" (Incentive Stock Options)?', '["Same as RSU","Preferential tax treatment if holding periods met (1yr from exercise + 2yr from grant)","Always ordinary","Random"]'::jsonb, 1, 'ISOs can qualify for long-term capital gains treatment if specific holding periods are met.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-036', 'Which is true about "NQSO" (Non-qualified Stock Options)?', '["Same as ISO","Spread at exercise taxed as ordinary income; gains thereafter are capital","Always tax-free","Random"]'::jsonb, 1, 'NQSOs trigger ordinary income on the bargain element at exercise; subsequent gains are capital.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-037', 'Which is true about "Section 1202" (QSBS)?', '["Random","Qualified Small Business Stock can exclude up to $10M+ of capital gains under conditions","Always taxed","Banned"]'::jsonb, 1, 'QSBS provides massive capital gains exclusions for qualifying small business stock held 5+ years.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-038', 'Which is true about "1031 exchange"?', '["Stock","Like-kind real estate exchange deferring capital gains","Always taxed","Banned"]'::jsonb, 1, '1031 exchanges defer capital gains tax on real estate when proceeds reinvested into similar property.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-039', 'Which is true about "opportunity zones"?', '["Tax-free","Investments in designated areas defer/reduce capital gains taxes","Random","Banned"]'::jsonb, 1, 'Opportunity Zone investments offer capital gains deferral and potential elimination of QOF appreciation taxes.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-040', 'Which is true about "asset location" strategy?', '["Random placement","Hold tax-inefficient assets in tax-advantaged accounts; tax-efficient in taxable","Identical accounts","Random"]'::jsonb, 1, 'Asset location places assets in account types that minimize taxes overall — bonds in IRAs, ETFs in taxable.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-041', 'Which is true about "tax-efficient withdrawal" ordering?', '["Random","Generally: taxable first, then tax-deferred, then Roth (preserve tax-free growth)","Random","Same"]'::jsonb, 1, 'Conventional advice: withdraw from taxable first, defer tax-advantaged, preserve Roth — but situations vary.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-042', 'Which is true about "Social Security taxation"?', '["Always tax-free","Up to 85% of benefits can be taxable depending on combined income","Always 50%","Random"]'::jsonb, 1, 'SS taxation depends on total income; 0%, 50%, or 85% of benefits may be taxable.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-043', 'Which is true about "early withdrawal penalty" (401k/IRA)?', '["No penalty","10% penalty on withdrawals before 59½ (with some exceptions)","Always 25%","Random"]'::jsonb, 1, 'Early withdrawals before 59½ generally face 10% penalty plus income tax; certain exceptions apply (rule of 55, etc.).', 'Taxes & retirement', 'Intermediate', null),
  ('tax-044', 'Which is true about "rule of 55"?', '["Random rule","If you leave job at 55+, can access 401(k) without 10% penalty","Always 50","Random"]'::jsonb, 1, 'Rule of 55 lets you tap your current employer''s 401(k) penalty-free if separated at 55+.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-045', 'Which is true about "72(t) SEPP"?', '["Banned","Series of substantially equal periodic payments allowing penalty-free IRA withdrawals before 59½","Always penalty","Random"]'::jsonb, 1, '72(t) provides early IRA access via substantially equal periodic payments — strict rules apply.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-046', 'Which is true about "inherited IRA" rules?', '["Same as own","Non-spouse beneficiaries generally have 10-year payout (SECURE Act)","Lifetime","Random"]'::jsonb, 1, 'SECURE Act requires most non-spouse IRA beneficiaries to deplete inherited accounts within 10 years.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-047', 'Which is true about "qualified longevity annuity contract" (QLAC)?', '["Random","Defers a portion of IRA RMDs into a deferred annuity to as late as age 85","Banned","Tax-free"]'::jsonb, 1, 'QLACs let retirees defer income (and RMDs) on a portion of IRA balances into later years.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-048', 'Which is true about "charitable contributions" via QCD?', '["Banned","Qualified Charitable Distribution: IRA-to-charity transfers count toward RMD, tax-excluded","Tax credit","Random"]'::jsonb, 1, 'QCDs let IRA holders 70½+ donate directly to charity, satisfying RMD without recognizing income.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-049', 'Which is true about "donor-advised funds" (DAF)?', '["Stocks","Charitable account funded now (tax deduction); grants distributed over time","Random","Banned"]'::jsonb, 1, 'DAFs receive immediate deduction upon funding, with flexibility on grant timing to charities.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-050', 'Which is true about "tax bracket arbitrage" in retirement?', '["No strategy","Use low-income years to convert/realize gains at lower brackets","Banned","Random"]'::jsonb, 1, 'Bracket-aware planning fills lower brackets via conversions and gain harvesting before SS/RMDs increase income.', 'Taxes & retirement', 'Intermediate', null),
  ('tax-051', 'Which is true about "Section 199A" QBI deduction?', '["No deduction","Up to 20% deduction on qualified business income for pass-through entities","Banned","Random"]'::jsonb, 1, 'QBI deduction provides up to 20% off pass-through business income, subject to limits and phaseouts.', 'Taxes & retirement', 'Advanced', null),
  ('tax-052', 'Which is true about "PFIC" rules?', '["Tax-free","Passive Foreign Investment Companies face punitive US tax treatment for US investors","Always tax-free","Random"]'::jsonb, 1, 'PFIC rules apply harsh taxation to many foreign mutual funds held by US persons — including foreign ETFs.', 'Taxes & retirement', 'Advanced', null),
  ('tax-053', 'Which is true about "FBAR" filing?', '["Voluntary","Required for US persons with foreign accounts aggregating >$10,000","Banned","Always"]'::jsonb, 1, 'FBAR (FinCEN 114) discloses foreign accounts; severe penalties for non-filing.', 'Taxes & retirement', 'Advanced', null),
  ('tax-054', 'Which is true about "Form 8938" (FATCA)?', '["Same as FBAR","Tax form for foreign financial assets above thresholds; separate from FBAR","Tax-free","Random"]'::jsonb, 1, 'Form 8938 reports specified foreign financial assets; coexists with FBAR but distinct.', 'Taxes & retirement', 'Advanced', null),
  ('tax-055', 'Which is true about "GRAT" (Grantor Retained Annuity Trust)?', '["Stock account","Estate planning tool transferring asset appreciation to heirs with reduced gift tax","Random","Tax credit"]'::jsonb, 1, 'GRATs let asset appreciation pass to beneficiaries with minimal gift tax — popular wealth transfer tool.', 'Taxes & retirement', 'Advanced', null),
  ('tax-056', 'Which is true about "irrevocable life insurance trust" (ILIT)?', '["Always taxable","Holds life insurance outside estate to avoid estate tax on death benefit","Random","Tax credit"]'::jsonb, 1, 'ILITs remove life insurance proceeds from the estate, reducing estate tax exposure.', 'Taxes & retirement', 'Advanced', null),
  ('tax-057', 'Which is true about "step transactions" doctrine?', '["No doctrine","IRS may collapse multiple steps into one if they lack independent business purpose","Random","Tax credit"]'::jsonb, 1, 'Step transaction doctrine recharacterizes interrelated steps as a single transaction for tax purposes.', 'Taxes & retirement', 'Advanced', null),
  ('tax-058', 'Which is true about "economic substance" doctrine?', '["Always upheld","Transactions need real economic substance beyond tax benefits — codified post-2010","Always banned","Random"]'::jsonb, 1, 'Economic substance doctrine disallows transactions whose primary purpose is tax avoidance.', 'Taxes & retirement', 'Advanced', null),
  ('tax-059', 'Which is true about "net unrealized appreciation" (NUA)?', '["Standard 401k","Employer stock in 401(k) can be distributed in-kind for preferential capital gains treatment on appreciation","Always ordinary","Random"]'::jsonb, 1, 'NUA strategy distributes appreciated employer stock in-kind, taxing only basis as ordinary, gains at LTCG.', 'Taxes & retirement', 'Advanced', null),
  ('tax-060', 'Which is true about "foreign tax credit"?', '["No credit","Credit for foreign taxes paid, generally limited to US tax on foreign income","Always full","Random"]'::jsonb, 1, 'FTC mitigates double taxation on foreign-source income; subject to limitation calculations.', 'Taxes & retirement', 'Advanced', null),
  ('tax-061', 'Which is true about "tax treaty" benefits?', '["No effect","Reduce withholding rates and clarify tax treatment between countries","Always 0","Random"]'::jsonb, 1, 'Tax treaties reduce withholding on cross-border investment income and clarify residency-based taxation.', 'Taxes & retirement', 'Advanced', null),
  ('tax-062', 'Which is true about "tax-managed funds"?', '["Random fund","Mutual funds explicitly minimizing taxable distributions via lot selection and harvesting","Always tax-free","Random"]'::jsonb, 1, 'Tax-managed funds use specific lot accounting, loss harvesting, and turnover discipline to minimize taxes.', 'Taxes & retirement', 'Advanced', null),
  ('tax-063', 'Which is true about "direct indexing"?', '["Same as ETF","Holding individual stocks in an index for granular tax-loss harvesting","Always taxable","Random"]'::jsonb, 1, 'Direct indexing replicates an index via individual stocks, enabling lot-level loss harvesting beyond ETF-level.', 'Taxes & retirement', 'Advanced', null),
  ('tax-064', 'Which is true about "municipal bond AMT bonds"?', '["Tax-free always","Private-activity munis can be subject to AMT — affects after-tax yield for AMT payers","Random","Always taxable"]'::jsonb, 1, 'Some PAB muni interest is AMT-includible — affecting effective yields for AMT-exposed investors.', 'Taxes & retirement', 'Advanced', null),
  ('tax-065', 'Which is true about "capital gains harvesting" in 0% bracket?', '["Banned","Some taxpayers can realize LTCG at 0% federal rate within bracket","Always 15%","Random"]'::jsonb, 1, 'At lower income levels, long-term gains can be realized federally at 0% — a strategic tool.', 'Taxes & retirement', 'Advanced', null),
  ('tax-066', 'Which is true about "variable annuity" tax treatment?', '["Always tax-free","Tax-deferred growth inside; withdrawals taxed as ordinary income on earnings first (LIFO)","Always LTCG","Random"]'::jsonb, 1, 'Variable annuities defer tax; non-qualified annuity withdrawals follow LIFO with ordinary income treatment on gains.', 'Taxes & retirement', 'Advanced', null),
  ('tax-067', 'Which is true about "529 to Roth IRA" rollover (SECURE 2.0)?', '["Banned","Limited tax-free rollover of leftover 529 funds to Roth IRA (subject to rules)","Always tax-free","Random"]'::jsonb, 1, 'SECURE 2.0 allows up to $35k lifetime rollover from 529 to Roth IRA, subject to ownership/contribution requirements.', 'Taxes & retirement', 'Advanced', null),
  ('rsk-001', 'What is portfolio risk?', '["Pure volatility","Uncertainty about portfolio returns and the chance of loss","Always loss","Random"]'::jsonb, 1, 'Portfolio risk encompasses both volatility and the probability of unfavorable outcomes.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-002', 'What is diversification?', '["Single asset","Spreading investments across assets to reduce idiosyncratic risk","Always rebalance","Random"]'::jsonb, 1, 'Diversification reduces unsystematic (idiosyncratic) risk by holding many uncorrelated assets.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-003', 'Which is true about "systematic risk"?', '["Eliminated by diversification","Market-wide risk that cannot be diversified away","Always zero","Random"]'::jsonb, 1, 'Systematic risk affects the entire market — economic, geopolitical, monetary; cannot be diversified away.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-004', 'Which is true about "unsystematic risk"?', '["Cannot be diversified","Idiosyncratic risk specific to a company/industry — diversifiable","Always systematic","Random"]'::jsonb, 1, 'Unsystematic risk is specific to individual securities and can be reduced via diversification.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-005', 'What is correlation?', '["Identity","Statistical measure of how two assets move together (−1 to +1)","Always positive","Random"]'::jsonb, 1, 'Correlation captures the linear relationship between asset returns, bounded between -1 and +1.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-006', 'Which is true about "lower correlation" in a portfolio?', '["Increases risk","Reduces overall portfolio volatility (when expected returns are positive)","No effect","Random"]'::jsonb, 1, 'Holdings with lower correlations smooth aggregate returns; foundation of diversification.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-007', 'What is asset allocation?', '["Single stock pick","Dividing portfolio across asset classes (stocks, bonds, cash, alternatives)","Always 60/40","Random"]'::jsonb, 1, 'Asset allocation is the strategic mix across asset classes — the dominant driver of long-term portfolio outcomes.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-008', 'Which is true about "strategic asset allocation"?', '["Daily trading","Long-term target weights based on goals/risk tolerance","Tactical","Random"]'::jsonb, 1, 'Strategic allocation sets long-term target weights aligned with goals; rebalanced periodically.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-009', 'Which is true about "tactical asset allocation"?', '["Static","Active short-to-medium-term shifts away from strategic targets to exploit views","Always passive","Random"]'::jsonb, 1, 'Tactical allocation overlays strategic with timely shifts based on valuation, momentum, or macro views.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-010', 'Which is true about "rebalancing"?', '["Always avoid","Restore target weights as market moves drift the allocation","Daily","Random"]'::jsonb, 1, 'Rebalancing trims overweight positions and adds to underweight ones — enforces buy-low, sell-high.', 'Risk & portfolio management', 'Basic', null),
  ('rsk-011', 'Which is true about "60/40 portfolio"?', '["100% stocks","60% stocks, 40% bonds — classic balanced allocation","All bonds","Random"]'::jsonb, 1, 'The 60/40 has been a benchmark balanced portfolio, though correlation regimes can challenge it.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-012', 'Which is true about "volatility" measurement?', '["Average return","Standard deviation of returns — common risk proxy","Always 0","Random"]'::jsonb, 1, 'Volatility (annualized standard deviation) is the most common risk proxy in finance.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-013', 'Which is true about "Sharpe ratio"?', '["Higher = worse","(Return − risk-free) / volatility — risk-adjusted return measure","Always 1","Random"]'::jsonb, 1, 'Sharpe ratio measures excess return per unit of total risk; higher is better.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-014', 'Which is true about "Sortino ratio"?', '["Same as Sharpe","Like Sharpe but uses downside deviation only","Always equal","Random"]'::jsonb, 1, 'Sortino focuses only on downside volatility — penalizes negative deviations rather than total volatility.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-015', 'Which is true about "drawdown"?', '["Volatility","Peak-to-trough decline in portfolio value","Daily moves","Random"]'::jsonb, 1, 'Drawdown measures the largest peak-to-trough decline — important psychological/funding risk metric.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-016', 'Which is true about "max drawdown"?', '["Average loss","Worst peak-to-trough loss over a period","Average daily","Random"]'::jsonb, 1, 'Max drawdown captures the largest experienced loss — informs risk tolerance and capital preservation.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-017', 'Which is true about "risk parity" approach?', '["Equal-dollar weights","Each asset contributes equal risk to portfolio (often using leverage)","Cash-only","Random"]'::jsonb, 1, 'Risk parity allocates capital so each asset contributes equal risk — typically leveraging lower-vol assets.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-018', 'Which is true about "minimum variance" portfolio?', '["Maximum return","Lowest-volatility achievable portfolio for a given universe","Always cash","Random"]'::jsonb, 1, 'Minimum variance portfolios target lowest possible volatility regardless of expected returns.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-019', 'Which is true about "efficient frontier"?', '["Worst portfolios","Set of portfolios offering highest return for each level of risk","Always cash","Random"]'::jsonb, 1, 'The efficient frontier traces optimal risk-return tradeoffs in mean-variance space.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-020', 'Which is true about "liquidity risk"?', '["Always zero","Risk of being unable to sell at fair price quickly","Always 100%","Random"]'::jsonb, 1, 'Liquidity risk is the cost or impossibility of exiting a position quickly without large concessions.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-021', 'Which is true about "credit risk"?', '["Always zero","Risk of borrower default; affects fixed income and counterparty exposures","Always 100%","Random"]'::jsonb, 1, 'Credit risk is the probability of default and consequent loss; central to fixed income.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-022', 'Which is true about "interest rate risk"?', '["Equities only","Bond prices fall when rates rise; longer duration = more rate sensitivity","Always zero","Random"]'::jsonb, 1, 'Interest rate risk hits fixed-income hardest; duration measures the exposure.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-023', 'Which is true about "currency risk" in international investing?', '["Always hedged","FX moves can amplify or offset local-market returns","Always 0","Random"]'::jsonb, 1, 'Foreign currency exposure adds volatility; can be hedged with derivatives or currency-hedged ETFs.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-024', 'Which is true about "inflation risk"?', '["Bonds immune","Erosion of purchasing power; particularly hurts fixed-income returns","Always equity","Random"]'::jsonb, 1, 'Inflation degrades real returns on fixed nominal cash flows; equities and real assets typically fare better.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-025', 'Which is true about "sequence of returns risk"?', '["Order doesn''t matter","Order of returns matters when contributing or withdrawing","Always equal","Random"]'::jsonb, 1, 'With cash flows in/out, return sequence affects ending wealth significantly — early losses during withdrawals damage most.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-026', 'Which is true about "longevity risk"?', '["Always low","Outliving your savings — central retirement planning risk","Always high","Random"]'::jsonb, 1, 'Longevity risk drives the need for risk-managed sustainable withdrawal plans and possibly annuities.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-027', 'Which is true about "concentration risk"?', '["Diversified","Excessive exposure to single position or sector","Always cash","Random"]'::jsonb, 1, 'Concentration risk arises when a portfolio is overweight a few names — common with employer stock.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-028', 'Which is true about "position sizing"?', '["Equal-weight always","How much capital to allocate to each position based on conviction/risk","Random","Always 1%"]'::jsonb, 1, 'Position sizing matches capital allocation to expected return, risk, and overall portfolio impact.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-029', 'Which is true about "stop-loss orders"?', '["Always wise","Pre-set exit triggers; can lock in losses on temporary dips","Always avoid","Random"]'::jsonb, 1, 'Stop-losses limit downside but can also exit at unfavorable temporary lows — trade-offs matter.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-030', 'Which is true about "rebalancing frequency"?', '["Daily best","Common approaches: time-based (quarterly/annual) or threshold-based","Always daily","Random"]'::jsonb, 1, 'Rebalancing rules trade off transaction costs vs drift; quarterly/annual or threshold-based are common.', 'Risk & portfolio management', 'Beginner', null),
  ('rsk-031', 'Which is true about "VaR" (Value at Risk)?', '["Average loss","Estimated maximum loss at given confidence level over a horizon","Profit measure","Random"]'::jsonb, 1, 'VaR estimates the loss not expected to be exceeded over a horizon at a given probability.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-032', 'Which is true about "expected shortfall" (CVaR)?', '["Same as VaR","Average loss in the tail beyond VaR","Always lower","Random"]'::jsonb, 1, 'Expected Shortfall (CVaR) captures average tail loss — more conservative than VaR.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-033', 'Which is true about "stress testing"?', '["No use","Hypothetical extreme scenarios applied to portfolio to estimate losses","Banned","Random"]'::jsonb, 1, 'Stress tests apply historical or hypothetical shocks to gauge portfolio resilience.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-034', 'Which is true about "scenario analysis"?', '["Single point","Evaluating portfolio under multiple market scenarios","Always equal","Random"]'::jsonb, 1, 'Scenario analysis projects multiple plausible outcomes and their portfolio impact.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-035', 'Which is true about "Monte Carlo simulation"?', '["Single path","Stochastic simulation generating thousands of paths to model uncertainty","Deterministic","Random"]'::jsonb, 1, 'Monte Carlo simulations generate many random paths to estimate distribution of outcomes.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-036', 'Which is true about "tail risk"?', '["Common returns","Risk of extreme rare events with large impact","Always certain","Random"]'::jsonb, 1, 'Tail risk encompasses rare, severe events — pandemics, crises, flash crashes.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-037', 'Which is true about "hedging" purposes?', '["Maximize return","Reduce portfolio sensitivity to a specific risk","Always profitable","Random"]'::jsonb, 1, 'Hedging trades expected return for reduced variability of specific exposures.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-038', 'Which is true about "natural hedges"?', '["External insurance","Inherent offsets within a portfolio reducing certain risks","Always external","Random"]'::jsonb, 1, 'Natural hedges arise when positions inherently offset (e.g., US importer with USD revenue/imports).', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-039', 'Which is true about "protective puts"?', '["Always free","Cost premium; cap downside on long positions","Free hedge","Random"]'::jsonb, 1, 'Protective puts insure long positions against drops; cost the premium but cap downside.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-040', 'Which is true about "collar strategy"?', '["Pure long","Sell upside call to fund protective put — limits both upside and downside","Random","Bond"]'::jsonb, 1, 'Collars finance downside protection by selling upside — common in concentrated stock hedging.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-041', 'Which is true about "black swan" preparation?', '["Predictable","Resilience-focused: avoid ruin, position for asymmetric outcomes","Always avoidable","Random"]'::jsonb, 1, 'Black swan preparation focuses on durability and asymmetric exposure — not prediction.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-042', 'Which is true about "barbell strategy"?', '["Concentrated","Combine very safe + very risky assets, avoid medium-risk","All cash","Random"]'::jsonb, 1, 'Barbells (popularized by Taleb) pair safe core with high-risk satellites — convex payoff profile.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-043', 'Which is true about "liquidity premium"?', '["Always zero","Less liquid assets typically demand higher expected returns","Always negative","Random"]'::jsonb, 1, 'Investors demand premium for tying up capital in illiquid investments.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-044', 'Which is true about "factor diversification"?', '["Same as asset diversification","Spreading exposure across return factors (value, momentum, quality, size)","Always cash","Random"]'::jsonb, 1, 'Factor diversification spreads risk across systematic return drivers, not just asset classes.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-045', 'Which is true about "60/40" challenges?', '["Always works","Both stocks and bonds can fall together (e.g., 2022) — correlation can spike","Always uncorrelated","Random"]'::jsonb, 1, 'In 2022 the 60/40 had its worst year in modern history as stocks and bonds fell together — challenging the diversification assumption.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-046', 'Which is true about "all-weather" portfolio?', '["Single asset","Designed for varied economic regimes — diversifies across risk drivers","Always cash","Random"]'::jsonb, 1, 'All-weather (Bridgewater) seeks balanced exposure across growth, inflation, deflation, and stagflation regimes.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-047', 'Which is true about "risk-on vs risk-off" regimes?', '["Same returns","Correlations and asset behavior shift sharply in risk-off — diversification can falter","Always uncorrelated","Random"]'::jsonb, 1, 'In risk-off, correlations spike — safe havens rally, risk assets fall together.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-048', 'Which is true about "alternative investments" purpose?', '["Increase volatility","Provide returns/diversification from non-traditional sources","Same as stocks","Random"]'::jsonb, 1, 'Alternatives (private equity, hedge funds, real assets) aim to diversify and access return streams unavailable in public markets.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-049', 'Which is true about "private equity vs public"?', '["Same liquidity","Illiquid, longer horizons, generally higher fees; potential illiquidity premium","Always lower returns","Random"]'::jsonb, 1, 'PE investments are illiquid and high-fee; capture an illiquidity premium and unique strategies.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-050', 'Which is true about "correlation in crisis"?', '["Stays low","Often spikes — assets fall together (\"everything goes to one\")","Always zero","Random"]'::jsonb, 1, 'Crisis correlations can spike sharply, undermining diversification just when it''s needed most.', 'Risk & portfolio management', 'Intermediate', null),
  ('rsk-051', 'Which is true about "Kelly criterion"?', '["Equal weights","Position-sizing formula maximizing expected log wealth growth","Always 50%","Random"]'::jsonb, 1, 'Kelly sizing optimizes expected geometric growth but is aggressive — most practitioners use a fraction ("half-Kelly").', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-052', 'Which is true about "variance drag"?', '["No effect","Volatile returns compound below their arithmetic mean — penalizes high-vol strategies","Always positive","Random"]'::jsonb, 1, 'Variance drag explains why geometric returns trail arithmetic averages, especially in volatile assets.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-053', 'Which is true about "copulas" in risk modeling?', '["Linear","Capture joint distribution structures beyond linear correlation","Always linear","Random"]'::jsonb, 1, 'Copulas model joint dependence (including tail dependence) beyond what linear correlation captures.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-054', 'Which is true about "tail-dependence"?', '["Always zero","Probability of extreme co-movements; matters for crisis behavior","Always low","Random"]'::jsonb, 1, 'Tail dependence captures how often extreme moves happen together — crucial for risk in crisis regimes.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-055', 'Which is true about "factor exposure" measurement?', '["Always single factor","Regress returns on factor returns to estimate sensitivities","Random","No factors"]'::jsonb, 1, 'Factor analysis decomposes returns into systematic exposures (market, size, value, momentum, etc.).', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-056', 'Which is true about "information ratio"?', '["Total return","Excess return / tracking error — risk-adjusted active manager skill","Always equal","Random"]'::jsonb, 1, 'Information ratio assesses skill at generating consistent alpha relative to a benchmark.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-057', 'Which is true about "alpha decay"?', '["Permanent edge","Alpha typically erodes as it''s discovered and copied","Eternal","Random"]'::jsonb, 1, 'Strategies that produce alpha attract capital and copycats, eroding excess returns over time.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-058', 'Which is true about "capacity" of strategies?', '["Unlimited","Many strategies have capacity limits beyond which alpha decays","Always unlimited","Random"]'::jsonb, 1, 'Strategy capacity constrains AUM that can be deployed before market impact eats returns.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-059', 'Which is true about "funding liquidity" vs "market liquidity"?', '["Identical","Funding is ability to obtain financing; market is ability to trade","Always same","Random"]'::jsonb, 1, 'Funding liquidity (financing access) and market liquidity (transaction ease) interact dangerously in crises.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-060', 'Which is true about "liquidity spirals"?', '["Always linear","Forced selling + collapsing prices reinforce each other in crises","Always controlled","Random"]'::jsonb, 1, 'Brunnermeier-Pedersen liquidity spirals: declining prices trigger margin calls and forced selling — feedback loop.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-061', 'Which is true about "counterparty risk" management?', '["Banned","Collateral, netting, central clearing, and credit limits all mitigate","Always uncovered","Random"]'::jsonb, 1, 'Modern derivatives markets use collateral, netting agreements, and CCPs to limit counterparty exposure.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-062', 'Which is true about "central counterparty" (CCP) role?', '["No interpose","Stands between counterparties, mutualizing some default risk","Same as broker","Random"]'::jsonb, 1, 'CCPs become buyer to every seller and vice versa, reducing bilateral risk via mutualization.', 'Risk & portfolio management', 'Advanced', null)
insert into public.quiz_questions
  (source_key, prompt, choices, correct_index, explanation, category, difficulty, glossary_slug)
values
  ('rsk-063', 'Which is true about "haircut" in collateral?', '["No haircut","Discount to collateral value covering market risk during liquidation","Always 0%","Random"]'::jsonb, 1, 'Haircuts protect the lender by valuing collateral below market — buffer for liquidation losses.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-064', 'Which is true about "leverage" magnification?', '["Reduces risk","Amplifies both returns and losses; risk grows nonlinearly with leverage","No effect","Random"]'::jsonb, 1, 'Leverage magnifies P&L proportionally but risk-of-ruin grows nonlinearly with leverage.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-065', 'Which is true about "liquidity buffers" for portfolios?', '["Always 0","Holding cash/liquid assets to handle redemptions/margin without forced selling","Never","Random"]'::jsonb, 1, 'Liquidity buffers prevent forced selling during stress — vital for funds with redemption obligations.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-066', 'Which is true about "risk budgeting"?', '["Single budget","Allocating risk (not just capital) across strategies/assets","Always equal","Random"]'::jsonb, 1, 'Risk budgeting allocates by risk contribution rather than dollars — clearer view of total portfolio risk exposure.', 'Risk & portfolio management', 'Advanced', null),
  ('rsk-067', 'Which is true about "ergodicity" in investing?', '["Always ergodic","Time-average wealth path can differ from ensemble average — relevant for compounding risk","Always equal","Random"]'::jsonb, 1, 'Non-ergodicity (Peters) shows that individual time paths differ from cross-sectional averages — important under leverage and ruin risk.', 'Risk & portfolio management', 'Advanced', null)
